//! End-to-end integration tests: each generates a crate by spawning the generator binary
//! (`codegen_cmd`), then compiles
//! and CBOR round-trip-tests it (plus wasm build and json-schema build). This is the correctness
//! gate. Golden snapshots of the generated *source* live in `snapshot_tests.rs`.

use crate::tests::gate_cache;
use std::io::Write;

/// Fixture-appended tests compile only inside generated crates, outside the workspace clippy
/// `assertions_on_result_states` deny. Positive Result assertions must unwrap/expect so a red
/// generated-crate run carries the error payload; `is_err()` stays allowed because `unwrap_err()`
/// requires generated Ok types to implement `Debug`, which they do not uniformly derive.
#[test]
fn fixture_appended_tests_do_not_assert_is_ok() {
    let tests_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests");
    let mut fixture_test_files = std::collections::BTreeSet::new();

    for dir_entry in std::fs::read_dir(&tests_root)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", tests_root.display()))
    {
        let dir_entry = dir_entry
            .unwrap_or_else(|e| panic!("cannot read an entry under {}: {e}", tests_root.display()));
        let dir_path = dir_entry.path();
        if !dir_path.is_dir() {
            continue;
        }

        for file_entry in std::fs::read_dir(&dir_path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir_path.display()))
        {
            let file_entry = file_entry.unwrap_or_else(|e| {
                panic!("cannot read an entry under {}: {e}", dir_path.display())
            });
            let file_path = file_entry.path();
            let Some(file_name) = file_path.file_name().and_then(|name| name.to_str()) else {
                continue;
            };
            if file_name.starts_with("tests") && file_name.ends_with(".rs") {
                fixture_test_files.insert(file_path);
            }
        }
    }

    let mut violations = Vec::new();
    for file_path in fixture_test_files {
        let contents = std::fs::read_to_string(&file_path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", file_path.display()));
        for (line_index, line) in contents.lines().enumerate() {
            if line.contains("assert!") && line.contains(".is_ok()") {
                let display_path = file_path
                    .strip_prefix(env!("CARGO_MANIFEST_DIR"))
                    .unwrap_or(&file_path)
                    .display();
                violations.push(format!("{display_path}:{}", line_index + 1));
            }
        }
    }

    assert!(
        violations.is_empty(),
        "fixture-appended tests must unwrap/expect positive Results so failures carry payloads: {}",
        violations.join(", ")
    );
}

/// Name-level docs-contract gate for `docs/docs/command_line_flags.mdx`, sibling in spirit to
/// `src/tests/dsl_position_tests.rs`'s `comment_dsl.mdx` contract: every clap long flag must have
/// a matching `:::info `--flag`` block, and every documented block must still name a real clap
/// flag. This lints flag NAMES only; prose content stays hand-owned and is not checked.
#[test]
fn command_line_flags_mdx_documents_all_clap_long_flags() {
    use clap::CommandFactory;
    use std::collections::BTreeSet;

    let command = crate::cli::Cli::command();
    let clap_flags = command
        .get_arguments()
        .filter_map(|arg| arg.get_long())
        .filter(|name| !matches!(*name, "help" | "version"))
        .map(str::to_owned)
        .collect::<BTreeSet<_>>();

    let docs_path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/docs/docs/command_line_flags.mdx"
    );
    let docs = std::fs::read_to_string(docs_path)
        .unwrap_or_else(|e| panic!("cannot read {docs_path}: {e}"));
    let doc_flags = docs
        .lines()
        .filter_map(|line| {
            line.trim()
                .strip_prefix(":::info `--")
                .and_then(|rest| rest.split_once('`'))
                .map(|(name, _)| name.to_owned())
        })
        .collect::<BTreeSet<_>>();

    let undocumented = clap_flags
        .difference(&doc_flags)
        .map(|flag| format!("--{flag}"))
        .collect::<Vec<_>>();
    assert!(
        undocumented.is_empty(),
        "new flag is undocumented - add a :::info block to docs/docs/command_line_flags.mdx for: {}",
        undocumented.join(", ")
    );

    let stale = doc_flags
        .difference(&clap_flags)
        .map(|flag| format!("--{flag}"))
        .collect::<Vec<_>>();
    assert!(
        stale.is_empty(),
        "stale doc block - the flag was renamed/removed from clap: {}",
        stale.join(", ")
    );
}

/// If you have multiple tests that use the same directory, please use different export_suffix
/// for each one or else the tests will be flaky as they are run concurrently.
///
/// Stable per-checkout discriminator for scratch dirs under `temp_dir()`: concurrent `cargo test`
/// runs from different checkouts/worktrees (an endorsed workflow) would otherwise share a fixed
/// path and `remove_dir_all` each other's fixtures/target mid-run.
pub(crate) fn checkout_hash() -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = std::collections::hash_map::DefaultHasher::new();
    std::env::current_dir().unwrap().hash(&mut h);
    h.finish()
}

/// Corpus fixtures whose generated crate references user-supplied code (for example,
/// `@custom_serialize` / `@custom_deserialize` functions like `my_ser`/`my_deser`, or the extern /
/// raw-bytes wrapper types an `@raw_bytes_flavor` extern generic references), so they cannot be
/// compiled or round-tripped standalone under any emission profile. They remain covered by source
/// snapshots — and, where a hand-written side exists, by a dedicated integration fixture (e.g.
/// `extern_generic_raw_bytes`).
pub(crate) const COMPILE_SKIP: &[&str] = &["dsl_custom", "dsl_copy", "extern_generic_raw_bytes"];

/// `(fixture stem, profile, reason)` triples whose GENERATION deliberately aborts under that
/// profile because the fixture reaches a tracked unimplemented path. Unlike `COMPILE_SKIP` (whole
/// fixture, every profile), this is per-profile: the fixture still generates and compile-gates
/// under its other profiles. Stale-guarded BOTH directions (mirrors
/// `wasm_parity_tests::EXPECTED_GENERATION_FAIL`): a listed pair that now GENERATES fails the gate
/// as "gap closed — remove the pin"; an unlisted generation failure fails as a normal generation
/// failure; and a listed stem absent from `tests/corpus` fails as a stale pin.
const EXPECTED_GENERATION_FAIL: &[(&str, &str, &str)] = &[(
    "dsl_ignore",
    "preserve",
    "an `@ignore` open struct-map is rejected under --preserve-encodings (a preserve crate's \
         byte-exact round-trip contract cannot hold for a type that drops unknown entries — the \
         rejection points at capture and at @custom_serialize/@custom_deserialize); default/json \
         generate the closed-struct surface",
)];

/// Wasm-matrix cells that deliberately never compile standalone in this harness. Each entry pairs
/// with a ledger entry in `cddl-matrix/ROADMAP.md` § findings (which shape/role, the exact `E####`,
/// root cause):
/// - `extern__array-element` references a user-supplied type (undefined standalone -> E0425), while
///   the extern emit path is integration-tested separately in `tests/extern-deps`. Because the cell
///   never compiles here, it never round-trips here either.
const WASM_MATRIX_SKIP: &[&str] = &["extern__array-element"];

/// Extract the DISTINCT rustc error codes (`E####`) from compiler output, keyed off the `error[E`
/// prefix. Only a real diagnostic header (`error[E0583]: ...`) carries that prefix; the trailing
/// `For more information about this error, try `rustc --explain E0583`.` summary and any bare code
/// inside a note line do NOT (they lack `error[`), so they are correctly ignored — the set reflects
/// the failure CLASS, not every textual mention. Deterministic `BTreeSet` (repo reproducibility
/// invariant). No new deps — a plain byte scan.
fn rustc_error_codes(stderr: &str) -> std::collections::BTreeSet<String> {
    let mut codes = std::collections::BTreeSet::new();
    let needle = "error[E";
    let mut rest = stderr;
    while let Some(pos) = rest.find(needle) {
        // Advance past `error[` to the digits after `E`.
        let after_e = &rest[pos + needle.len() - 1..]; // starts at 'E'
        let mut chars = after_e.char_indices();
        // first char is 'E'
        let _ = chars.next();
        let mut enddigits = 1;
        for (i, c) in chars {
            if c.is_ascii_digit() {
                enddigits = i + c.len_utf8();
            } else {
                break;
            }
        }
        let code = &after_e[..enddigits];
        // Only accept a well-formed `E` + digits followed by the closing `]`.
        if code.len() > 1 && after_e[enddigits..].starts_with(']') {
            codes.insert(code.to_string());
        }
        rest = &rest[pos + needle.len()..];
    }
    codes
}

/// Pin `rustc_error_codes`: distinct codes only (duplicates dedupe), the `--explain E####` summary
/// line must NOT count (no `error[` prefix), and a bare code inside a note must NOT count either.
#[test]
fn rustc_error_codes_extracts_the_failure_class() {
    let stderr = "\
error[E0583]: file not found for module `serialization`\n\
 --> src/generated/a/mod.rs:1:1\n\
error[E0583]: file not found for module `serialization`\n\
error[E0432]: unresolved import `crate::generated::MapU64ToText`\n\
note: the error code E0433 is only mentioned in prose here, not as a header\n\
For more information about this error, try `rustc --explain E0583`.\n";
    let codes = rustc_error_codes(stderr);
    let expected: std::collections::BTreeSet<String> = ["E0432".to_string(), "E0583".to_string()]
        .into_iter()
        .collect();
    assert_eq!(
        codes, expected,
        "E0583 dedupes to one; E0432 counts; the prose `E0433` note and the `--explain E0583` \
         summary must NOT count (neither carries the `error[` prefix)"
    );
    assert!(rustc_error_codes("no diagnostics here").is_empty());
}

/// Multifile-placement matrix cells (`tests/matrix_multifile/<shape>__<mode>/`) that deliberately
/// do NOT compile. Each `(cell stem, expected rustc error codes, reason)` names the error class the
/// sweep pins while landing green. The three module-placement error classes it originally held
/// (E0583 alias/enum-only non-root module declaring `pub mod serialization;` without the file;
/// E0432 anonymous same-shape table importing the structural name from root scope instead of the
/// sole owner's module; E0433 cross-module named `.cbor` ref omitting the inner-type import) are all
/// fixed in `generation/export.rs`'s module-declaration loop and `intermediate/mod.rs`'s
/// `scope_references`/`mark_refs`. The ARRAY/MAP structural-WRAPPER placement class is fixed too:
/// `mark_refs` resolves each collection occurrence's wrapper NAME and HOME scope through the shared
/// `wasm_collection_wrapper` helper (the emitter's `for_wasm_member` twin) instead of a hard-coded
/// pre-NonEmpty spelling from ROOT_SCOPE, and the restricted wrappers' loose `try_from` source is
/// imported at its emission scope — so `collrec__anon` and the whole `necoll`/`necollrec`/`nemap`/
/// `nepmap`/`nepmapa` restricted-wrapper family compile. The NAMED-collection alias-target recursion
/// class is fixed too: the `Alias` arm suppresses the structural-wrapper import when the alias names a
/// collection rule whose own class (imported via `set_ref`) subsumes the target's surface, so
/// `collrec__named` / `gcolln__named` (and the dep-owned named-map flavor) keep only the rule ident.
/// Currently EMPTY: no multifile-placement cell is deliberately red. Four-state verdict in
/// `multifile_matrix_compiles`: red+listed = expected (held here) — but ADDITIONALLY the observed
/// rustc error-code set (extracted from the captured cargo stderr) must EQUAL the pinned set, or the
/// cell's failure CLASS changed and the pin is re-triaged loudly; red+unlisted = failure (fix the
/// emitter or, deliberately, pin + ledger); green+listed = "resurfaced — remove the pin (a fix
/// landed)"; green+unlisted = pass. A skip cell whose GENERATION aborts (no rustc compile error at
/// all) is likewise a class mismatch. An up-front stale-key guard rejects a listed stem absent from
/// the projected fixture set, so the list can't rot silently.
const MULTIFILE_MATRIX_SKIP: &[(&str, &[&str], &str)] = &[];

/// Per-profile round-trip skips for `wasm_matrix_roundtrips` ONLY (never consulted by
/// `wasm_matrix_compiles`, which stays the always-on default-profile floor). Each `(profile, cell
/// stem, reason)` marks a cell whose emitted wasm round-trip surface is a known structural gap
/// UNDER THAT PROFILE — a red the sweep tolerates deliberately, distinct from `WASM_MATRIX_SKIP`'s
/// "red in EVERY profile" (extern). Such a cell COMPILEs (so it can't go in `WASM_MATRIX_SKIP`,
/// which the compile floor also consults and would flag as "resurfaced") — it is listed once per
/// affected profile and ledgered in cddl-matrix/ROADMAP.md § findings. A resurfaced guard fails the
/// gate if a listed cell starts passing, and an up-front stale-pin guard rejects entries naming a
/// dead profile or cell stem, so the list can't rot silently. Currently empty: no cell is
/// profile-specifically red.
const WASM_MATRIX_PROFILE_SKIP: &[(&str, &str, &str)] = &[];

/// Multifile-placement cells whose ROUND-TRIP (`multifile_matrix_roundtrips`) is deliberately red
/// in EVERY profile — `(cell stem, reason)`, the roundtrip precedent's shape (`WASM_MATRIX_SKIP`):
/// no rustc-error-code class assertion here, because the compile floor's `MULTIFILE_MATRIX_SKIP`
/// already pins each cell's exact failure class. Currently EMPTY: every multifile-placement cell
/// compiles (`MULTIFILE_MATRIX_SKIP` is empty) and round-trips — the NAMED-collection
/// alias-target-recursion cells that seeded this list (`collrec__named` / `gcolln__named`) are fixed
/// by the `Alias` arm's structural-wrapper suppression. Four-state verdict + stale-key guard as the
/// compile floor; a listed cell that starts round-tripping fails the resurfaced guard (remove the
/// pin — a fix landed).
const MULTIFILE_ROUNDTRIP_SKIP: &[(&str, &str)] = &[];

/// Per-profile round-trip skips for `multifile_matrix_roundtrips` ONLY — `(profile, cell stem,
/// reason)` for cells red under a SPECIFIC profile, distinct from `MULTIFILE_ROUNDTRIP_SKIP`'s
/// "red in every profile". Expected empty: the first full sweep found no profile-specific reds
/// (default/preserve/json all green outside the collrec pins). Same four-state contract; an
/// up-front stale-pin guard rejects entries naming a dead profile or cell stem.
const MULTIFILE_ROUNDTRIP_PROFILE_SKIP: &[(&str, &str, &str)] = &[];

/// Serialize gates that share a per-checkout scratch root under `temp_dir()`: two concurrent runs
/// of the SAME gate from the SAME checkout both `remove_dir_all` that root at start, so the second
/// deletes the first's fixtures/target mid-run (observed for `ir_conformance_corpus`). An advisory
/// flock on a sibling lock file serializes them while KEEPING the path-keyed root — so the
/// shared-cargo-target amortization that path-keying buys survives (a PID/random key would defeat
/// target reuse). The OS releases the lock on process death, so there is no stale-lock failure
/// mode. Returns the held lock; keep the returned handle alive for the whole gate (drop it and the
/// lock releases).
///
/// `scratch_name` is the scratch root's dir name (e.g. `cddl_codegen_ir_conformance_<hash>`); the
/// lock file is its SIBLING `temp_dir()/<scratch_name>.lock`, never inside the root (the root gets
/// `remove_dir_all`'d; unlinking a held lock file would let a third run acquire a fresh inode while
/// an earlier run still holds the old one).
#[must_use = "the lock releases when the returned handle is dropped — bind it for the whole gate"]
pub(crate) fn acquire_scratch_lock(scratch_name: &str) -> std::fs::File {
    let lock_path = std::env::temp_dir().join(format!("{scratch_name}.lock"));
    let file = std::fs::File::options()
        .create(true)
        .truncate(false)
        .write(true)
        .open(&lock_path)
        .unwrap_or_else(|e| panic!("cannot open scratch lock file {lock_path:?}: {e}"));
    match file.try_lock() {
        Ok(()) => {}
        Err(std::fs::TryLockError::WouldBlock) => {
            eprintln!(
                "another run of this gate from this checkout is active — waiting for it to finish \
                 (scratch root for {scratch_name:?} is shared; concurrent runs would clobber each \
                 other's crates). This is expected: same-checkout runs serialize on {lock_path:?}."
            );
            file.lock()
                .unwrap_or_else(|e| panic!("cannot acquire scratch lock {lock_path:?}: {e}"));
        }
        Err(std::fs::TryLockError::Error(e)) => {
            panic!("cannot acquire scratch lock {lock_path:?}: {e}")
        }
    }
    file
}

/// The one branch of `acquire_scratch_lock` worth a runnable check: a held lock is observed as
/// contended by an independent handle to the same file, and releases when dropped. (A whole-gate
/// two-process race isn't worth the machinery — this pins the advisory-flock semantics the gates
/// rely on.)
#[test]
fn acquire_scratch_lock_serializes() {
    let name = format!("cddl_codegen_scratch_lock_test_{:016x}", checkout_hash());
    let lock_path = std::env::temp_dir().join(format!("{name}.lock"));
    let _ = std::fs::remove_file(&lock_path);

    let held = acquire_scratch_lock(&name);

    // An independent handle to the SAME file must see the lock as held (advisory flock is per
    // open-file-description, so this is a genuine second acquirer, not a re-lock of `held`).
    let contender = std::fs::File::options()
        .create(true)
        .truncate(false)
        .write(true)
        .open(&lock_path)
        .unwrap();
    assert!(
        matches!(contender.try_lock(), Err(std::fs::TryLockError::WouldBlock)),
        "a second handle should observe the lock as held while the first is alive"
    );

    // Release the first lock; the contender can now take it. Match rather than `.is_ok()` so a
    // failure names WHICH way it failed: a PERSISTENT `WouldBlock` (the lock outlived its handle —
    // a real semantics break) vs a syscall error (e.g. ENOLCK under kernel lock-table pressure from
    // the suite's parallel cargo children — a transient environment condition, not a semantics
    // break). The release assert RETRIES a transient `WouldBlock` on a bounded deadline, to absorb
    // the attributed flake class without weakening the semantics pin: `flock` locks are per
    // open-file-description, and a concurrent `Command` spawn elsewhere in this multithreaded test
    // process forks a child that inherits a duplicate of `held`'s descriptor until its exec closes
    // the CLOEXEC fds — during that fork-to-exec window the duplicate keeps the lock alive, so an
    // INSTANTANEOUS post-drop `try_lock` can observe `WouldBlock` under parallel nested-cargo load
    // (the profile of all five ledgered sightings; first self-attributed capture 2026-07-17 after
    // the match split landed — see the flake ledger in tests/TESTING_ROADMAP.md). The gates' real
    // acquisition path is the BLOCKING `lock()`, which waits out that window by construction; only
    // this test's instantaneous assert ever raced it. A hold that outlives the deadline still
    // fails loudly — that remains a genuine release-on-drop break.
    std::mem::drop(held);
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        match contender.try_lock() {
            Ok(()) => break,
            Err(std::fs::TryLockError::WouldBlock) => {
                if std::time::Instant::now() >= deadline {
                    panic!(
                        "the lock should be acquirable once the first handle is dropped, but \
                         try_lock reported it still HELD (WouldBlock) for 5s of retries — a \
                         persistent hold, not the transient fork-to-exec fd-duplication window \
                         (which clears as soon as the concurrent child execs): the advisory-flock \
                         release-on-drop semantics the gates rely on are broken"
                    );
                }
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
            Err(std::fs::TryLockError::Error(e)) => panic!(
                "the lock should be acquirable once the first handle is dropped, but try_lock \
                 errored: {e} (raw_os_error {:?}) — a syscall failure, not a lock-semantics break; \
                 if transient (e.g. ENOLCK under load), see the flake ledger in \
                 tests/TESTING_ROADMAP.md",
                e.raw_os_error()
            ),
        }
    }
    std::mem::drop(contender);
    let _ = std::fs::remove_file(&lock_path);
}

/// One scratch root shared by the sibling `#[test]` SHARDS a matrix compile gate is split across.
///
/// The unsharded loop owned its root outright and wiped it twice: on entry, because generation is
/// only hermetic against a clean tree (the comment-preservation overlay READS prior generated
/// output, so a stale crate changes what the next run emits), and on exit, because the root holds
/// one generated crate per cell plus the shared `CARGO_TARGET_DIR` — gigabytes at rest, which
/// `draft/test-duration-first-principles.md` measured and rejected persisting.
///
/// Shards must keep BOTH halves while still sharing ONE target dir (per-shard target dirs would pay
/// the cbor_event/wasm-bindgen dependency build once per shard on a cold gate cache). So the wipe is
/// keyed on how many shards are currently INSIDE the root rather than on any single shard: the first
/// one in wipes, the last one out wipes. A run that selects a single shard by name degenerates to
/// exactly the old wipe-on-entry/wipe-on-exit behaviour.
///
/// Occupancy, not "shards finished": a filtered run that selects some shards must still clean up,
/// and a shard that panics must still release its count — hence the `Drop` impl, which libtest's
/// unwinding harness runs on the failure path too.
struct SharedScratch {
    root: std::path::PathBuf,
    occupancy: &'static std::sync::Mutex<usize>,
}

impl SharedScratch {
    /// Enter the root, wiping it if no other shard is inside. `occupancy` must be a `static` unique
    /// to the gate — two gates sharing one counter would wipe each other's roots.
    fn enter(occupancy: &'static std::sync::Mutex<usize>, root: std::path::PathBuf) -> Self {
        {
            // `unwrap_or_else(into_inner)`, never `unwrap()`: a shard that panics poisons the mutex,
            // and a poisoned-lock panic raised from the `Drop` below would abort the whole test
            // process instead of reporting the shard's own failure.
            let mut inside = occupancy.lock().unwrap_or_else(|e| e.into_inner());
            if *inside == 0 {
                let _ = std::fs::remove_dir_all(&root);
            }
            *inside += 1;
        }
        Self { root, occupancy }
    }

    fn root(&self) -> &std::path::Path {
        &self.root
    }
}

impl Drop for SharedScratch {
    fn drop(&mut self) {
        let mut inside = self.occupancy.lock().unwrap_or_else(|e| e.into_inner());
        *inside -= 1;
        if *inside == 0 {
            let _ = std::fs::remove_dir_all(&self.root);
        }
    }
}

/// The two halves of [`SharedScratch`]'s contract, which no gate run can demonstrate on its own:
/// the FIRST entrant wipes (hermetic generation) and the LAST leaver wipes (disk), while an
/// overlapping shard in between sees the root survive.
#[test]
fn shared_scratch_wipes_on_first_in_and_last_out() {
    static OCCUPANCY: std::sync::Mutex<usize> = std::sync::Mutex::new(0);
    let root = std::env::temp_dir().join(format!(
        "cddl_codegen_shared_scratch_probe_{}",
        std::process::id()
    ));
    let stale = root.join("stale.txt");
    std::fs::create_dir_all(&root).unwrap();
    std::fs::write(&stale, "prior run").unwrap();

    let first = SharedScratch::enter(&OCCUPANCY, root.clone());
    assert!(
        !stale.exists(),
        "the first shard inside must wipe the root — generation is only hermetic against a clean tree"
    );
    std::fs::create_dir_all(first.root()).unwrap();
    let live = root.join("live.txt");
    std::fs::write(&live, "shard output").unwrap();

    let second = SharedScratch::enter(&OCCUPANCY, root.clone());
    assert!(
        live.exists(),
        "a shard entering a root another shard is still inside must NOT wipe it"
    );
    std::mem::drop(first);
    assert!(
        live.exists(),
        "a shard leaving while another is still inside must NOT wipe the root"
    );
    std::mem::drop(second);
    assert!(
        !root.exists(),
        "the last shard out must wipe the root — the shared target dir is gigabytes at rest"
    );
}

fn tool_exists(bin: &str) -> bool {
    std::process::Command::new(bin)
        .arg("--version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

/// Spawn cargo/wasm-pack for building a *generated* crate. The generated code is the harness's
/// own output and legitimately over-imports traits and globs — the usage-derived prune
/// (`import_prune`) covers only the concrete collection-type imports, since a trait can be
/// exercised via a method call that never names it; CI's `setup-rust-toolchain` injects
/// `RUSTFLAGS="-D warnings"` into the job env, which nested cargo builds would otherwise inherit
/// and fail on those unused-import warnings. The root workspace keeps `-D warnings` via the
/// dedicated Build/clippy steps; only these nested generated-crate builds must be insulated.
pub(crate) fn tool_cmd(program: &str) -> std::process::Command {
    let mut c = std::process::Command::new(program);
    c.env_remove("RUSTFLAGS");
    c
}

/// The generator binary the generation call sites spawn, built exactly ONCE per test process.
///
/// Generation used to shell out to `tool_cmd("cargo").args(["run", "--"])`. That paid a cargo
/// freshness check on every generation — measured 0.11 s for a warm no-op, against 0.00 s for the
/// binary invoked directly — and, more importantly, took the repo `target/` build-directory lock
/// each time. A tier makes thousands of these calls (`decode_conformance_replay` alone ~411), so
/// serially the lock is invisible but it is the hard ceiling on any gate-level parallelism.
///
/// What `cargo run` bought that a bare path does NOT is the guarantee that the generator under test
/// is CURRENT: a hardcoded path silently tests a stale generator, a wrong-results failure mode far
/// worse than a slow one. So that guarantee is kept and merely relocated — one
/// `cargo build --bin cddl-codegen` per process behind this `OnceLock`, before the first spawn,
/// instead of one freshness check per spawn.
///
/// The path is derived from the RUNNING test executable rather than a literal `target/debug/`, so a
/// custom `CARGO_TARGET_DIR` (or a `--release` outer run) still resolves: libtest's harness lives at
/// `<target>/<profile>/deps/cddl_codegen-<hash>`, so the plain bin sits one directory up. The build
/// is load-bearing rather than defensive — `cargo test --bin cddl-codegen` (how every `#[ignore]`d
/// gate is invoked) builds only the test harness and does NOT uplift `<target>/<profile>/cddl-codegen`.
static GENERATOR_BIN: std::sync::OnceLock<std::path::PathBuf> = std::sync::OnceLock::new();

fn generator_bin() -> &'static std::path::Path {
    GENERATOR_BIN
        .get_or_init(|| {
            let exe = std::env::current_exe().expect(
                "the running test executable must have a resolvable path — the generator binary is \
                 located relative to it so a custom CARGO_TARGET_DIR still works",
            );
            let dir = exe
                .parent()
                .unwrap_or_else(|| panic!("test executable {exe:?} has no parent directory"))
                .to_path_buf();
            // `<target>/<profile>/deps/<harness>` for a libtest harness; tolerate an already-uplifted
            // `<target>/<profile>/<harness>` layout rather than assuming `deps`.
            let profile_dir = if dir.file_name() == Some(std::ffi::OsStr::new("deps")) {
                dir.parent()
                    .unwrap_or_else(|| panic!("{dir:?} has no parent directory"))
                    .to_path_buf()
            } else {
                dir
            };
            let target_root = profile_dir.parent().unwrap_or_else(|| {
                panic!("profile directory {profile_dir:?} has no parent target directory")
            });
            let bin = profile_dir.join(format!("cddl-codegen{}", std::env::consts::EXE_SUFFIX));
            // Same `RUSTFLAGS` strip as `tool_cmd`: the `cargo run` form this replaces went through
            // `tool_cmd`, so the generator was already built (and spawned) without CI's injected
            // `-D warnings`. Keeping it makes the swap behaviour-preserving.
            let mut build = tool_cmd("cargo");
            build.args(["build", "--bin", "cddl-codegen"]);
            if profile_dir.file_name() == Some(std::ffi::OsStr::new("release")) {
                build.arg("--release");
            }
            // Pin the inner build to the SAME target dir the harness was built into, so the path
            // derived above is the path the build writes.
            build.arg("--target-dir").arg(target_root);
            let out = build
                .output()
                .expect("`cargo build --bin cddl-codegen` must be spawnable from the test process");
            assert!(
                out.status.success(),
                "the one-per-process `cargo build --bin cddl-codegen` FAILED (status {:?}) — every \
                 generation call site depends on it, and skipping it would silently test a stale \
                 generator\nstdout:\n{}\nstderr:\n{}",
                out.status.code(),
                String::from_utf8_lossy(&out.stdout),
                String::from_utf8_lossy(&out.stderr)
            );
            assert!(
                bin.is_file(),
                "`cargo build --bin cddl-codegen` succeeded but no generator binary exists at \
                 {bin:?} (derived from test executable {exe:?}) — refusing to fall back to a \
                 guessed path, which could run a stale binary"
            );
            bin
        })
        .as_path()
}

/// A `Command` that runs this repo's generator binary directly — the replacement for
/// `tool_cmd("cargo").args(["run", "--"])` at every generation call site. Freshness is handled once
/// per process by `generator_bin`; `RUSTFLAGS` is stripped for the same reason `tool_cmd` strips it,
/// so the spawned environment matches what the `cargo run` form produced.
pub(crate) fn codegen_cmd() -> std::process::Command {
    let mut c = std::process::Command::new(generator_bin());
    c.env_remove("RUSTFLAGS");
    c
}

/// Locate the ruby `cddl` gem binary for the decorrelated conformance oracle (`ir_conformance_corpus`),
/// mirroring `cddl-matrix/verify.ts`'s `resolveRubyCddl`: an explicit `RUBY_CDDL` env pin wins (and
/// fails LOUD if it points nowhere — a mispinned oracle must NOT silently fall back to gem discovery,
/// or the run would probe a different validator than the operator intended); otherwise probe the gem
/// install location `$(ruby -e 'puts Gem.user_dir')/bin/cddl`. Returns `None` when neither resolves
/// (ruby absent / gem not installed) — the caller prints a grep-stable SKIPPED marker and the gate's
/// rust half still runs. Deliberately does NOT consult `$PATH`/`which cddl`: on a dev box that is
/// typically the unrelated RUST `cddl` binary (same lineage as the generator — no decorrelation).
fn resolve_ruby_cddl() -> Option<std::path::PathBuf> {
    if let Ok(pin) = std::env::var("RUBY_CDDL") {
        let p = std::path::PathBuf::from(&pin);
        assert!(
            p.exists(),
            "RUBY_CDDL is set to '{pin}' but no such file exists — a pinned ruby cddl oracle that \
             does not exist must fail loud, not silently fall back to gem discovery"
        );
        return Some(p);
    }
    let out = std::process::Command::new("ruby")
        .args(["-e", "puts Gem.user_dir"])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let gem_dir = String::from_utf8_lossy(&out.stdout).trim().to_owned();
    let cand = std::path::PathBuf::from(gem_dir).join("bin").join("cddl");
    cand.exists().then_some(cand)
}

// ===== decode-side reference-codec differential (used by `ir_conformance_corpus`) ===================
// A CDDL-BLIND structural cross-check, complementary to the two spec validators (the rust `cddl`
// validator and the ruby `cddl` gem, both of which prove our bytes match the SPEC). This decodes each
// minted case through TWO independent CBOR codecs — `ciborium` and `minicbor` — and asserts they BOTH
// fully consume the bytes and agree on the decoded structure. It catches a well-formedness/structural
// regression a CDDL validator wouldn't (a validator can accept bytes a raw decoder would choke on, or
// vice-versa), and it has NO external dependency, so it runs even under `CDDL_RUBY_ORACLE=skip` and for
// `RUST_ORACLE_SKIP` fixtures. What it proves: two decorrelated decoders agree on our bytes' structure.
// What it CAN'T: nothing about spec conformance — that's the two cddl oracles' job.
//
// The minted corpus is generated with default flags (no `--preserve-encodings`), so every dumped case
// is a single, canonical, definite-length CBOR item. Indefinite-length handling below is defensive:
// both codecs normalize indefinite byte/text strings to their concatenated definite form, so the trees
// still agree if one ever appears. `undefined` / exotic simple values aren't in the minter's baseline;
// `ciborium::Value` can't represent them, so if one ever surfaced the differential would (correctly)
// flag a structural surprise rather than silently pass.
#[derive(Debug, PartialEq)]
enum CborTree {
    Int(i128),
    Bytes(Vec<u8>),
    Text(String),
    Array(Vec<CborTree>),
    Map(Vec<(CborTree, CborTree)>),
    Tag(u64, Box<CborTree>),
    Bool(bool),
    Null,
    Undefined,
    Float(u64), // f64 bit pattern (f16/f32 widened); NaN canonicalized so bit-noise can't false-diff
    Simple(u8),
}

fn canon_f64_bits(f: f64) -> u64 {
    if f.is_nan() {
        f64::NAN.to_bits()
    } else {
        f.to_bits()
    }
}

fn tree_via_ciborium(bytes: &[u8]) -> Result<CborTree, String> {
    // Read from a slice cursor so we can assert the reader consumed ALL bytes (no trailing garbage):
    // `impl Read for &[u8]` advances the slice, and `from_reader` stops after one item.
    let mut cursor: &[u8] = bytes;
    let value: ciborium::value::Value =
        ciborium::from_reader(&mut cursor).map_err(|e| format!("ciborium decode error: {e}"))?;
    if !cursor.is_empty() {
        return Err(format!(
            "ciborium: {} trailing byte(s) after the item (not a single well-formed item)",
            cursor.len()
        ));
    }
    ciborium_value_to_tree(value)
}

fn ciborium_value_to_tree(v: ciborium::value::Value) -> Result<CborTree, String> {
    use ciborium::value::Value;
    Ok(match v {
        Value::Integer(i) => CborTree::Int(i128::from(i)),
        Value::Bytes(b) => CborTree::Bytes(b),
        Value::Float(f) => CborTree::Float(canon_f64_bits(f)),
        Value::Text(s) => CborTree::Text(s),
        Value::Bool(b) => CborTree::Bool(b),
        Value::Null => CborTree::Null,
        Value::Tag(t, inner) => CborTree::Tag(t, Box::new(ciborium_value_to_tree(*inner)?)),
        Value::Array(items) => CborTree::Array(
            items
                .into_iter()
                .map(ciborium_value_to_tree)
                .collect::<Result<_, _>>()?,
        ),
        Value::Map(entries) => CborTree::Map(
            entries
                .into_iter()
                .map(|(k, val)| Ok((ciborium_value_to_tree(k)?, ciborium_value_to_tree(val)?)))
                .collect::<Result<Vec<_>, String>>()?,
        ),
        // `#[non_exhaustive]`: a variant ciborium adds later (or a value it can't model, e.g.
        // `undefined`) surfaces as a structural surprise rather than a silent pass.
        other => return Err(format!("ciborium: unsupported value variant {other:?}")),
    })
}

fn tree_via_minicbor(bytes: &[u8]) -> Result<CborTree, String> {
    let mut tokens = minicbor::decode::Tokenizer::new(bytes);
    let tree = minicbor_next_item(&mut tokens)?;
    // Full consumption: after one complete item the token stream must be exhausted.
    if let Some(extra) = tokens.next() {
        return Err(format!(
            "minicbor: trailing tokens after the item (not a single well-formed item): {extra:?}"
        ));
    }
    Ok(tree)
}

fn minicbor_pull<'b>(
    it: &mut minicbor::decode::Tokenizer<'_, 'b>,
) -> Result<minicbor::data::Token<'b>, String> {
    match it.next() {
        Some(Ok(t)) => Ok(t),
        Some(Err(e)) => Err(format!("minicbor decode error: {e}")),
        None => Err("minicbor: unexpected end of input".into()),
    }
}

fn minicbor_next_item(it: &mut minicbor::decode::Tokenizer<'_, '_>) -> Result<CborTree, String> {
    let tok = minicbor_pull(it)?;
    minicbor_item_from(tok, it)
}

fn minicbor_item_from(
    tok: minicbor::data::Token<'_>,
    it: &mut minicbor::decode::Tokenizer<'_, '_>,
) -> Result<CborTree, String> {
    use minicbor::data::Token;
    Ok(match tok {
        Token::Bool(b) => CborTree::Bool(b),
        Token::U8(n) => CborTree::Int(i128::from(n)),
        Token::U16(n) => CborTree::Int(i128::from(n)),
        Token::U32(n) => CborTree::Int(i128::from(n)),
        Token::U64(n) => CborTree::Int(i128::from(n)),
        Token::I8(n) => CborTree::Int(i128::from(n)),
        Token::I16(n) => CborTree::Int(i128::from(n)),
        Token::I32(n) => CborTree::Int(i128::from(n)),
        Token::I64(n) => CborTree::Int(i128::from(n)),
        Token::Int(i) => CborTree::Int(i128::from(i)),
        Token::F16(f) => CborTree::Float(canon_f64_bits(f64::from(f))),
        Token::F32(f) => CborTree::Float(canon_f64_bits(f64::from(f))),
        Token::F64(f) => CborTree::Float(canon_f64_bits(f)),
        Token::Bytes(b) => CborTree::Bytes(b.to_vec()),
        Token::String(s) => CborTree::Text(s.to_owned()),
        Token::Null => CborTree::Null,
        Token::Undefined => CborTree::Undefined,
        Token::Simple(n) => CborTree::Simple(n),
        Token::Tag(t) => CborTree::Tag(t.as_u64(), Box::new(minicbor_next_item(it)?)),
        Token::Array(n) => {
            let mut items = Vec::with_capacity(n as usize);
            for _ in 0..n {
                items.push(minicbor_next_item(it)?);
            }
            CborTree::Array(items)
        }
        Token::Map(n) => {
            let mut entries = Vec::with_capacity(n as usize);
            for _ in 0..n {
                let k = minicbor_next_item(it)?;
                let v = minicbor_next_item(it)?;
                entries.push((k, v));
            }
            CborTree::Map(entries)
        }
        Token::BeginArray => {
            let mut items = vec![];
            loop {
                let t = minicbor_pull(it)?;
                if matches!(t, Token::Break) {
                    break;
                }
                items.push(minicbor_item_from(t, it)?);
            }
            CborTree::Array(items)
        }
        Token::BeginMap => {
            let mut entries = vec![];
            loop {
                let t = minicbor_pull(it)?;
                if matches!(t, Token::Break) {
                    break;
                }
                let k = minicbor_item_from(t, it)?;
                let v = minicbor_next_item(it)?;
                entries.push((k, v));
            }
            CborTree::Map(entries)
        }
        Token::BeginBytes => {
            let mut buf = vec![];
            loop {
                match minicbor_pull(it)? {
                    Token::Break => break,
                    Token::Bytes(b) => buf.extend_from_slice(b),
                    other => {
                        return Err(format!(
                            "minicbor: unexpected token {other:?} inside indefinite byte string"
                        ));
                    }
                }
            }
            CborTree::Bytes(buf)
        }
        Token::BeginString => {
            let mut s = String::new();
            loop {
                match minicbor_pull(it)? {
                    Token::Break => break,
                    Token::String(chunk) => s.push_str(chunk),
                    other => {
                        return Err(format!(
                            "minicbor: unexpected token {other:?} inside indefinite text string"
                        ));
                    }
                }
            }
            CborTree::Text(s)
        }
        Token::Break => return Err("minicbor: unexpected Break token".into()),
    })
}

/// Canonicalize the one place the two codecs legitimately MODEL the same well-formed bytes
/// differently: RFC 8949 §3.4.3 bignum tags. `ciborium`'s byte-level decoder folds tag 2 (BIGPOS) /
/// tag 3 (BIGNEG) wrapping a definite byte string of <= 16 bytes into an integer (BIGNEG `b` becomes
/// `-1 - be(b)`, i.e. `raw ^ !0`), while `minicbor`'s token stream leaves them as `Tag(2/3, Bytes)`.
/// Both are correct decodings of the same bytes (our `biguint`/`bignint` prelude types encode as
/// exactly this), so we fold minicbor's tree to match — the divergence is representational, not a
/// structural regression. Applied to BOTH trees: a no-op on ciborium's already-folded tree. A bignum
/// that exceeds i128 (never minted by the corpus) is left as `Tag` and would surface as a divergence
/// to investigate rather than being silently mis-canonicalized.
fn fold_bignums(t: CborTree) -> CborTree {
    fn folded_int(neg: bool, b: &[u8]) -> Option<CborTree> {
        if b.len() > 16 {
            return None;
        }
        let mut buf = [0u8; 16];
        buf[16 - b.len()..].copy_from_slice(b);
        let raw = u128::from_be_bytes(buf);
        let signed = i128::try_from(raw).ok()?;
        Some(CborTree::Int(if neg { signed ^ !0 } else { signed }))
    }
    match t {
        CborTree::Tag(tag @ (2 | 3), inner) => {
            if let CborTree::Bytes(b) = inner.as_ref()
                && let Some(folded) = folded_int(tag == 3, b)
            {
                return folded;
            }
            CborTree::Tag(tag, Box::new(fold_bignums(*inner)))
        }
        CborTree::Tag(tag, inner) => CborTree::Tag(tag, Box::new(fold_bignums(*inner))),
        CborTree::Array(items) => CborTree::Array(items.into_iter().map(fold_bignums).collect()),
        CborTree::Map(entries) => CborTree::Map(
            entries
                .into_iter()
                .map(|(k, v)| (fold_bignums(k), fold_bignums(v)))
                .collect(),
        ),
        other => other,
    }
}

/// Both independent codecs must fully decode `bytes` AND agree on the decoded structure (after
/// bignum-representation canonicalization, see `fold_bignums`). Any error names which codec failed
/// and why; a tree mismatch dumps both trees. Anti-vacuity: a truncated (malformed) case must FAIL
/// this — a decoder that accepts anything can't pass (see the gate's negative control).
fn reference_codec_differential(bytes: &[u8]) -> Result<(), String> {
    let via_cib = fold_bignums(tree_via_ciborium(bytes)?);
    let via_mini = fold_bignums(tree_via_minicbor(bytes)?);
    if via_cib != via_mini {
        return Err(format!(
            "ciborium and minicbor disagree on the decoded structure:\n  ciborium: {via_cib:?}\n  minicbor: {via_mini:?}"
        ));
    }
    Ok(())
}

/// Pins the reference-codec differential's semantics on hand-derived RFC 8949 bytes so a codec bump
/// or a mapping bug is caught fast, and — the teeth — asserts truncated bytes FAIL (a decoder that
/// accepts anything can't pass). Mirrors the anti-vacuity posture the gate's negative control enforces
/// at breadth.
#[test]
fn reference_codec_differential_self_check() {
    // Well-formed vectors both codecs must fully decode and agree on.
    let good: &[(&str, &[u8])] = &[
        ("uint 0", &[0x00]),
        ("uint 100", &[0x18, 0x64]),
        ("nint -1", &[0x20]),
        // negative below i64::MIN exercises minicbor's `Int` token + ciborium's i128 integer.
        (
            "nint -2^63-1",
            &[0x3b, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
        ),
        ("text \"a\"", &[0x61, 0x61]),
        ("bytes h'01'", &[0x41, 0x01]),
        ("false", &[0xf4]),
        ("true", &[0xf5]),
        ("null", &[0xf6]),
        ("array [1, 2]", &[0x82, 0x01, 0x02]),
        ("map {1: 2}", &[0xa1, 0x01, 0x02]),
        (
            "tag 0 \"2013-03-21T20:04:00Z\"",
            &[
                0xc0, 0x74, 0x32, 0x30, 0x31, 0x33, 0x2d, 0x30, 0x33, 0x2d, 0x32, 0x31, 0x54, 0x32,
                0x30, 0x3a, 0x30, 0x34, 0x3a, 0x30, 0x30, 0x5a,
            ],
        ),
        ("nested [[]]", &[0x81, 0x80]),
        // bignum tags: ciborium folds tag 2/3 + short bytes into an integer, minicbor keeps them as
        // Tag(2/3, Bytes); `fold_bignums` reconciles them (the `biguint`/`bignint` prelude case).
        ("biguint tag2 h'00'", &[0xc2, 0x41, 0x00]),
        ("bignint tag3 h'00'", &[0xc3, 0x41, 0x00]),
        ("biguint tag2 h'0100'", &[0xc2, 0x42, 0x01, 0x00]),
    ];
    for (label, bytes) in good {
        assert!(
            reference_codec_differential(bytes).is_ok(),
            "reference-codec differential should accept well-formed {label}: {}",
            reference_codec_differential(bytes).unwrap_err()
        );
    }

    // Teeth: truncating the final byte of a well-formed multi-byte item yields an incomplete item
    // both codecs must reject — so the differential returns Err (never a silent accept).
    for (label, bytes) in good.iter().filter(|(_, b)| b.len() > 1) {
        let truncated = &bytes[..bytes.len() - 1];
        assert!(
            reference_codec_differential(truncated).is_err(),
            "reference-codec differential must reject truncated (malformed) {label}"
        );
    }

    // Trailing-garbage teeth: a valid item plus an extra byte is NOT a single well-formed item.
    assert!(
        reference_codec_differential(&[0x00, 0x00]).is_err(),
        "two concatenated items must fail the single-item full-consumption check"
    );
}

/// Append the in-repo user-supplied `RawBytesEncoding` defs (`PubKey`) into a freshly generated crate
/// rooted at `out` (rust + wasm), so a `rawbytes__*` wasm-matrix cell — whose `_CDDL_CODEGEN_RAW_BYTES_TYPE_`
/// resolves to that user type — compiles/tests standalone instead of being skipped permanently like `extern`.
/// Mirrors `run_test`'s external-file append (including the `use serialization::*;` the rust def needs for
/// `RawBytesEncoding`/`Deserialize*`); the matrix never passes `--lib-name`, so the wasm def's `cddl_lib`
/// path needs no substitution here.
///
/// `json` selects the json-flavored rust def: the json flags make generated code delegate its JSON
/// representation to the user type (serde::Serialize/Deserialize + schemars::JsonSchema bounds —
/// part of the documented `_CDDL_CODEGEN_RAW_BYTES_TYPE_` contract), so the fixture must model a
/// user who satisfies them. The wasm def has no flavor (its json fns delegate through the rust
/// type's serde).
fn append_raw_bytes_defs(out: &std::path::Path, json: bool) {
    use std::io::Write;
    let rust_def_path = if json {
        "tests/external_rust_raw_bytes_def_json"
    } else {
        "tests/external_rust_raw_bytes_def"
    };
    let rust_def = std::fs::read_to_string(rust_def_path).unwrap();
    // Append into the user-owned thin `lib.rs` — the SAME contract as extern-type defs (see
    // `run_test`'s `is_extern_type_def` path): a real consumer defines a
    // `_CDDL_CODEGEN_RAW_BYTES_TYPE_` type in hand-written code re-exported at the crate root, and
    // the generator's extern re-export glue (`pub use crate::Name;` in the declaring scope's
    // generated module) resolves the bare `generated/**` references back to it. Appending into
    // `generated/mod.rs` instead would model the pre-thin-root contract no real user can follow
    // (that subtree is clobbered every run) — and it MASKED the glue not covering `RawBytesType`
    // (CML cip36's `public_key` aliases failed E0412 on regen while this fixture stayed green);
    // it now also collides with the glue's own `pub use crate::<Name>;` line. The def files carry
    // their own explicit imports, so no `use serialization::*;` prefix is needed here.
    let mut rust_lib = std::fs::OpenOptions::new()
        .append(true)
        .open(out.join("rust/src/lib.rs"))
        .unwrap();
    rust_lib.write_all(b"\n\n").unwrap();
    rust_lib.write_all(rust_def.as_bytes()).unwrap();
    std::mem::drop(rust_lib);
    let wasm_def = std::fs::read_to_string("tests/external_wasm_raw_bytes_def").unwrap();
    // Append into the user-owned thin wasm `lib.rs` — the same real-contract routing as the rust def
    // above (and as `run_test`'s `is_extern_wasm_type_def` path): the wasm glue re-exports raw-bytes
    // wrappers with `pub use crate::<Name>;` into `wasm/src/generated/**` too, so a definition there
    // would collide, and `generated/**` residence models a layout no real user can keep (clobbered
    // every regen — it masked the wasm glue not covering `RawBytesType`). The crate root doesn't see
    // the `wasm_bindgen` macro `generated/mod.rs` privately `use`s, so bring it along (the raw-bytes
    // def needs nothing else from the prelude).
    let mut wasm_lib = std::fs::OpenOptions::new()
        .append(true)
        .open(out.join("wasm/src/lib.rs"))
        .unwrap();
    wasm_lib
        .write_all(b"\nuse wasm_bindgen::prelude::wasm_bindgen;\n\n")
        .unwrap();
    wasm_lib.write_all(wasm_def.as_bytes()).unwrap();
}

/// Append raw dependency snippets to a generated `Cargo.toml` in a position-robust way: insert them
/// right after the `[dependencies]` header rather than at EOF. The generated rust manifest now ends
/// with a `[features]` table (the wasm-bindgen feature gate), so a blind EOF append would land the
/// deps UNDER `[features]`, where cargo reads them as feature values ("expected a sequence"). Each
/// snippet may hold one or more `name = spec` lines (a leading/trailing blank line is tolerated).
/// Falls back to seeding a fresh `[dependencies]` table if the manifest has none. These are throwaway
/// test-scaffolding deps (never asserted byte-wise), so the reordering is immaterial to what's tested.
fn append_manifest_deps(manifest: &std::path::Path, dep_snippets: &[&str]) {
    let content = std::fs::read_to_string(manifest).unwrap();
    let mut block = String::new();
    for snippet in dep_snippets {
        block.push_str(snippet.trim_matches('\n'));
        block.push('\n');
    }
    const NEEDLE: &str = "[dependencies]\n";
    let patched = match content.find(NEEDLE) {
        Some(pos) => {
            let at = pos + NEEDLE.len();
            format!("{}{}{}", &content[..at], block, &content[at..])
        }
        None => format!("{}\n[dependencies]\n{}", content.trim_end(), block),
    };
    std::fs::write(manifest, patched).unwrap();
}

/// Every `$ref` string anywhere in a JSON value, in document order. A schema keyword is the only
/// thing that can hold a `$ref`, and its value is always a string there — an object-valued `"$ref"`
/// key is a user property literally named `$ref`, which is not a reference and is skipped.
fn collect_schema_refs(value: &serde_json::Value, out: &mut Vec<String>) {
    match value {
        serde_json::Value::Object(map) => {
            for (key, child) in map {
                if key == "$ref"
                    && let Some(reference) = child.as_str()
                {
                    out.push(reference.to_owned());
                }
                collect_schema_refs(child, out);
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                collect_schema_refs(item, out);
            }
        }
        _ => {}
    }
}

/// Inverse of `schemars`' (private) `encode_ref_name`: percent-decode, then undo the JSON-Pointer
/// `~1`/`~0` escapes, so a `$defs` key containing `/`, `<`, `>` or a space (e.g. the static runtime's
/// `OrderedHashMap<K, V>`) is matched against the map by its REAL key rather than by its encoded
/// spelling. Percent escapes and tilde escapes cannot alias: the encoder emits `~0`/`~1` for `~`/`/`
/// and percent-escapes everything else, so no `%XX` ever decodes to `~` or `/`.
fn decode_schema_ref_name(encoded: &str) -> String {
    let bytes = encoded.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%'
            && i + 2 < bytes.len()
            && let Ok(byte) = u8::from_str_radix(&encoded[i + 1..i + 3], 16)
        {
            decoded.push(byte);
            i += 3;
            continue;
        }
        decoded.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&decoded)
        .replace("~1", "/")
        .replace("~0", "~")
}

fn run_test(
    dir: &str,
    options: &[&str],
    export_suffix: Option<&str>,
    external_rust_file_paths: &[std::path::PathBuf],
    external_wasm_file_paths: &[std::path::PathBuf],
    input_is_dir: bool,
    test_deps: &[&str],
) {
    use std::str::FromStr;
    let export_path = match export_suffix {
        Some(suffix) => format!("export_{suffix}"),
        None => "export".to_owned(),
    };
    let test_path = std::path::PathBuf::from_str("tests").unwrap().join(dir);
    println!("--------- running test: {dir} ---------");
    // These export dirs are throwaway regen targets (not user-owned manifests), reused across runs
    // only to amortize each crate's `target/`. Generation now MERGES the manifest instead of
    // clobbering it, so the raw `test_deps` appended into these manifests below would otherwise
    // accumulate (duplicate keys) across runs. Reset the manifests to a clean slate before
    // regenerating so the harness's append model still holds; `target/` is left intact. (The
    // user-facing manifest merge/preservation contract is exercised by
    // `cargo_manifest_disk_round_trip`, not here.)
    for manifest in [
        "rust/Cargo.toml",
        "wasm/Cargo.toml",
        "wasm/json-gen/Cargo.toml",
    ] {
        let _ = std::fs::remove_file(test_path.join(format!("{export_path}/{manifest}")));
    }
    // Each crate root `lib.rs` (rust, wasm, json-gen) is now a seed-once thin root the tool never
    // clobbers. The committed fixture exports still carry the pre-split monolithic `lib.rs` (full
    // generated content); left in place, seed-once would preserve it and it would collide with the
    // regenerated `generated/**` subtree (duplicate definitions). Delete them so the tool re-seeds a
    // clean thin root each run. (The survival-across-edits contract is covered by
    // `thin_root_seed_once`/`thin_root_wiring_survives`.)
    for root in [
        "rust/src/lib.rs",
        "wasm/src/lib.rs",
        "wasm/json-gen/src/lib.rs",
    ] {
        let _ = std::fs::remove_file(test_path.join(format!("{export_path}/{root}")));
    }
    // generate the code by spawning the generator binary
    let mut gen_cmd = codegen_cmd();
    gen_cmd.arg(format!(
        "--output={}",
        test_path.join(&export_path).to_str().unwrap()
    ));
    // These reused export dirs accumulate hand-written scaffolding (custom-serialization helpers, the
    // appended `tests.rs`/`deser_test` modules — code the tool never emits, carrying its own comments)
    // in `generated/mod.rs` after each export. The harness's model is pristine clobber-then-append, so
    // regenerate with comment preservation OFF: default-on would (correctly) read those hand-written
    // comments as edits on now-vanished items and trap them in `compile_error!` blocks. The
    // preservation contract itself is covered by `comment_preservation_disk_round_trip`.
    gen_cmd.arg("--no-preserve-comments");
    if input_is_dir {
        gen_cmd.arg(format!(
            "--input={}",
            test_path.join("inputs").to_str().unwrap()
        ));
    } else {
        gen_cmd.arg(format!(
            "--input={}",
            test_path.join("input.cddl").to_str().unwrap()
        ));
    }
    for option in options {
        gen_cmd.arg(option);
    }
    println!("   ------ building ------");
    let gen_result = gen_cmd.output().unwrap();
    if !gen_result.status.success() {
        eprintln!("{}", String::from_utf8(gen_result.stderr).unwrap());
    }
    assert!(gen_result.status.success());
    // Copy tests into generated code. The generated root scope (with the cross-module `use` imports
    // the appended tests' `use super::*;` relies on) now lives in `generated/mod.rs`, not the thin
    // seed-once `lib.rs`; append the tests there so they see exactly the imports they did when the old
    // monolithic `lib.rs` WAS the root scope. `generated/mod.rs` is regenerated every run, so appends
    // don't accumulate across reruns of the same throwaway export dir.
    let mut generated_mod = std::fs::OpenOptions::new()
        .append(true)
        .open(test_path.join(format!("{export_path}/rust/src/generated/mod.rs")))
        .unwrap();
    // some pasted-in tests need this
    generated_mod
        .write_all("\nuse serialization::*;\n".as_bytes())
        .unwrap();
    // `external_rust_file_paths` carries two kinds of hand-written code that belong in DIFFERENT scopes
    // under the thin-root split:
    //   - extern-TYPE definitions (`external_rust_defs*` AND the raw-bytes defs
    //     `external_rust_raw_bytes*`): the Rust definition of a type declared
    //     `_CDDL_CODEGEN_EXTERN_TYPE_` / `_CDDL_CODEGEN_RAW_BYTES_TYPE_`. These CANNOT live in
    //     `generated/**` (clobbered every run, and the generator re-exports each in-crate extern —
    //     both flavors — with `pub use crate::Name;` into that subtree, so a definition there
    //     collides E0255). A real consumer defines the extern in a hand-written module and
    //     re-exports it at the crate root; the glue resolves the bare `generated/**` references
    //     back to it. Model that by appending these into the user-owned thin `lib.rs`.
    //   - generated-scope helpers (`custom_serialization*`, conformance harnesses): free functions the
    //     generated `serialization.rs` calls via `use super::*;`, so they must land in the `generated`
    //     module scope — append them into `generated/mod.rs` exactly as before.
    // Both need `use serialization::*;` (reachable at the crate root through the seeded
    // `pub use generated::*;` glob), written into whichever file receives defs.
    let is_extern_type_def = |path: &std::path::Path| {
        path.file_name().and_then(|n| n.to_str()).is_some_and(|n| {
            n.starts_with("external_rust_defs") || n.starts_with("external_rust_raw_bytes")
        })
    };
    if external_rust_file_paths
        .iter()
        .any(|p| is_extern_type_def(p))
    {
        let mut root_lib_rs = std::fs::OpenOptions::new()
            .append(true)
            .open(test_path.join(format!("{export_path}/rust/src/lib.rs")))
            .unwrap();
        root_lib_rs
            .write_all("\nuse serialization::*;\n".as_bytes())
            .unwrap();
        for external_rust_file_path in external_rust_file_paths
            .iter()
            .filter(|p| is_extern_type_def(p))
        {
            let extern_rs = std::fs::read_to_string(external_rust_file_path).unwrap();
            root_lib_rs.write_all("\n\n".as_bytes()).unwrap();
            root_lib_rs.write_all(extern_rs.as_bytes()).unwrap();
        }
    }
    for external_rust_file_path in external_rust_file_paths
        .iter()
        .filter(|p| !is_extern_type_def(p))
    {
        let extern_rs = std::fs::read_to_string(external_rust_file_path).unwrap();
        generated_mod.write_all("\n\n".as_bytes()).unwrap();
        generated_mod.write_all(extern_rs.as_bytes()).unwrap();
    }
    let deser_test_rs = std::fs::read_to_string(
        std::path::PathBuf::from_str("tests")
            .unwrap()
            .join("deser_test"),
    )
    .unwrap();
    generated_mod.write_all("\n\n".as_bytes()).unwrap();
    generated_mod.write_all(deser_test_rs.as_bytes()).unwrap();
    let test_rs = std::fs::read_to_string(test_path.join("tests.rs")).unwrap();
    generated_mod.write_all("\n\n".as_bytes()).unwrap();
    generated_mod.write_all(test_rs.as_bytes()).unwrap();
    std::mem::drop(generated_mod);
    // add extra deps used within tests
    if !test_deps.is_empty() {
        append_manifest_deps(
            &test_path.join(format!("{export_path}/rust/Cargo.toml")),
            test_deps,
        );
        // copy test deps to wasm too in case they're used (e.g. extern deps dir crates)
        let wasm_manifest = test_path.join(format!("{export_path}/wasm/Cargo.toml"));
        if wasm_manifest.exists() {
            append_manifest_deps(&wasm_manifest, test_deps);
        }
    }
    // run tests in generated code
    println!("   ------ testing ------");
    let cargo_test = tool_cmd("cargo")
        .arg("test")
        .current_dir(test_path.join(format!("{export_path}/rust")))
        .output()
        .unwrap();
    if !cargo_test.status.success() {
        eprintln!(
            "test stderr:\n{}",
            String::from_utf8(cargo_test.stderr).unwrap()
        );
    }
    println!(
        "test stdout:\n{}",
        String::from_utf8(cargo_test.stdout).unwrap()
    );
    assert!(cargo_test.status.success());

    // wasm
    let wasm_export_dir = test_path.join(format!("{export_path}/wasm"));
    let wasm_test_path = test_path.join("tests_wasm.rs");
    // The harness knows from the flags which outputs generation promised; assert instead of gating
    // stages on `.exists()`, so an emission regression fails loudly rather than silently turning
    // the stage into a no-op.
    let wasm_expected = !options.contains(&"--wasm=false");
    if wasm_expected {
        assert!(
            wasm_export_dir.exists(),
            "no wasm crate at {wasm_export_dir:?} (--wasm=false was not passed) — generation stopped emitting it"
        );
    }
    // we must replace the lib name if it's not the default
    let custom_lib_name = options.iter().find_map(|arg: &&str| {
        arg.split_once("--lib-name=")
            .map(|(_, lib_name)| lib_name.replace('-', "_"))
    });
    // copy external wasm defs if they exist. Two kinds land in DIFFERENT scopes under the thin-root
    // split, mirroring the rust-side routing (see the `is_extern_type_def` split above):
    //   - extern-TYPE WRAPPER defs (`external_wasm_defs*` AND the raw-bytes wrappers
    //     `external_wasm_raw_bytes*`): the `#[wasm_bindgen]` wrapper of a type declared
    //     `_CDDL_CODEGEN_EXTERN_TYPE_` / `_CDDL_CODEGEN_RAW_BYTES_TYPE_`. The generator re-exports
    //     each in-crate extern wrapper — both flavors — with `pub use crate::Name;` INTO
    //     `generated/**`, so a definition there would collide. A real consumer defines the wrapper in
    //     a hand-written wasm module and re-exports it at the wasm crate root; the glue resolves the
    //     bare `generated/**` references back to it. Model that by appending these into the user-owned
    //     thin wasm `lib.rs`. That crate root doesn't see the `wasm_bindgen`/`JsError` names
    //     generated/mod.rs privately `use`s, so add them alongside. (Raw-bytes defs previously sat in
    //     `wasm/src/generated/mod.rs` — the modeled-obsolete residence that masked the wasm glue not
    //     covering `RawBytesType` while the rust half of the same bug was consumer-reported.)
    //   - non-extern wasm helpers (`custom_serialization*` etc.): referenced by the generated code via
    //     same-module resolution — they stay in `generated/mod.rs` (unchanged).
    let is_extern_wasm_type_def = |path: &std::path::Path| {
        path.file_name().and_then(|n| n.to_str()).is_some_and(|n| {
            n.starts_with("external_wasm_defs") || n.starts_with("external_wasm_raw_bytes")
        })
    };
    let append_wasm = |file: &mut std::fs::File, external_wasm_file_path: &std::path::PathBuf| {
        let extern_rs = std::fs::read_to_string(external_wasm_file_path).unwrap();
        file.write_all("\n\n".as_bytes()).unwrap();
        if let Some(custom_lib_name) = &custom_lib_name {
            let replaced_extern_rs = extern_rs.replace("cddl_lib", custom_lib_name);
            file.write_all(replaced_extern_rs.as_bytes()).unwrap();
        } else {
            file.write_all(extern_rs.as_bytes()).unwrap();
        }
    };
    if wasm_expected
        && external_wasm_file_paths
            .iter()
            .any(|p| is_extern_wasm_type_def(p))
    {
        let mut wasm_root_lib = std::fs::OpenOptions::new()
            .append(true)
            .open(test_path.join(format!("{export_path}/wasm/src/lib.rs")))
            .unwrap();
        wasm_root_lib
            .write_all(b"\nuse wasm_bindgen::prelude::{wasm_bindgen, JsError};\n")
            .unwrap();
        for external_wasm_file_path in external_wasm_file_paths
            .iter()
            .filter(|p| is_extern_wasm_type_def(p))
        {
            println!("trying to open (wasm root): {external_wasm_file_path:?}");
            append_wasm(&mut wasm_root_lib, external_wasm_file_path);
        }
    }
    for external_wasm_file_path in external_wasm_file_paths
        .iter()
        .filter(|p| !is_extern_wasm_type_def(p))
    {
        println!("trying to open (generated): {external_wasm_file_path:?}");
        // non-extern wasm helpers reference the generated wrapper types via same-module resolution,
        // both resolved in `generated/mod.rs` (see the wasm half of `append_raw_bytes_defs`).
        let mut wasm_lib_rs = std::fs::OpenOptions::new()
            .append(true)
            .open(test_path.join(format!("{export_path}/wasm/src/generated/mod.rs")))
            .unwrap();
        append_wasm(&mut wasm_lib_rs, external_wasm_file_path);
    }
    if wasm_expected && wasm_test_path.exists() {
        // The hook is only real if the file's contents actually land in the crate: append into the
        // generated root scope (`generated/mod.rs`, the equivalent of the old monolithic wasm root)
        // exactly like tests.rs into `rust/src/generated/mod.rs`. A generated wasm crate ships no
        // #[test]s of its own, so without the append `cargo test` runs zero tests and passes
        // vacuously (which is what this branch silently did before).
        let mut wasm_lib_rs = std::fs::OpenOptions::new()
            .append(true)
            .open(test_path.join(format!("{export_path}/wasm/src/generated/mod.rs")))
            .unwrap();
        let test_wasm_rs = std::fs::read_to_string(&wasm_test_path).unwrap();
        wasm_lib_rs.write_all("\n\n".as_bytes()).unwrap();
        if let Some(custom_lib_name) = &custom_lib_name {
            wasm_lib_rs
                .write_all(test_wasm_rs.replace("cddl_lib", custom_lib_name).as_bytes())
                .unwrap();
        } else {
            wasm_lib_rs.write_all(test_wasm_rs.as_bytes()).unwrap();
        }
        std::mem::drop(wasm_lib_rs);
        println!("   ------ testing (wasm) ------");
        let cargo_test_wasm = tool_cmd("cargo")
            .arg("test")
            .current_dir(&wasm_export_dir)
            .output()
            .unwrap();
        if !cargo_test_wasm.status.success() {
            eprintln!(
                "test stderr:\n{}",
                String::from_utf8(cargo_test_wasm.stderr).unwrap()
            );
        }
        println!(
            "test stdout:\n{}",
            String::from_utf8(cargo_test_wasm.stdout).unwrap()
        );
        assert!(cargo_test_wasm.status.success());
    } else if wasm_expected {
        let cargo_build_wasm = tool_cmd("cargo")
            .arg("build")
            .current_dir(&wasm_export_dir)
            .output()
            .unwrap();
        if !cargo_build_wasm.status.success() {
            eprintln!(
                "wasm build stderr:\n{}",
                String::from_utf8(cargo_build_wasm.stderr).unwrap()
            );
        }
        assert!(cargo_build_wasm.status.success());
    }
    // If the test ships a node round-trip script, build the bindings with wasm-pack and run them
    // under node. This is the ONLY layer that executes generated bindings in a JS engine, so it's
    // what catches Rust<->JS serialization-shape bugs (e.g. serde-wasm-bindgen emitting a JS `Map`
    // where the JSON/TS type says object) that `cargo build` and the snapshot suite can't observe.
    let roundtrip_script = test_path.join("roundtrip.mjs");
    if roundtrip_script.exists() {
        if tool_exists("wasm-pack") && tool_exists("node") {
            println!("   ------ testing (wasm json roundtrip) ------");
            let wasm_pack = tool_cmd("wasm-pack")
                .args(["build", "--target=nodejs", "--dev"])
                .current_dir(&wasm_export_dir)
                .output()
                .unwrap();
            if !wasm_pack.status.success() {
                eprintln!(
                    "wasm-pack stderr:\n{}",
                    String::from_utf8_lossy(&wasm_pack.stderr)
                );
            }
            assert!(wasm_pack.status.success());
            // Absolute path: node's require() treats a bare relative path as a node_modules lookup.
            let pkg_dir = std::fs::canonicalize(wasm_export_dir.join("pkg")).unwrap();
            let node = std::process::Command::new("node")
                .arg(&roundtrip_script)
                .arg(&pkg_dir)
                .output()
                .unwrap();
            print!("{}", String::from_utf8_lossy(&node.stdout));
            if !node.status.success() {
                eprintln!("node stderr:\n{}", String::from_utf8_lossy(&node.stderr));
            }
            assert!(node.status.success());
        } else {
            // Don't let CI silently skip the only JS-execution coverage we have.
            assert!(
                std::env::var_os("CI").is_none(),
                "wasm-pack and node are required to run {roundtrip_script:?} in CI"
            );
            eprintln!("skipping {roundtrip_script:?}: wasm-pack/node not found");
        }
    }
    // Run (not just build) the JSON schema export crate so its `main()` -> `export_schemas()`
    // actually executes: it creates the `schemas/` dir and writes the one `<lib>.schema.json`
    // document. `cargo build` only typechecked that code; nothing ever ran it, so a runtime panic in
    // the generated schema-export body (e.g. a bad path or `schemars` call) was invisible to CI.
    let json_export_dir = test_path.join(format!("{export_path}/wasm/json-gen"));
    if options.contains(&"--json-schema-export=true") {
        assert!(
            json_export_dir.exists(),
            "no json-gen crate at {json_export_dir:?} (--json-schema-export=true was passed) — generation stopped emitting it"
        );
    }
    if json_export_dir.exists() {
        // Stale schemas from a previous local run would satisfy the assertions below even if the
        // current export writes nothing; start from a clean dir (CI is a fresh checkout, so this
        // only matters for the local signal).
        let schemas_dir = json_export_dir.join("schemas");
        let _ = std::fs::remove_dir_all(&schemas_dir);
        let cargo_run_json = tool_cmd("cargo")
            .arg("run")
            .current_dir(&json_export_dir)
            .output()
            .unwrap();
        if !cargo_run_json.status.success() {
            eprintln!(
                "json-gen run stderr:\n{}",
                String::from_utf8(cargo_run_json.stderr).unwrap()
            );
        }
        assert!(cargo_run_json.status.success());
        // `export_schemas()` succeeding isn't enough: a no-op body would also exit 0. Assert it
        // wrote exactly ONE `*.schema.json` document and nothing else — `run-json2ts.js` rejects a
        // schemas dir holding anything but the single document, so a stray file here would be a
        // green Rust run that reddens the JS step.
        let written: Vec<String> = std::fs::read_dir(&schemas_dir)
            .unwrap_or_else(|e| panic!("json-gen wrote no schemas dir {schemas_dir:?}: {e}"))
            .filter_map(Result::ok)
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|name| name.ends_with(".json"))
            .collect();
        assert_eq!(
            written.len(),
            1,
            "json-gen must write exactly one schema document in {schemas_dir:?}, got {written:?}"
        );
        assert!(
            written[0].ends_with(".schema.json"),
            "json-gen's schema document must be named `<lib>.schema.json`, got {written:?}"
        );
        let document: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(schemas_dir.join(&written[0])).unwrap())
                .unwrap_or_else(|e| panic!("{:?} is not valid JSON: {e}", written[0]));
        let defs = document
            .get("$defs")
            .and_then(|d| d.as_object())
            .unwrap_or_else(|| panic!("{:?} has no `$defs` object:\n{document:#}", written[0]));
        assert!(
            !defs.is_empty(),
            "json-gen produced an empty `$defs` in {:?}",
            written[0]
        );
        // Row-set sanity: every `reg.add::<T>()` row lands in `$defs` by construction (the runtime
        // helper publishes an inline-schema type under its own name rather than letting
        // `subschema_for` drop it), and `$defs` additionally holds every type reached transitively.
        // So `$defs` is never SMALLER than the row set. The only way it could be is two rows whose
        // `schema_name()` collide — no fixture has that, and a new one that does should be looked at
        // rather than accommodated here.
        //
        // `reg.add::<` is the row spelling; it matches no import line and no other emitted
        // construct, so the count is genuinely the number of ROWS.
        let rows = std::fs::read_to_string(json_export_dir.join("src/generated/mod.rs"))
            .unwrap()
            .matches("reg.add::<")
            .count();
        assert!(
            defs.len() >= rows,
            "json-gen document {:?} has {} `$defs` entries for {rows} registration rows — a row's \
             type silently failed to land in the document",
            written[0],
            defs.len()
        );
        // `--json-schema-root` extra roots: a type named by NO CDDL rule must still reach the
        // document, since the flag's registration row is its ONLY route in. The expected `$defs` key
        // is derived from the flag value (last `::` segment, generic arguments stripped), which is
        // exactly what `schema_name()` returns for a `#[derive(schemars::JsonSchema)]` type — true of
        // every fixture root today. A future fixture whose extra root has a hand-written
        // `schema_name()` that differs from its type name needs this lifted to an explicit per-fixture
        // expectation, not relaxed here.
        for root in options
            .iter()
            .filter_map(|arg| arg.split_once("--json-schema-root=").map(|(_, v)| v))
        {
            let expected = root
                .split('<')
                .next()
                .unwrap()
                .rsplit("::")
                .next()
                .unwrap()
                .trim();
            assert!(
                defs.contains_key(expected),
                "fixture {dir}: --json-schema-root={root} produced no `{expected}` entry in the \
                 json-gen document {:?} — an extra root named by no CDDL rule never reached `$defs`",
                written[0]
            );
        }
        // Reference closure: the document is self-contained. Every `$ref` in it must be an INTERNAL
        // pointer at one of its own `$defs` keys, so "which types can dangle?" is a check rather than
        // an argument. A dangling ref ships as a `.d.ts` that references a type it never declares
        // (`TS2304`), and it is what a hand-written `JsonSchema` impl returning a bare
        // `Schema::new_ref("SomeType")` produces.
        let mut refs = Vec::new();
        collect_schema_refs(&document, &mut refs);
        for reference in &refs {
            let key = reference
                .strip_prefix("#/$defs/")
                .map(decode_schema_ref_name)
                .unwrap_or_else(|| {
                    panic!(
                        "fixture {dir}: json-gen document {:?} holds the non-internal reference \
                         `{reference}` — every `$ref` must be `#/$defs/<key>` into this same document",
                        written[0]
                    )
                });
            assert!(
                defs.contains_key(&key),
                "fixture {dir}: json-gen document {:?} references `{reference}`, but `{key}` is not \
                 a `$defs` key — the shipped `.d.ts` would reference a type it never declares",
                written[0]
            );
        }
        // The document is a published artifact a consumer diffs across regenerations, and it is
        // built by walking a live `SchemaGenerator` rather than by printing a sorted list — so
        // "same inputs, same bytes" is a property of the RUNTIME here, not only of the emitter.
        // Re-run the same binary and compare (the emitter's own byte-stability is pinned in the fast
        // tier by `snapshot_tests::json_gen_rows_are_byte_stable`).
        let first_document = std::fs::read(schemas_dir.join(&written[0])).unwrap();
        let rerun = tool_cmd("cargo")
            .arg("run")
            .current_dir(&json_export_dir)
            .output()
            .unwrap();
        assert!(rerun.status.success());
        assert_eq!(
            first_document,
            std::fs::read(schemas_dir.join(&written[0])).unwrap(),
            "two runs of export_schemas() must write a byte-identical {:?}",
            written[0]
        );
    }
}

/// Generate + gate every `tests/corpus/*.cddl` crate under each emission profile. The snapshot
/// suite (`snapshot_tests::feature_corpus`) only pins the generated *source*, so a construct that
/// emits non-compiling Rust would be snapshotted as "correct"; this is the compile gate for it.
/// Trait imports the usage-derived prune (`crate::import_prune`) deliberately cannot remove: a trait
/// is exercised by a method call whose ident never appears (`x.serialize(..)` for `cbor_event`'s
/// `Serialize`), so name-scanning can't prove it unused. The generated serialization prelude imports
/// `Serialize` (non-canonical profiles) and a scope that never calls it warns — an out-of-model
/// residue tracked in `tests/TESTING_ROADMAP.md`'s `unused_imports` entry, NOT a prune regression.
/// Everything else in a PURELY-generated crate is a prune target, so the scan flags it.
const UNUSED_IMPORT_TRAIT_RESIDUE: &[&str] = &["Serialize"];

/// Scan rustc/cargo stderr for rendered `unused import` warnings in the generated crates. These
/// crates are 100% generated, so ANY unused import is a generator imprecision the import prune should
/// have removed — the scan flags every one EXCEPT warnings that name only a documented trait residue
/// (`UNUSED_IMPORT_TRAIT_RESIDUE`). Rustc renders these as a single line `warning: unused import:
/// `PATH`` (or the plural `warning: unused imports: `A`, `B``) with the path(s) inline in backticks;
/// the leaf ident is the last `::` segment (`super::*` → `*`, always flagged). Returns each offending
/// line (trimmed) so the caller can name it in the failure.
fn unused_generated_import_lines(stderr: &str) -> Vec<String> {
    stderr
        .lines()
        .filter_map(|line| {
            if !line.contains("warning: unused import") {
                return None;
            }
            // Leaf ident of every backtick-quoted import path on the line.
            let idents: Vec<&str> = line
                .split('`')
                .skip(1)
                .step_by(2)
                .map(|path| path.rsplit("::").next().unwrap_or(path))
                .collect();
            // A warning naming ONLY documented trait residue is not a prune target.
            if !idents.is_empty()
                && idents
                    .iter()
                    .all(|id| UNUSED_IMPORT_TRAIT_RESIDUE.contains(id))
            {
                return None;
            }
            Some(line.trim().to_string())
        })
        .collect()
}

/// Red-path guard for the scan: an allowlisted ident, a cross-scope user type, and a `super::*` /
/// `error::*` glob unused-import warning are all flagged (a purely-generated crate should carry
/// none), while a warning naming only the documented `Serialize` trait residue is ignored.
#[test]
fn unused_generated_import_scan_flags_prune_targets_and_ignores_trait_residue() {
    for (label, line) in [
        (
            "allowlisted",
            "warning: unused import: `alloc::collections::BTreeMap`\n --> src/generated/mod.rs:3:5",
        ),
        (
            "cross-scope user type",
            "warning: unused import: `governance::Voter`\n --> src/generated/mod.rs:3:5",
        ),
        (
            "super glob",
            "warning: unused import: `super::*`\n --> src/generated/cbor_encodings.rs:4:5",
        ),
        (
            "error glob",
            "warning: unused import: `cml_core::error::*`\n --> src/generated/mod.rs:5:5",
        ),
    ] {
        assert_eq!(
            unused_generated_import_lines(line).len(),
            1,
            "{label} unused import must be flagged"
        );
    }

    let trait_residue = "warning: unused import: `cbor_event::se::Serialize`\n \
                         --> src/generated/serialization.rs:8:5";
    assert!(
        unused_generated_import_lines(trait_residue).is_empty(),
        "the documented Serialize trait residue must be ignored"
    );

    // A clean build has no such warning at all.
    assert!(unused_generated_import_lines("   Compiling foo v0.1.0\n    Finished").is_empty());
}

/// Scan rustc/cargo stderr for rendered `unused variable` warnings in the generated crates. Like the
/// unused-import scan, these crates are 100% generated, so ANY named binding rustc reports as unused
/// is a generator imprecision — e.g. a definite-length count match whose arm body is a compile-time
/// constant (`Some(x) => 3`) should bind `_`, not `x`. Rustc renders these as `warning: unused
/// variable: `x``. There is no trait-residue analogue here (every such binding is generator-owned),
/// so every matching line is returned (trimmed) for the caller to name in the failure.
fn unused_generated_variable_lines(stderr: &str) -> Vec<String> {
    stderr
        .lines()
        .filter(|line| line.contains("warning: unused variable"))
        .map(|line| line.trim().to_string())
        .collect()
}

/// Red-path guard for the variable scan: a real `unused variable` warning is flagged; a clean build
/// and an unrelated unused-import warning are not.
#[test]
fn unused_generated_variable_scan_flags_named_binding() {
    let warning = "warning: unused variable: `x`\n --> src/generated/serialization.rs:24:14";
    assert_eq!(
        unused_generated_variable_lines(warning).len(),
        1,
        "an unused variable in a purely-generated crate must be flagged"
    );
    assert!(unused_generated_variable_lines("   Compiling foo v0.1.0\n    Finished").is_empty());
    assert!(
        unused_generated_variable_lines("warning: unused import: `alloc::collections::BTreeMap`")
            .is_empty()
    );
}

/// Runs all three `default`/`preserve`/`json` profiles the corpus is snapshotted under, since
/// non-compiling output can be flag-specific (a bare construct compiled but its preserve/json
/// variant did not). Generates with `--wasm=true` and `cargo check`s BOTH the `rust` and (when
/// emitted) `wasm` crates — the wasm bindings are a whole output mode nothing else systematically
/// compile-gates. One shared `CARGO_TARGET_DIR` so the deps build once. `int` needs no extern defs
/// here — the generator emits its own `Int` type.
///
/// Under the DEFAULT profile this is also the corpus EXECUTION gate (tests/README.md
/// § "Generated-test harness"):
/// generation adds `--emit-tests` and the rust crate runs `cargo test`, executing the emitted
/// round-trip + reject tests — a corpus construct must round-trip byte-identically, not just
/// compile. One profile keeps the wall-clock bounded (preserve/json stay compile-only for now),
/// and the emitted-module count floor keeps the execution half from going vacuous if emission
/// silently shrinks.
///
/// **Sharded.** The body below is one `#[test]` per [`FEATURE_CORPUS_SHARDS`] slice of the corpus
/// (`feature_corpus_compiles_shard_NN`), so libtest's existing thread pool runs the cells
/// concurrently instead of one test walking them serially. The shard names all contain
/// `feature_corpus_compiles`, so every substring selector that named the old test (`cargo test
/// feature_corpus_compiles`, the docs, `CLOSURE_AUDIT_GATE`) still selects the whole gate. The
/// whole-corpus assertions that no single shard can make live in
/// [`feature_corpus_compiles_pins_are_live`].
fn feature_corpus_entries() -> Vec<std::path::PathBuf> {
    use std::str::FromStr;
    let corpus_dir = std::path::PathBuf::from_str("tests/corpus").unwrap();
    let mut entries: Vec<std::path::PathBuf> = std::fs::read_dir(&corpus_dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().and_then(|e| e.to_str()) == Some("cddl"))
        .collect();
    entries.sort();
    assert!(!entries.is_empty(), "no corpus files in {corpus_dir:?}");
    entries
}

/// The stale-pin half of `feature_corpus_compiles`, which is only correct when ONE test sees EVERY
/// corpus fixture: a shard that walks a slice could not tell "this pin names a fixture that was
/// deleted" from "this pin names a fixture another shard owns", so a naive split would leave both
/// guards vacuous while the suite stayed green. It reads the corpus directory and nothing else — no
/// generation, no cargo — so keeping it whole costs milliseconds.
#[test]
fn feature_corpus_compiles_pins_are_live() {
    let entries = feature_corpus_entries();
    let corpus_stems: std::collections::BTreeSet<&str> = entries
        .iter()
        .map(|p| p.file_stem().unwrap().to_str().unwrap())
        .collect();
    for stem in COMPILE_SKIP {
        assert!(
            corpus_stems.contains(stem),
            "COMPILE_SKIP names corpus fixture `{stem}` that no longer exists in tests/corpus — \
             stale pin, remove or fix it"
        );
    }
    for (stem, _profile, _reason) in EXPECTED_GENERATION_FAIL {
        assert!(
            corpus_stems.contains(stem),
            "EXPECTED_GENERATION_FAIL names corpus fixture `{stem}` that no longer exists in \
             tests/corpus — stale pin, remove or fix it"
        );
    }
}

/// How many `#[test]`s the corpus compile gate is split across. Sized against the gate's own
/// measured scaling, not a core count: its cells are dominated by per-cell generation and the gate
/// cache's `cargo generate-lockfile` preflight, and that preflight serializes on cargo's PROCESS-WIDE
/// `$CARGO_HOME/.package-cache` lock — so past a modest degree extra shards queue rather than run.
/// Measured standalone on this gate: 1 shard 109 s, 12 shards 60 s, 24 shards slower again.
///
/// The preflight half of that ceiling is GONE: `gate_cache` memoizes the lockfile derivation per
/// distinct manifest set, which took this gate from 568 `cargo generate-lockfile` processes to 21
/// and its standalone wall from 26.4 s to 16.0 s. The count above is left at its measured value
/// because the scaling has NOT been re-measured since — re-measure before raising it, do not assume
/// the old curve still describes the gate.
const FEATURE_CORPUS_SHARDS: usize = 6;

/// Cross-shard accumulator for the execution-half vacuous-pass guard. The floor ("at least 38 of the
/// corpus fixtures emit a generated-test module") is a property of the WHOLE corpus, so no shard can
/// check it alone; the shard that completes the set checks it. Every full `cargo test`, and every
/// substring selector that names the gate, runs all [`FEATURE_CORPUS_SHARDS`] shards and so fires the
/// guard exactly once. A run that selects a SINGLE shard by exact name does not complete the set and
/// does not check the floor — the same way a run that filtered the unsharded gate out did not.
static FEATURE_CORPUS_EMITTED_TEST_MODULES: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
static FEATURE_CORPUS_SHARDS_COMPLETED: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
/// Occupancy counter for the shards' one shared scratch root (see [`SharedScratch`]).
static FEATURE_CORPUS_SCRATCH: std::sync::Mutex<usize> = std::sync::Mutex::new(0);

macro_rules! feature_corpus_compiles_shards {
    ($($name:ident = $shard:expr;)+) => {
        $(
            #[test]
            fn $name() {
                feature_corpus_compiles_shard($shard);
            }
        )+
    };
}

feature_corpus_compiles_shards! {
    feature_corpus_compiles_shard_00 = 0;
    feature_corpus_compiles_shard_01 = 1;
    feature_corpus_compiles_shard_02 = 2;
    feature_corpus_compiles_shard_03 = 3;
    feature_corpus_compiles_shard_04 = 4;
    feature_corpus_compiles_shard_05 = 5;
}

/// One slice of the corpus. The unsharded loop accumulated every cell's failure and asserted once at
/// the end, so a single failure named every problem; each shard keeps that batching for ITS OWN
/// cells, and libtest reports every failing shard in a run — so a run still surfaces every problem,
/// grouped by shard rather than in one list.
fn feature_corpus_compiles_shard(shard: usize) {
    // The component profile is filtered out BY NAME: the component crate is a **wasip2** target and
    // this gate compiles for the HOST (`crate_subs` below is rust/wasm, and no `--target` appears
    // anywhere in the gate), so it structurally cannot compile-gate `component/`. That face's
    // compile coverage is `component_tests::component_crate_builds_for_wasm32_wasip2`; its
    // corpus-breadth verdict is `component_tests::component_wit_validates_the_corpus`.
    let profiles: Vec<super::Profile> = super::ALL_PROFILES
        .iter()
        .filter(|(profile, _)| *profile != super::COMPONENT_PROFILE)
        .copied()
        .collect();
    let all_entries = feature_corpus_entries();
    // Round-robin over the SORTED list, so which fixture lands in which shard is deterministic and
    // reproducible from the corpus alone — a failure names its cell, and rerunning that shard
    // reproduces it.
    let entries: Vec<&std::path::PathBuf> = all_entries
        .iter()
        .enumerate()
        .filter(|(i, _)| i % FEATURE_CORPUS_SHARDS == shard)
        .map(|(_, p)| p)
        .collect();

    // Scratch dir + one shared target so cbor_event & friends build once (~30 tiny crates × 3),
    // shared across the shards (see `SharedScratch` for the wipe contract).
    let scratch = SharedScratch::enter(
        &FEATURE_CORPUS_SCRATCH,
        std::env::temp_dir().join(format!(
            "cddl_codegen_corpus_compile_{:016x}",
            checkout_hash()
        )),
    );
    let root = scratch.root().to_path_buf();
    let target_dir = root.join("target");

    let mut failures = vec![];
    let mut emitted_test_modules = 0usize;
    let mut cache_run = 0usize;
    let mut cache_hit = 0usize;
    for input in entries {
        let stem = input.file_stem().unwrap().to_str().unwrap();
        if COMPILE_SKIP.contains(&stem) {
            continue;
        }
        for (profile, extra) in &profiles {
            let label = format!("{stem}/{profile}");
            let out = root.join(format!("{stem}__{profile}"));
            let emit_tests = *profile == "default";
            // generate rust + wasm so both crates are compile-gated
            let gen_out = codegen_cmd()
                .arg(format!("--input={}", input.to_str().unwrap()))
                .arg(format!("--output={}", out.to_str().unwrap()))
                .arg("--wasm=true")
                .args(if emit_tests {
                    &["--emit-tests=true"][..]
                } else {
                    &[][..]
                })
                .args(*extra)
                .output()
                .unwrap();
            let expected_gen_fail = EXPECTED_GENERATION_FAIL
                .iter()
                .any(|(s, p, _)| *s == stem && *p == *profile);
            if !gen_out.status.success() {
                if !expected_gen_fail {
                    failures.push(format!(
                        "{label}: generation failed\n{}",
                        String::from_utf8_lossy(&gen_out.stderr)
                    ));
                }
                // Expected aborts don't compile-gate (there is no crate to check); unexpected ones
                // were already recorded. Either way, move on.
                continue;
            }
            if expected_gen_fail {
                // Resurfaced guard: a fixture ledgered as expected-generation-fail under this
                // profile now GENERATES — the tracked unimplemented path was implemented. Retire
                // the EXPECTED_GENERATION_FAIL entry (and start compile-gating this cell).
                failures.push(format!(
                    "{label}: generation SUCCEEDED but is pinned in EXPECTED_GENERATION_FAIL — \
                     the gap closed; remove the pin so this cell is compile-gated"
                ));
                continue;
            }
            // cargo check the generated rust crate, then the wasm crate, and — under the json
            // profile — the json-gen crate. The wasm crate is a whole output mode nothing else
            // systematically compile-gates; a host `cargo check` catches type/signature errors in
            // the generated bindings (wrong accessor return type, boundary `.into()`/`.clone()`
            // slips) without needing the wasm32 target — `wasm-bindgen` is just a normal dependency
            // and the shared target dir amortizes its build. json-gen is an INDEPENDENT nested
            // crate (not a dependency of wasm/), so checking wasm/ never touches it, yet its
            // per-fixture `export_schemas()` body is snapshot-pinned by feature_corpus — leaving it
            // out re-opens the exact hole this gate exists to close.
            let crate_subs: &[&str] = if *profile == "json" {
                &["rust", "wasm", "wasm/json-gen"]
            } else {
                &["rust", "wasm"]
            };
            let mut command_plan = Vec::new();
            let mut manifest_subpaths = Vec::new();
            let mut missing_crates = false;
            for crate_sub in crate_subs.iter().copied() {
                let crate_dir = out.join(crate_sub);
                if !crate_dir.exists() {
                    // A missing crate de-gates the fixture: that's a failure, not a skip (mirrors
                    // wasm_matrix_compiles). Every fixture emits rust/, and with --wasm=true also
                    // wasm/ (+ json-gen under the json profile) — if that ever becomes legitimately
                    // untrue for a fixture, allowlist it explicitly like COMPILE_SKIP.
                    failures.push(format!(
                        "{label} ({crate_sub}): crate dir missing — the fixture is no longer being compile-gated"
                    ));
                    missing_crates = true;
                    continue;
                }
                // Under the default profile (where `--emit-tests` is passed) both the rust AND the
                // wasm crate EXECUTE their emitted tests (strictly stronger than check: `cargo test`
                // compiles the lib and runs the round-trip/reject module). `cargo check` never
                // compiles `#[cfg(test)]` code, so the wasm crate's emitted `cddl_generated_wasm_tests`
                // module (cross-crate byte differential + wire round-trip + accessor read-back) is only
                // type-checked and executed under `cargo test` — giving the corpus its wasm ROUND-TRIP
                // coverage, not just wasm compile coverage. json-gen stays check-only (json profile,
                // no --emit-tests). preserve/json profiles stay check-only throughout.
                let cargo_cmd = if emit_tests && (crate_sub == "rust" || crate_sub == "wasm") {
                    "test"
                } else {
                    "check"
                };
                command_plan.push((crate_sub, cargo_cmd));
                manifest_subpaths.push(std::path::PathBuf::from(crate_sub).join("Cargo.toml"));
            }
            if missing_crates {
                continue;
            }
            let mut argv_for_key = Vec::new();
            for (crate_sub, cargo_cmd) in &command_plan {
                argv_for_key.extend([
                    format!("cwd={crate_sub}"),
                    "cargo".to_string(),
                    (*cargo_cmd).to_string(),
                ]);
            }
            // Closure-logic version marker: the cached cell scans stderr for unused-import warnings.
            // v2 broadens that scan from the allowlist-only set to EVERY generated-crate unused import
            // (super::*/error::* globs, cross-scope type imports, wasm macro/prelude imports) minus a
            // documented trait residue. v3 additionally scans for `unused variable` warnings (a named
            // count-match binding the generator never uses) — so pre-v3 cached PASSes must be
            // invalidated. Bump on any future change to the scan's verdict.
            argv_for_key.push("lint=unused-imports-v3".to_string());
            let outcome = gate_cache::run_cached(
                "feature_corpus_compiles",
                &label,
                &out,
                &manifest_subpaths,
                &argv_for_key,
                || {
                    let mut ok = true;
                    for (crate_sub, cargo_cmd) in &command_plan {
                        let crate_dir = out.join(crate_sub);
                        let check = tool_cmd("cargo")
                            .arg(cargo_cmd)
                            .current_dir(&crate_dir)
                            .env("CARGO_TARGET_DIR", &target_dir)
                            .output()
                            .unwrap();
                        let stderr = String::from_utf8_lossy(&check.stderr);
                        if !check.status.success() {
                            failures.push(format!(
                                "{label} ({crate_sub}): cargo {cargo_cmd} failed\n{}\n{}",
                                String::from_utf8_lossy(&check.stdout),
                                stderr
                            ));
                            ok = false;
                        }
                        // Warning-severity residue the compile gates (over-prune only) can't see: an
                        // `unused import` in a PURELY-generated crate means the usage-derived import
                        // prune (crate::import_prune) under-pruned (a documented trait residue aside).
                        // `ok = false` so a warning cell is never cached as PASS.
                        let unused = unused_generated_import_lines(&stderr);
                        if !unused.is_empty() {
                            failures.push(format!(
                                "{label} ({crate_sub}): generated-code unused-import residue — import prune under-pruned:\n{}",
                                unused.join("\n")
                            ));
                            ok = false;
                        }
                        // Same reasoning for `unused variable`: a named binding in a purely-generated
                        // crate is generator imprecision (a count-match arm that should bind `_`).
                        let unused_vars = unused_generated_variable_lines(&stderr);
                        if !unused_vars.is_empty() {
                            failures.push(format!(
                                "{label} ({crate_sub}): generated-code unused-variable residue — generator emitted a named binding it never uses:\n{}",
                                unused_vars.join("\n")
                            ));
                            ok = false;
                        }
                    }
                    ok
                },
            );
            cache_run += outcome.ran();
            cache_hit += outcome.cached();
            if emit_tests
                && std::fs::read_to_string(out.join("rust/src/generated/mod.rs"))
                    .unwrap_or_default()
                    .contains("mod cddl_generated_tests")
            {
                emitted_test_modules += 1;
            }
        }
    }
    if gate_cache::enabled() {
        println!(
            "feature_corpus_compiles shard {shard}/{FEATURE_CORPUS_SHARDS} gate-cache: {cache_run} run, {cache_hit} cached"
        );
    }
    // The shard's own cells first: a failing shard must report its own cells, not the corpus-wide
    // floor it never had the whole of.
    assert!(
        failures.is_empty(),
        "corpus crates failed to compile:\n\n{}",
        failures.join("\n\n")
    );

    // execution-half vacuous-pass guard: most corpus fixtures mint at least one round-trip/reject
    // test today (41 of 44; the rest are transparent aliases / pure c-enums). A big drop means the
    // emitter's coverage silently shrank, not that the corpus got simpler. Corpus-wide, so it is
    // accumulated across shards and checked by whichever shard completes the set.
    //
    // Order matters: every shard publishes its count BEFORE announcing completion, so the shard
    // whose completion makes the set whole is guaranteed to observe every other shard's count.
    // Reading the accumulator after that check (not the `fetch_add` return) is what makes that
    // guarantee usable — the return value is only a snapshot from before the concurrent adds.
    use std::sync::atomic::Ordering;
    FEATURE_CORPUS_EMITTED_TEST_MODULES.fetch_add(emitted_test_modules, Ordering::SeqCst);
    if FEATURE_CORPUS_SHARDS_COMPLETED.fetch_add(1, Ordering::SeqCst) + 1 == FEATURE_CORPUS_SHARDS {
        let total = FEATURE_CORPUS_EMITTED_TEST_MODULES.load(Ordering::SeqCst);
        assert!(
            total >= 38,
            "only {total} corpus fixtures emitted a generated-test module (expected >= 38) — emit_tests coverage shrank"
        );
    }
}

/// Standing, table-driven sweep over the generator's synthesized wasm-boundary idents. The generator
/// mints structural wasm classes whose names derive from user type names (`intermediate/rust_type.rs`):
/// F1 plain list `{Elem}List` (`name_as_wasm_array_ct`), F2 table builder `Map{K}To{V}`
/// (`name_for_wasm_map`), F3 `NonEmpty{Elem}List` (`non_empty_wasm_wrapper_name`), F4
/// `NonEmptyMap{K}To{V}` (`non_empty_wasm_map_wrapper_name`), and F5 the table `keys()` list wrapper
/// (`mint_wasm_wrapper_for_visited_type`). Each cell below crosses a family with one interaction
/// against user rule names and enforces the invariant **no cell may be exit-0 with a non-compiling
/// crate**: every cell is pinned to either
///   - `Reject(ident)` — a GRACEFUL rejection (the IR-level NonEmpty collision scans for F3/F4, or
///     the generation-time duplicate-ident backstop at the `generated_files` seam for the plain
///     F1/F2/F5 families that have no IR scan) whose message names the colliding ident; or
///   - `Ok { present, absent }` — the cell generates AND its wasm crate compiles. The Ok rows are
///     batched into ONE crate whose wasm binding is `cargo check`ed (the `feature_corpus_compiles`
///     pattern, shared `CARGO_TARGET_DIR`) — the "AND a compiling crate" leg. `present`/`absent`
///     additionally pin dedup semantics against the batched source (dedup target defined once, the
///     synthesized twin never emitted); the backstop already guarantees ≤ 1 definition per ident,
///     so `present` asserting exactly-once is the "the dedup target exists" complement.
///
/// The four interactions (a cell is SKIPPED, with a reason, where an interaction is structurally
/// inexpressible for a family):
///   - I-a: a user rule of a DIFFERENT shape claiming the family's synthesized name;
///   - I-b: a named same-shape rule coexisting with an inline occurrence (dedup or clean coexistence);
///   - I-c: a self-named rule (rule ident == the structural name its own shape would mint inline);
///   - I-d: a different-shape claim of a NEEDED AUXILIARY ident — for F3/F4 the restricted wrapper's
///     loose `try_from`-source builder. Inexpressible for F1/F2 (the loose family's wrapper IS its
///     own builder — no separate auxiliary) and for F5 (its synthesized name already IS the keys()
///     auxiliary, so I-d would coincide with I-a).
///
/// Every rule ident is cell-prefixed so these NAME-LOCAL failure classes can't mask across cells
/// when the Ok rows share one crate (cf. the `LAYER2_RULES_PER_BATCH` batch-masking lesson in
/// `recombination_tests.rs`): distinct idents structurally exclude cross-cell interference. The
/// probe that seeded these expectations found NO exit-0-non-compiling cell — every collision is
/// either an IR-scan or backstop rejection, or compiles — so there is no known-bad ledger here; a
/// future cell that lands exit-0 + non-compiling is a NEW instance of the class and must be fixed
/// or explicitly ledgered, never blessed by loosening a row to `Ok`.
#[test]
fn synthesized_name_interaction_sweep() {
    use clap::Parser;

    enum Expect {
        /// graceful rejection whose message must contain this substring (the colliding ident)
        Reject(&'static str),
        /// generates + the batched wasm crate compiles; the batched wasm source must define each
        /// `present` ident exactly once and NONE of the `absent` idents (the deduped-away twins)
        Ok {
            present: &'static [&'static str],
            absent: &'static [&'static str],
        },
    }
    use Expect::{Ok as ExpectOk, Reject};

    // (cell id, CDDL, expected outcome). Non-exposable record element (`[x: uint]`) so the wrappers
    // actually mint; exposable map keys (`text`) except F5, which deliberately uses a non-exposable
    // key to mint the keys() list wrapper.
    let cells: &[(&str, &str, Expect)] = &[
        // F1 — plain list `{Elem}List` (inline `[* elem]`, non-exposable element)
        (
            "F1 x I-a",
            "f1a_bar = [x: uint]\nf1a_bar_list = tstr\nf1a_holder = { xs: [* f1a_bar] }\n",
            Reject("F1aBarList"),
        ),
        (
            "F1 x I-b",
            "f1b_bar = [x: uint]\nf1b_things = [* f1b_bar]\nf1b_holder = { xs: [* f1b_bar] }\n",
            // a differently-named plain-list rule and the inline mint coexist (no plain-array
            // owner-dedup: each keeps its own class)
            ExpectOk {
                present: &["F1bThings", "F1bBarList"],
                absent: &[],
            },
        ),
        (
            "F1 x I-c",
            "f1c_bar = [x: uint]\nf1c_bar_list = [* f1c_bar]\nf1c_holder = { xs: [* f1c_bar] }\n",
            // self-named plain-list rule owns the ident; the inline `[* elem]` shares it (idempotent
            // mint), so exactly one `F1cBarList`
            ExpectOk {
                present: &["F1cBarList"],
                absent: &[],
            },
        ),
        // F1 x I-d SKIPPED: the plain-list family's wrapper IS its own loose builder — no separate
        // auxiliary ident exists to claim.

        // F2 — table builder `Map{K}To{V}` (inline `{* text => elem}`)
        (
            "F2 x I-a",
            "f2a_bar = [x: uint]\nmap_text_to_f2a_bar = tstr\nf2a_holder = { m: {* text => f2a_bar} }\n",
            Reject("MapTextToF2aBar"),
        ),
        (
            "F2 x I-b",
            "f2b_bar = [x: uint]\nf2b_things = {* text => f2b_bar}\nf2b_holder = { m: {* text => f2b_bar} }\n",
            // a named table rule owns the shape; the inline use routes to it (sole-owner), and the
            // structural `MapTextToF2bBar` survives as an alias onto that owner — both defined
            ExpectOk {
                present: &["F2bThings", "MapTextToF2bBar"],
                absent: &[],
            },
        ),
        (
            "F2 x I-c",
            "f2c_bar = [x: uint]\nmap_text_to_f2c_bar = {* text => f2c_bar}\nf2c_holder = { m: {* text => f2c_bar} }\n",
            // self-named table rule IS the sole owner; the inline shares it — exactly one class
            ExpectOk {
                present: &["MapTextToF2cBar"],
                absent: &[],
            },
        ),
        // F2 x I-d SKIPPED: same as F1 — the table-builder wrapper IS its own loose builder.

        // F3 — `NonEmpty{Elem}List` (inline `[+ elem]`)
        (
            "F3 x I-a",
            "f3a_bar = [x: uint]\nnon_empty_f3a_bar_list = tstr\nf3a_holder = { xs: [+ f3a_bar] }\n",
            Reject("NonEmptyF3aBarList"),
        ),
        (
            "F3 x I-b",
            "f3b_bar = [x: uint]\nf3b_things = [+ f3b_bar]\nf3b_holder = { xs: [+ f3b_bar] }\n",
            // inline `[+ elem]` dedups to the named `[+ elem]` rule (`non_empty_named_owner`): the
            // synthesized `NonEmptyF3bBarList` is NOT minted; the loose `F3bBarList` builder IS
            // (the restricted wrapper's non-exposable-element `try_from` source)
            ExpectOk {
                present: &["F3bThings", "F3bBarList"],
                absent: &["NonEmptyF3bBarList"],
            },
        ),
        (
            "F3 x I-c",
            "f3c_bar = [x: uint]\nnon_empty_f3c_bar_list = [+ f3c_bar]\nf3c_holder = { xs: [+ f3c_bar] }\n",
            // self-named `[+ elem]` rule whose ident IS the structural `NonEmpty…` name: it owns the
            // restricted wrapper, the inline dedups to it, and the loose builder still mints
            ExpectOk {
                present: &["NonEmptyF3cBarList", "F3cBarList"],
                absent: &[],
            },
        ),
        (
            "F3 x I-d",
            "f3d_bar = [x: uint]\nf3d_bar_list = tstr\nf3d_holder = { xs: [+ f3d_bar] }\n",
            // the inline `[+ elem]` wrapper needs the loose `F3dBarList` builder as its `try_from`
            // source; a different-shape rule claims that auxiliary ident -> IR-scan rejection
            Reject("F3dBarList"),
        ),
        // F4 — `NonEmptyMap{K}To{V}` (inline `{+ text => elem}`)
        (
            "F4 x I-a",
            "f4a_bar = [x: uint]\nnon_empty_map_text_to_f4a_bar = tstr\nf4a_holder = { m: {+ text => f4a_bar} }\n",
            Reject("NonEmptyMapTextToF4aBar"),
        ),
        (
            "F4 x I-b",
            "f4b_bar = [x: uint]\nf4b_things = {+ text => f4b_bar}\nf4b_holder = { m: {+ text => f4b_bar} }\n",
            // map-side twin of F3 x I-b: inline dedups to the named `{+ …}` rule; the loose
            // `MapTextToF4bBar` builder mints; the synthesized `NonEmptyMapTextToF4bBar` does not
            ExpectOk {
                present: &["F4bThings", "MapTextToF4bBar"],
                absent: &["NonEmptyMapTextToF4bBar"],
            },
        ),
        (
            "F4 x I-c",
            "f4c_bar = [x: uint]\nnon_empty_map_text_to_f4c_bar = {+ text => f4c_bar}\nf4c_holder = { m: {+ text => f4c_bar} }\n",
            ExpectOk {
                present: &["NonEmptyMapTextToF4cBar", "MapTextToF4cBar"],
                absent: &[],
            },
        ),
        (
            "F4 x I-d",
            "f4d_bar = [x: uint]\nmap_text_to_f4d_bar = tstr\nf4d_holder = { m: {+ text => f4d_bar} }\n",
            Reject("MapTextToF4dBar"),
        ),
        // F5 — table `keys()` list wrapper (`{* elem => text}`, non-exposable KEY mints the list)
        (
            "F5 x I-a",
            "f5a_bar = [x: uint]\nf5a_bar_list = tstr\nf5a_holder = { m: {* f5a_bar => text} }\n",
            // the keys() list wrapper `F5aBarList` (no IR scan for this family) collides with a
            // different-shape rule -> backstop rejection at the `generated_files` seam
            Reject("F5aBarList"),
        ),
        (
            "F5 x I-b",
            "f5b_bar = [x: uint]\nf5b_holder = { m: {* f5b_bar => text}, xs: [* f5b_bar] }\n",
            // the table's keys() list and an inline plain `[* elem]` both want `F5bBarList` — they
            // dedup to one (idempotent mint), coexisting with the table builder
            ExpectOk {
                present: &["F5bBarList"],
                absent: &[],
            },
        ),
        (
            "F5 x I-c",
            "f5c_bar = [x: uint]\nf5c_bar_list = [* f5c_bar]\nf5c_holder = { m: {* f5c_bar => text} }\n",
            // self-named plain-list rule owns `F5cBarList`; the table's keys() wrapper shares it
            ExpectOk {
                present: &["F5cBarList"],
                absent: &[],
            },
        ),
        // F5 x I-d SKIPPED: F5's synthesized name IS the keys() auxiliary ident, so a
        // different-shape claim of it coincides with F5 x I-a above.
    ];

    // Count line-anchored top-level type-namespace definitions of `ident` — the same class the
    // duplicate-ident backstop keys on (`generation/export.rs::top_level_type_ident`).
    fn count_def(src: &str, ident: &str) -> usize {
        src.lines()
            .filter(|line| {
                ["pub struct ", "pub enum ", "pub type "]
                    .iter()
                    .filter_map(|kw| line.strip_prefix(kw))
                    .any(|rest| {
                        rest.split(|c: char| !(c.is_alphanumeric() || c == '_'))
                            .next()
                            == Some(ident)
                    })
            })
            .count()
    }

    // --- Reject leg: each reject cell rejects GRACEFULLY in-process (no cargo), message-asserted ---
    let mut reject_count = 0usize;
    let mut ok_batch = String::new();
    let mut ok_checks: Vec<(&str, &[&str], &[&str])> = Vec::new();
    for (i, (id, cddl, expect)) in cells.iter().enumerate() {
        match expect {
            Reject(ident) => {
                reject_count += 1;
                let spec = std::env::temp_dir().join(format!(
                    "cddl_codegen_synth_sweep_{:016x}_{i}.cddl",
                    checkout_hash()
                ));
                std::fs::write(&spec, cddl).unwrap();
                let cli = crate::cli::Cli::parse_from([
                    "cddl-codegen",
                    &format!("--input={}", spec.to_str().unwrap()),
                    "--output=synth_sweep_unused",
                    "--wasm=true",
                ]);
                let msg = crate::api::generated_strings(&cli)
                    .map_err(|e| e.to_string())
                    .err()
                    .unwrap_or_else(|| {
                        panic!(
                            "{id}: expected a graceful rejection naming '{ident}', but it generated"
                        )
                    });
                let _ = std::fs::remove_file(&spec);
                assert!(
                    msg.contains(ident),
                    "{id}: the rejection must name the colliding ident '{ident}', got: {msg}"
                );
            }
            ExpectOk { present, absent } => {
                ok_batch.push_str(cddl);
                ok_checks.push((id, present, absent));
            }
        }
    }
    assert!(
        reject_count > 0 && !ok_checks.is_empty(),
        "sweep went vacuous: {reject_count} reject cells, {} ok cells",
        ok_checks.len()
    );

    // --- Ok leg: batch every generating cell into ONE crate, generate, `cargo check` the wasm
    // crate, then pin the dedup semantics against the batched wasm source. Cell-prefixed idents make
    // the batch equivalent to running the cells separately (no cross-cell name interference). ---
    let root = std::env::temp_dir().join(format!(
        "cddl_codegen_synth_sweep_batch_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&root);
    let spec = root.join("batch.cddl");
    let out = root.join("out");
    let target_dir = root.join("target");
    std::fs::create_dir_all(&root).unwrap();
    std::fs::write(&spec, &ok_batch).unwrap();

    let gen_out = codegen_cmd()
        .arg(format!("--input={}", spec.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--wasm=true")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "batched Ok-cell generation failed (an Ok cell is secretly a rejection?):\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );

    let wasm_dir = out.join("wasm");
    assert!(
        wasm_dir.exists(),
        "no wasm crate at {wasm_dir:?} — generation stopped emitting it"
    );
    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(&wasm_dir)
        .env("CARGO_TARGET_DIR", &target_dir)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "the batched Ok-cell wasm crate failed to compile — a cell is exit-0 + non-compiling:\n{}\n{}",
        String::from_utf8_lossy(&check.stdout),
        String::from_utf8_lossy(&check.stderr)
    );

    // Join every generated wasm source file so per-cell dedup assertions see the whole surface.
    let gen_dir = wasm_dir.join("src/generated");
    let mut wasm_src = String::new();
    let mut files: Vec<std::path::PathBuf> = std::fs::read_dir(&gen_dir)
        .unwrap_or_else(|e| panic!("cannot read {gen_dir:?}: {e}"))
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("rs"))
        .collect();
    files.sort();
    for f in &files {
        wasm_src.push_str(&std::fs::read_to_string(f).unwrap());
        wasm_src.push('\n');
    }

    for (id, present, absent) in &ok_checks {
        for ident in *present {
            assert_eq!(
                count_def(&wasm_src, ident),
                1,
                "{id}: expected exactly one top-level definition of '{ident}' in the batched wasm crate"
            );
        }
        for ident in *absent {
            assert_eq!(
                count_def(&wasm_src, ident),
                0,
                "{id}: '{ident}' should have deduped away (it must NOT be defined) in the batched wasm crate"
            );
        }
    }
    let _ = std::fs::remove_dir_all(&root);
}

/// Pins the documented first-run experience in `docs/docs/getting_started.mdx`: that doc tells a new
/// user to run `cargo run -- --input=example/test.cddl --output=export` (and the release-binary
/// variant) as their very first command, so `example/test.cddl` must always generate a crate that
/// actually compiles — a silent break here is the worst kind of docs rot (it greets every newcomer).
/// This runs that command VERBATIM (no extra flags, so the test can't drift from what the doc
/// promises — wasm is emitted by default, so the wasm crate is gated too), generating into
/// `example/export` just like the doc, then `cargo check`s BOTH the generated rust crate and the
/// generated wasm crate. One shared `CARGO_TARGET_DIR` (the `feature_corpus_compiles`
/// pattern) so the deps build once. Hand-rolled rather than `run_test` on purpose: `run_test`
/// requires a `tests.rs` round-trip fixture, and `example/` deliberately ships only the spec (its
/// round-trip coverage is `--emit-tests`' job) — so this gate is generate + check, nothing appended.
#[test]
fn getting_started_example() {
    let input = std::path::Path::new("example/test.cddl");
    assert!(
        input.exists(),
        "{input:?} is the spec docs/docs/getting_started.mdx runs verbatim — it must exist"
    );
    let out = std::path::Path::new("example/export");

    // Scratch target dir so cbor_event & wasm-bindgen build once for both crate checks below.
    let root = std::env::temp_dir().join(format!(
        "cddl_codegen_getting_started_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&root);
    let target_dir = root.join("target");

    // The documented command, verbatim.
    let gen_out = codegen_cmd()
        .arg(format!("--input={}", input.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "generation from {input:?} failed:\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );

    for crate_sub in ["rust", "wasm"] {
        let crate_dir = out.join(crate_sub);
        assert!(
            crate_dir.exists(),
            "no {crate_sub} crate at {crate_dir:?} — generation stopped emitting it"
        );
        let check = tool_cmd("cargo")
            .arg("check")
            .current_dir(&crate_dir)
            .env("CARGO_TARGET_DIR", &target_dir)
            .output()
            .unwrap();
        assert!(
            check.status.success(),
            "cargo check failed for the {crate_sub} crate generated from {input:?}:\n{}\n{}",
            String::from_utf8_lossy(&check.stdout),
            String::from_utf8_lossy(&check.stderr)
        );
    }
    let _ = std::fs::remove_dir_all(&root);
}

/// The dep-side compiled self-check (`generated/extern_interface_check.rs`) is emitted into every
/// crate and references `crate::generated::<Type>` for every exported name, so a bad path or an
/// unsatisfiable bound is a REAL build break. This generates the `tests/extern-interface-check`
/// fixture — every row projects to a tool-generated rust surface, so no hand-written externs are
/// needed — and `cargo check`s the rust crate WITH the self-check present. Covers
/// `Serialize`(+`Deserialize`), the WEAKENED Serialize-only bound (the ambiguous-optional `ambig`
/// has no generated deserialize), the `use` existence checks (transparent aliases / c-style enum /
/// named collections), the `@no_alias` skip, and the group-body row's four-bound assertion (a
/// referenced plain group asserting whole-value + embedded-group Serialize/Deserialize). The
/// raw-bytes + hand-written-extern + generic-base
/// paths compile-check through `extern_generic_raw_bytes` (a `run_test` fixture whose crate now also
/// carries the self-check). Modeled on `getting_started_example`.
#[test]
fn extern_interface_check_compiles() {
    let input = std::path::Path::new("tests/extern-interface-check/inputs");
    assert!(
        input.exists(),
        "{input:?} is the self-check compile fixture — it must exist"
    );
    let root = std::env::temp_dir().join(format!(
        "cddl_codegen_extern_interface_check_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&root);
    let out = root.join("gen");

    let gen_out = codegen_cmd()
        .arg(format!("--input={}", input.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--wasm=false")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "generation from {input:?} failed:\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );
    let check_rs = out.join("rust/src/generated/extern_interface_check.rs");
    assert!(
        check_rs.exists(),
        "the self-check file must be emitted unconditionally at {check_rs:?}"
    );

    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("rust"))
        .env("CARGO_TARGET_DIR", root.join("target"))
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "cargo check failed for the self-check crate generated from {input:?}:\n{}\n{}",
        String::from_utf8_lossy(&check.stdout),
        String::from_utf8_lossy(&check.stderr)
    );
    let _ = std::fs::remove_dir_all(&root);
}

/// Mutation vector proving the failure mode the self-check design promises: a hand-edited or stale
/// export — one advertising a surface the dep no longer has — fails THIS crate's build NAMING the
/// type. After a clean generation, delete a `pub type` the self-check references (`Coin`),
/// simulating exactly that drift, and assert `cargo check` now FAILS mentioning `Coin`. The clean
/// baseline is `extern_interface_check_compiles` (same fixture + tool), so the failure here is
/// attributable to the mutation alone.
#[test]
fn extern_interface_check_mutation_fails_build() {
    let input = std::path::Path::new("tests/extern-interface-check/inputs");
    let root = std::env::temp_dir().join(format!(
        "cddl_codegen_extern_interface_check_mut_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&root);
    let out = root.join("gen");

    let gen_out = codegen_cmd()
        .arg(format!("--input={}", input.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--wasm=false")
        .output()
        .unwrap();
    assert!(gen_out.status.success(), "generation failed");

    // Mutate the generated crate: drop the `coin` surface the export still advertises (and the
    // self-check still references via `use crate::generated::Coin as _;`).
    let mod_rs = out.join("rust/src/generated/mod.rs");
    let content = std::fs::read_to_string(&mod_rs).unwrap();
    let mutated = content.replace("pub type Coin = u64;\n", "");
    assert_ne!(
        content, mutated,
        "expected `pub type Coin = u64;` in the generated crate to remove"
    );
    std::fs::write(&mod_rs, &mutated).unwrap();

    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("rust"))
        .env("CARGO_TARGET_DIR", root.join("target"))
        .output()
        .unwrap();
    assert!(
        !check.status.success(),
        "removing the `Coin` surface must break the self-check's build"
    );
    let stderr = String::from_utf8_lossy(&check.stderr);
    assert!(
        stderr.contains("Coin"),
        "the build failure must NAME the missing type `Coin`:\n{stderr}"
    );
    let _ = std::fs::remove_dir_all(&root);
}

/// Regression pin for the preservation-overlay sentinel-trap class (feature-requests 03): the two
/// generated sidecar files whose rows track spec rules — `extern_interface_check.rs` (a `use … as _;`
/// / `_assert_*::<…>()` row per exported name) and `key_demand_assertions.rs` (a `_demand_<rule>` fn
/// per `@used_as_key` tag) — must carry NO per-row comments. A trailing/own-line comment on a row a
/// spec change can delete is stranded on the deleted row and re-injected by the edit-preservation
/// overlay as a `// cddl-codegen:unpreserved-comment` + `compile_error!` sentinel that every further
/// regen carries forward (a self-perpetuating trap). This regenerates IN PLACE over prior output
/// (the only path that runs the overlay) with a rule deletion, and asserts neither file gains a trap
/// block. Fixed by making both files banner-only (`generation/export.rs`). In-process via
/// `generate_to_disk` (the overlay lives in the disk-write seam; `generated_strings` never runs it).
#[test]
fn extern_interface_check_regen_over_deletion_no_trap() {
    use clap::Parser;
    let dir = std::env::temp_dir().join(format!(
        "cddl_codegen_check_regen_no_trap_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&dir);
    let input = dir.join("in");
    let output = dir.join("out");
    std::fs::create_dir_all(&input).unwrap();

    // v1: transparent aliases (`use … as _;` rows), a record, and two `@used_as_key` tags (two
    // `_demand_<rule>` fns). v2 deletes `alias_b` and `other_key` (+ the rules referencing them).
    let v1 = "alias_a = uint\n\
              alias_b = tstr\n\
              my_key = [a: uint] ; @used_as_key\n\
              other_key = [b: uint] ; @used_as_key\n\
              wrap = [x: alias_a, y: alias_b]\n\
              stuff = { * my_key => uint }\n\
              more = { * other_key => uint }\n";
    let v2 = "alias_a = uint\n\
              my_key = [a: uint] ; @used_as_key\n\
              wrap = [x: alias_a]\n\
              stuff = { * my_key => uint }\n";

    let regen = |spec: &str| {
        std::fs::write(input.join("lib.cddl"), spec).unwrap();
        let cli = crate::cli::Cli::parse_from([
            "cddl-codegen",
            "--input",
            input.to_str().unwrap(),
            "--output",
            output.to_str().unwrap(),
            "--wasm=false",
        ]);
        crate::api::generate_to_disk(&cli).unwrap_or_else(|e| panic!("generation failed: {e}"));
    };
    regen(v1);
    regen(v2); // regenerate IN PLACE — the overlay reads the v1 files still on disk

    for name in ["extern_interface_check.rs", "key_demand_assertions.rs"] {
        let path = output.join("rust/src/generated").join(name);
        let content = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("{name} must be emitted at {path:?}: {e}"));
        assert!(
            !content.contains("compile_error!"),
            "{name} gained a `compile_error!` sentinel after regen-over-deletion — a deleted row's \
             per-row comment was stranded into the preservation-overlay trap:\n{content}"
        );
        assert!(
            !content.contains("cddl-codegen:unpreserved-comment"),
            "{name} gained a `cddl-codegen:unpreserved-comment` sentinel after regen-over-deletion — \
             the sidecar files must be banner-only so no row can strand a comment:\n{content}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}

/// Pin for feature-requests 03 (the trap corpus) and 04 (rustfmt glue) at once: `extern_interface_check.rs`
/// must carry NO trailing (end-of-line) `//` comment on any row. The fixture's rule-ident order
/// (BTreeMap-by-`RustIdent`: the root `Withdrawals`, then scope `plutus`'s `CostModels`, `RedeemerTag`)
/// differs from rustfmt's import-path sort order, so the pre-fix emission both (a) put a deletable
/// `// <cddl>` marker on every row — the 03 trap source — and (b) had rustfmt reorder the `use` rows
/// and GLUE a moved row's marker onto another line (`… as _; // redeemer_tag // withdrawals`, request
/// 04). Banner-only rows have no marker to strand or glue. Asserts on `generated_strings` output
/// (post-rustfmt, in-process): every `//` in the check file is either the provenance banner or the
/// fixed self-check banner, never a trailing row comment.
#[test]
fn extern_interface_check_has_no_trailing_row_comments() {
    use clap::Parser;
    let dir = std::env::temp_dir().join(format!(
        "cddl_codegen_check_no_trailing_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(dir.join("plutus")).unwrap();
    std::fs::write(
        dir.join("lib.cddl"),
        "withdrawals = { * uint => uint }\n\
         big = [c: cost_models, r: redeemer_tag, w: withdrawals]\n",
    )
    .unwrap();
    std::fs::write(
        dir.join("plutus/mod.cddl"),
        "redeemer_tag = 0 / 1 / 2 / 3\ncost_models = { * uint => uint }\n",
    )
    .unwrap();

    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input",
        dir.to_str().unwrap(),
        "--output",
        "check_no_trailing_unused",
        "--wasm=false",
    ]);
    let files =
        crate::api::generated_strings(&cli).unwrap_or_else(|e| panic!("generation failed: {e}"));
    let _ = std::fs::remove_dir_all(&dir);
    let check = files
        .get("rust/src/generated/extern_interface_check.rs")
        .expect("extern_interface_check.rs must be emitted");

    for line in check.lines() {
        let trimmed = line.trim_start();
        // A trailing comment is a `//` that follows non-comment code on the same line. Own-line
        // banner comments (the only comments allowed here) start with `//` after trimming.
        if trimmed.starts_with("//") {
            continue;
        }
        if let Some(idx) = line.find("//") {
            panic!(
                "extern_interface_check.rs has a trailing `//` comment on a code row — the 03/04 \
                 per-row-marker trap is back (rows must be banner-only): {:?}",
                &line[idx..]
            );
        }
    }
}

/// The wasm-ABI matrix compile-gate. `cddl-matrix/project_wasm_matrix.ts` enumerates the cross-product
/// {wasm-ABI type-shape} × {boundary role} into `tests/matrix_wasm/*.cddl` — one minimal fixture per
/// cell. This generates each `--wasm=true` and `cargo check`s the wasm crate (which pulls the rust crate
/// in as a path dep, so rust-side errors surface here too). It's the *coverage* counterpart to
/// `feature_corpus_compiles`'s oracle: the CBOR-feature corpus doesn't individuate a type's wasm-ABI
/// representation (`is_copy` × `directly_wasm_exposable` × has-a-wrapper-`RustStruct`), so a whole class
/// of boundary bugs (wrong accessor type, bad `.into()`/`.clone()`/by-ref slips, dangling map typedefs)
/// was invisible. Here an un-covered boundary bug shows up as a specific red cell instead of by luck.
///
/// `WASM_MATRIX_SKIP` holds the deliberately-red cells (pre-existing gaps tracked in
/// `cddl-matrix/ROADMAP.md`, plus `extern`, which references a user-supplied type and can't compile
/// standalone). `rawbytes__*` cells also reference a user-supplied type, but its defs are in-repo —
/// `append_raw_bytes_defs` splices them in per cell (same 2 commands, no extra cargo invocation), so
/// those cells compile for real instead of being skipped. A fix lands by taking its cell off
/// `WASM_MATRIX_SKIP` — and the guard below fails if a `WASM_MATRIX_SKIP` cell starts compiling, so
/// the list can't silently rot. A cell that's red but NOT in `WASM_MATRIX_SKIP` fails the test: it's a
/// new wasm-ABI bug to fix or (deliberately, with a ledger entry) skip-list. `cargo check`s only the
/// wasm crate (single default profile) — lighter than `feature_corpus_compiles`. The round-trip
/// upgrade of this gate exists as `wasm_matrix_roundtrips` (manual, full tier); this compile floor
/// stays always-on beside it.
///
/// **Sharded** into `wasm_matrix_compiles_shard_NN` — see [`FEATURE_CORPUS_SHARDS`] for the shape and
/// [`wasm_matrix_compiles_pins_are_live`] for the whole-matrix half. The shard names all contain
/// `wasm_matrix_compiles`, so every substring selector that named the old test still selects the gate.
fn wasm_matrix_entries() -> Vec<std::path::PathBuf> {
    use std::str::FromStr;
    let dir = std::path::PathBuf::from_str("tests/matrix_wasm").unwrap();
    let mut entries: Vec<std::path::PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().and_then(|e| e.to_str()) == Some("cddl"))
        .collect();
    entries.sort();
    assert!(
        !entries.is_empty(),
        "no wasm-matrix fixtures in {dir:?} (run `bun run project_wasm_matrix.ts`)"
    );
    entries
}

/// The stale-pin half of `wasm_matrix_compiles`, kept whole for the reason given on
/// [`feature_corpus_compiles_pins_are_live`]: a shard walking a slice cannot tell a deleted fixture
/// from one another shard owns, so this guard is only correct when one test sees every cell. The
/// four-state per-cell verdict (red/green × listed/unlisted) is decidable per cell and stays in the
/// shards.
#[test]
fn wasm_matrix_compiles_pins_are_live() {
    let entries = wasm_matrix_entries();
    let cell_stems: std::collections::BTreeSet<&str> = entries
        .iter()
        .map(|p| p.file_stem().unwrap().to_str().unwrap())
        .collect();
    for stem in WASM_MATRIX_SKIP {
        assert!(
            cell_stems.contains(stem),
            "WASM_MATRIX_SKIP names cell `{stem}` that no longer exists in tests/matrix_wasm — \
             stale pin, remove or fix it"
        );
    }
}

/// See [`FEATURE_CORPUS_SHARDS`] for why this is sized against measured scaling, not core count.
const WASM_MATRIX_SHARDS: usize = 6;
/// Occupancy counter for the shards' one shared scratch root (see [`SharedScratch`]).
static WASM_MATRIX_SCRATCH: std::sync::Mutex<usize> = std::sync::Mutex::new(0);

macro_rules! wasm_matrix_compiles_shards {
    ($($name:ident = $shard:expr;)+) => {
        $(
            #[test]
            fn $name() {
                wasm_matrix_compiles_shard($shard);
            }
        )+
    };
}

wasm_matrix_compiles_shards! {
    wasm_matrix_compiles_shard_00 = 0;
    wasm_matrix_compiles_shard_01 = 1;
    wasm_matrix_compiles_shard_02 = 2;
    wasm_matrix_compiles_shard_03 = 3;
    wasm_matrix_compiles_shard_04 = 4;
    wasm_matrix_compiles_shard_05 = 5;
}

/// One slice of the wasm-ABI matrix. Each shard batches its own cells' failures and asserts once,
/// exactly as the unsharded loop did for the whole matrix; libtest reports every failing shard, so a
/// run still surfaces every red cell.
fn wasm_matrix_compiles_shard(shard: usize) {
    let all_entries = wasm_matrix_entries();
    let entries: Vec<&std::path::PathBuf> = all_entries
        .iter()
        .enumerate()
        .filter(|(i, _)| i % WASM_MATRIX_SHARDS == shard)
        .map(|(_, p)| p)
        .collect();

    // Scratch dir + one shared target so cbor_event/wasm-bindgen build once, then each tiny crate
    // checks; shared across shards (see `SharedScratch` for the wipe contract).
    let scratch = SharedScratch::enter(
        &WASM_MATRIX_SCRATCH,
        std::env::temp_dir().join(format!("cddl_codegen_wasm_matrix_{:016x}", checkout_hash())),
    );
    let root = scratch.root().to_path_buf();
    let target_dir = root.join("target");

    let mut failures = vec![]; // red cells NOT on WASM_MATRIX_SKIP — real bugs
    let mut resurfaced = vec![]; // WASM_MATRIX_SKIP cells that now compile — remove them
    let mut cache_run = 0usize;
    let mut cache_hit = 0usize;
    for input in entries {
        let stem = input.file_stem().unwrap().to_str().unwrap();
        let skipped = WASM_MATRIX_SKIP.contains(&stem);
        let out = root.join(stem);
        let gen_out = codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=true")
            .output()
            .unwrap();
        if !gen_out.status.success() {
            // A generation failure is also "red". Only a NON-skipped one is a test failure.
            if !skipped {
                failures.push(format!(
                    "{stem}: generation failed\n{}",
                    String::from_utf8_lossy(&gen_out.stderr)
                ));
            }
            continue;
        }
        let wasm_dir = out.join("wasm");
        if !wasm_dir.exists() {
            // Every cell wraps its shape in a composite `holder`, so a wasm crate is always expected.
            // Treat a missing one symmetrically: for a skip cell it means the red is gone ("resurfaced");
            // for a non-skip cell it's a real coverage regression (the cell silently stops being gated),
            // not a pass — fail loudly rather than count it green.
            if skipped {
                resurfaced.push(format!("{stem} (emits no wasm crate)"));
            } else {
                failures.push(format!(
                    "{stem}: generated no wasm crate (expected a wasm wrapper for every cell — the cell \
                     is no longer being compile-gated)"
                ));
            }
            continue;
        }
        // `rawbytes__*` cells resolve `_CDDL_CODEGEN_RAW_BYTES_TYPE_` to a user-supplied type (`PubKey`),
        // undefined in a bare crate. Unlike `extern` (whose defs live only in tests/extern-deps), the raw-bytes
        // defs are in-repo, so append them and the cell compiles for real instead of being skipped.
        if stem.starts_with("rawbytes__") {
            append_raw_bytes_defs(&out, false);
        }
        let argv_for_key = vec![
            "cwd=wasm".to_string(),
            "cargo".to_string(),
            "check".to_string(),
        ];
        let manifest_subpaths = vec![std::path::PathBuf::from("wasm/Cargo.toml")];
        let mut check_output = None;
        let outcome = gate_cache::run_cached(
            "wasm_matrix_compiles",
            stem,
            &out,
            &manifest_subpaths,
            &argv_for_key,
            || {
                let check = tool_cmd("cargo")
                    .arg("check")
                    .current_dir(&wasm_dir)
                    .env("CARGO_TARGET_DIR", &target_dir)
                    .output()
                    .unwrap();
                let success = check.status.success();
                check_output = Some(check);
                success
            },
        );
        cache_run += outcome.ran();
        cache_hit += outcome.cached();
        match (skipped, outcome.success()) {
            (false, false) => failures.push(format!(
                "{stem}: cargo check failed (new wasm-ABI red cell — fix the emitter or, deliberately, \
                 add to WASM_MATRIX_SKIP + cddl-matrix/ROADMAP.md)\n{}",
                String::from_utf8_lossy(&check_output.unwrap().stderr)
            )),
            (true, true) => resurfaced.push(stem.to_string()),
            _ => {} // (false,true)=green as expected; (true,false)=red as expected
        }
    }
    if gate_cache::enabled() {
        println!(
            "wasm_matrix_compiles shard {shard}/{WASM_MATRIX_SHARDS} gate-cache: {cache_run} run, {cache_hit} cached"
        );
    }
    assert!(
        resurfaced.is_empty(),
        "these WASM_MATRIX_SKIP-listed wasm-matrix cells now compile — remove them from \
         WASM_MATRIX_SKIP (a fix landed):\n{}",
        resurfaced.join("\n")
    );
    assert!(
        failures.is_empty(),
        "wasm-matrix cells failed to compile:\n\n{}",
        failures.join("\n\n")
    );
}

/// The multifile-placement matrix compile-gate. `cddl-matrix/project_multifile_matrix.ts` enumerates
/// {type-shape} × {cross-module reference mode} into two-module DIRECTORY fixtures
/// `tests/matrix_multifile/<shape>__<mode>/` (`lib.cddl` = root scope, `a.cddl` = the shape's defs,
/// `b.cddl` = the reference). It's the *placement* counterpart to the construct gates, which all feed
/// the generator SINGLE-file specs and so only ever verify root-scope placement: multifile emission
/// branches on scope (`mark_refs`' hard-coded ROOT_SCOPE for the generator-invented structural
/// wrappers), and that region has no other coverage.
///
/// Each cell is generated with DIRECTORY input (`--input=tests/matrix_multifile/<cell>`) `--wasm=true`,
/// then only the WASM crate is `cargo check`ed — like `wasm_matrix_compiles`, the wasm crate pulls the
/// rust crate in as a path dep, so rust-side breakage (e.g. an alias/table-only module declaring
/// `pub mod serialization;` without emitting the file, or a cross-module structural/inner-type import
/// landing in the wrong scope) surfaces transitively through the wasm check; one crate keeps the
/// wall-clock bounded.
///
/// `MULTIFILE_MATRIX_SKIP` holds the deliberately-red cells — the `collrec__named`
/// array-structural-NAME cell plus the restricted-wrapper cells (the `mark_refs` Array-arm WRAPPER
/// placement class; see the const's doc). `collrec__anon`'s element-import class is fixed.
/// The three historical module-placement error classes (E0583 alias/table-only serialization stub,
/// E0432 anonymous same-shape table importing the structural name from root scope, E0433
/// cross-module named `.cbor` ref omitting the inner-type import) are all fixed. Four-state verdict per
/// cell: red+listed = expected —
/// but ADDITIONALLY the observed rustc error-code set (extracted from the captured cargo stderr) must
/// EQUAL the pin's declared codes; red-with-the-wrong-class is a loud "the cell's failure class
/// changed — re-triage the pin" (a skip cell whose GENERATION aborts, producing no rustc error at all,
/// is likewise a class mismatch); red+unlisted = a new placement finding to fix or (deliberately, with
/// a ledger entry) pin; green+listed = "resurfaced — remove the pin (a fix landed)"; green+unlisted =
/// pass. An up-front stale-key guard rejects a listed stem absent from the projected set, and a missing
/// wasm crate is handled symmetrically (a red for a non-skip cell, a resurface for a skip cell), so the
/// ledger can't silently rot. Always-on (no `#[ignore]`): it joins the default `cargo test` / check.ts
/// local tier.
///
/// **Sharded** into `multifile_matrix_compiles_shard_NN` — see [`FEATURE_CORPUS_SHARDS`] for the
/// shape and [`multifile_matrix_compiles_pins_are_live`] for the whole-matrix half. The shard names
/// all contain `multifile_matrix_compiles`, so every substring selector that named the old test —
/// including `audit_gate_cache_closure.ts`'s default `CLOSURE_AUDIT_GATE` — still selects the gate.
fn multifile_matrix_cell_dirs() -> Vec<std::path::PathBuf> {
    use std::str::FromStr;
    let dir = std::path::PathBuf::from_str("tests/matrix_multifile").unwrap();
    let mut cell_dirs: Vec<std::path::PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.is_dir())
        .collect();
    cell_dirs.sort();
    assert!(
        !cell_dirs.is_empty(),
        "no multifile-matrix fixtures in {dir:?} (run `bun run project_multifile_matrix.ts`)"
    );
    cell_dirs
}

/// The up-front stale-key guard of `multifile_matrix_compiles`, kept whole for the reason given on
/// [`feature_corpus_compiles_pins_are_live`]. The pin's rustc-error-code CLASS assertion is
/// decidable per cell and stays in the shards.
#[test]
fn multifile_matrix_compiles_pins_are_live() {
    let cell_dirs = multifile_matrix_cell_dirs();
    let cell_stems: std::collections::BTreeSet<&str> = cell_dirs
        .iter()
        .map(|p| p.file_name().unwrap().to_str().unwrap())
        .collect();
    for (stem, _codes, _reason) in MULTIFILE_MATRIX_SKIP {
        assert!(
            cell_stems.contains(stem),
            "MULTIFILE_MATRIX_SKIP names cell `{stem}` that no longer exists in tests/matrix_multifile \
             — stale pin, remove or fix it"
        );
    }
}

/// See [`FEATURE_CORPUS_SHARDS`] for why this is sized against measured scaling, not core count.
const MULTIFILE_MATRIX_SHARDS: usize = 6;
/// Occupancy counter for the shards' one shared scratch root (see [`SharedScratch`]).
static MULTIFILE_MATRIX_SCRATCH: std::sync::Mutex<usize> = std::sync::Mutex::new(0);

macro_rules! multifile_matrix_compiles_shards {
    ($($name:ident = $shard:expr;)+) => {
        $(
            #[test]
            fn $name() {
                multifile_matrix_compiles_shard($shard);
            }
        )+
    };
}

multifile_matrix_compiles_shards! {
    multifile_matrix_compiles_shard_00 = 0;
    multifile_matrix_compiles_shard_01 = 1;
    multifile_matrix_compiles_shard_02 = 2;
    multifile_matrix_compiles_shard_03 = 3;
    multifile_matrix_compiles_shard_04 = 4;
    multifile_matrix_compiles_shard_05 = 5;
}

/// One slice of the multifile-placement matrix. Each shard batches its own cells' failures and
/// asserts once, exactly as the unsharded loop did for the whole matrix.
fn multifile_matrix_compiles_shard(shard: usize) {
    let all_cell_dirs = multifile_matrix_cell_dirs();
    let cell_dirs: Vec<&std::path::PathBuf> = all_cell_dirs
        .iter()
        .enumerate()
        .filter(|(i, _)| i % MULTIFILE_MATRIX_SHARDS == shard)
        .map(|(_, p)| p)
        .collect();

    // Scratch dir + one shared target so cbor_event/wasm-bindgen build once, then each tiny crate
    // checks; shared across shards (see `SharedScratch` for the wipe contract).
    let scratch = SharedScratch::enter(
        &MULTIFILE_MATRIX_SCRATCH,
        std::env::temp_dir().join(format!(
            "cddl_codegen_multifile_matrix_{:016x}",
            checkout_hash()
        )),
    );
    let root = scratch.root().to_path_buf();
    let target_dir = root.join("target");

    let mut failures = vec![]; // red cells NOT on MULTIFILE_MATRIX_SKIP — real bugs
    let mut resurfaced = vec![]; // MULTIFILE_MATRIX_SKIP cells that now compile — remove them
    let mut cache_run = 0usize;
    let mut cache_hit = 0usize;
    for input in cell_dirs {
        let stem = input.file_name().unwrap().to_str().unwrap();
        let pin = MULTIFILE_MATRIX_SKIP.iter().find(|(s, _, _)| *s == stem);
        let skipped = pin.is_some();
        let out = root.join(stem);
        let gen_out = codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=true")
            .output()
            .unwrap();
        if !gen_out.status.success() {
            match pin {
                // The pin claims a rustc COMPILE-error class, but generation aborted — there is no
                // rustc error code at all, so the cell's failure class changed.
                Some((_, codes, reason)) => failures.push(format!(
                    "{stem}: generation aborted, but MULTIFILE_MATRIX_SKIP pins a rustc compile-error \
                     class {codes:?} ({reason}) — a generation abort produces no rustc error code, so \
                     the cell's failure class changed — re-triage the pin and its \
                     cddl-matrix/ROADMAP.md finding\n{}",
                    String::from_utf8_lossy(&gen_out.stderr)
                )),
                // A NON-skipped generation failure is a plain red.
                None => failures.push(format!(
                    "{stem}: generation failed\n{}",
                    String::from_utf8_lossy(&gen_out.stderr)
                )),
            }
            continue;
        }
        let wasm_dir = out.join("wasm");
        if !wasm_dir.exists() {
            // Every cell's module `b` is a composite record, so a wasm crate is always expected. Treat a
            // missing one symmetrically (like `wasm_matrix_compiles`): a skip cell's red is gone
            // ("resurfaced"); a non-skip cell silently stops being gated — a coverage regression, not a pass.
            if skipped {
                resurfaced.push(format!("{stem} (emits no wasm crate)"));
            } else {
                failures.push(format!(
                    "{stem}: generated no wasm crate (expected a wasm wrapper for every cell — the cell \
                     is no longer being compile-gated)"
                ));
            }
            continue;
        }
        let argv_for_key = vec![
            "cwd=wasm".to_string(),
            "cargo".to_string(),
            "check".to_string(),
        ];
        let manifest_subpaths = vec![std::path::PathBuf::from("wasm/Cargo.toml")];
        let mut check_output = None;
        let outcome = gate_cache::run_cached(
            "multifile_matrix_compiles",
            stem,
            &out,
            &manifest_subpaths,
            &argv_for_key,
            || {
                let check = tool_cmd("cargo")
                    .arg("check")
                    .current_dir(&wasm_dir)
                    .env("CARGO_TARGET_DIR", &target_dir)
                    .output()
                    .unwrap();
                let success = check.status.success();
                check_output = Some(check);
                success
            },
        );
        cache_run += outcome.ran();
        cache_hit += outcome.cached();
        match (skipped, outcome.success()) {
            (false, false) => failures.push(format!(
                "{stem}: cargo check failed (new multifile-placement red cell — fix the emitter or, \
                 deliberately, add to MULTIFILE_MATRIX_SKIP + cddl-matrix/ROADMAP.md)\n{}",
                String::from_utf8_lossy(&check_output.unwrap().stderr)
            )),
            (true, true) => resurfaced.push(stem.to_string()),
            (true, false) => {
                // Red as expected — but the observed rustc error-code SET must EQUAL the pin's, or
                // the cell's failure CLASS changed and the pin must be re-triaged (class assertion).
                let (_, pinned_codes, reason) = pin.unwrap();
                let output = check_output.unwrap();
                let stderr = String::from_utf8_lossy(&output.stderr);
                let observed = rustc_error_codes(&stderr);
                let expected: std::collections::BTreeSet<String> =
                    pinned_codes.iter().map(|c| c.to_string()).collect();
                if observed != expected {
                    failures.push(format!(
                        "{stem}: red as pinned, but the observed rustc error-code set {observed:?} \
                         does NOT equal the pinned set {expected:?} ({reason}) — the cell's failure \
                         class changed — re-triage the pin and its cddl-matrix/ROADMAP.md finding. \
                         Captured stderr:\n{stderr}"
                    ));
                }
            }
            (false, true) => {} // green as expected
        }
    }
    if gate_cache::enabled() {
        println!(
            "multifile_matrix_compiles shard {shard}/{MULTIFILE_MATRIX_SHARDS} gate-cache: {cache_run} run, {cache_hit} cached"
        );
    }
    assert!(
        resurfaced.is_empty(),
        "these MULTIFILE_MATRIX_SKIP-listed cells now compile — remove them from MULTIFILE_MATRIX_SKIP \
         (a fix landed):\n{}",
        resurfaced.join("\n")
    );
    assert!(
        failures.is_empty(),
        "multifile-matrix cells failed to compile:\n\n{}",
        failures.join("\n\n")
    );
}

/// Always-on pin for the multifile `--emit-tests` scope-import emission. For DIRECTORY input the
/// generated test modules land at the generated ROOT of each crate (`generation/mod.rs` raws them into
/// `rust_lib()`/`wasm_lib()`) while the minted values name submodule types bare (`St`, `Bholder`),
/// so each emitted header must glob-import every declared non-root module (`use super::a::*;`) —
/// without them EVERY multifile `--emit-tests` crate fails `cargo test` with E0433 ("cannot find
/// type `St` in this scope"): malformed emission of a shipped feature. In-process
/// (`api::generated_strings`, no nested cargo build) so it stays cheap enough for the default
/// suite; actually EXECUTING these modules across the matrix is `multifile_matrix_roundtrips`'
/// job (full tier). The single-file half pins the byte-identity guard: no non-root scopes → no
/// glob lines and no injected `#[allow(unused_imports)]`, so single-file output is unchanged.
#[test]
fn emit_tests_multifile_scope_imports() {
    use clap::Parser;

    let get = |files: &std::collections::BTreeMap<String, String>, key: &str| -> String {
        files
            .get(key)
            .unwrap_or_else(|| {
                panic!(
                    "no `{key}` among generated files; got: {:?}",
                    files.keys().collect::<Vec<_>>()
                )
            })
            .clone()
    };

    // Multifile: one placement-matrix cell — module `a` holds the shape (`st`), module `b` the
    // cross-module reference (`bholder = [field0: st]`).
    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input=tests/matrix_multifile/struct__named",
        "--output=unused_in_memory_generation",
        "--wasm=true",
        "--emit-tests=true",
    ]);
    let files = crate::api::generated_strings(&cli).unwrap();
    for (which, key, header) in [
        (
            "rust",
            "rust/src/generated/mod.rs",
            "mod cddl_generated_tests",
        ),
        (
            "wasm",
            "wasm/src/generated/mod.rs",
            "mod cddl_generated_wasm_tests",
        ),
    ] {
        let module = get(&files, key);
        assert!(
            module.contains(header),
            "{which}: expected `{header}` in {key} (did --emit-tests stop minting for this cell?)\n{module}"
        );
        for glob in ["use super::a::*;", "use super::b::*;"] {
            assert!(
                module.contains(glob),
                "{which}: the root-level test module names submodule types bare, so {key} must \
                 carry `{glob}` — without it the module is E0433-uncompilable (malformed \
                 emission)\n{module}"
            );
        }
    }

    // Single-file: the same shapes at root scope must stay glob-free — the emitters' non-empty
    // guard keeps single-file `--emit-tests` output byte-identical.
    let spec_path = std::env::temp_dir().join(format!(
        "cddl_codegen_emit_tests_scope_imports_{:016x}.cddl",
        checkout_hash()
    ));
    std::fs::write(
        &spec_path,
        "st = [a: uint, b: text]\nbholder = [field0: st]\n",
    )
    .unwrap();
    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        &format!("--input={}", spec_path.to_str().unwrap()),
        "--output=unused_in_memory_generation",
        "--wasm=true",
        "--emit-tests=true",
    ]);
    let files = crate::api::generated_strings(&cli).unwrap();
    let _ = std::fs::remove_file(&spec_path);
    for (which, key, header) in [
        (
            "rust",
            "rust/src/generated/mod.rs",
            "mod cddl_generated_tests",
        ),
        (
            "wasm",
            "wasm/src/generated/mod.rs",
            "mod cddl_generated_wasm_tests",
        ),
    ] {
        let module = get(&files, key);
        assert!(
            module.contains(header),
            "{which}: expected `{header}` in single-file {key}\n{module}"
        );
        assert!(
            !module.contains("use super::a::*;") && !module.contains("use super::b::*;"),
            "{which}: single-file output (all types at root scope) must not grow scope glob \
             imports — the non-empty guard regressed\n{module}"
        );
    }
    let rust_mod = get(&files, "rust/src/generated/mod.rs");
    assert!(
        !rust_mod.contains("#[allow(unused_imports)]\nmod cddl_generated_tests"),
        "rust: single-file output must not grow the glob-only `#[allow(unused_imports)]` — the \
         non-empty guard regressed\n{rust_mod}"
    );
}

/// The wasm-ABI matrix ROUND-TRIP gate — the behavioural upgrade of `wasm_matrix_compiles`. Same cell
/// enumeration (`tests/matrix_wasm/*.cddl`), but each cell is generated with `--wasm=true
/// --emit-tests=true` and `cargo test`ed (not `cargo check`ed): this compiles AND RUNS the emitted
/// `cddl_generated_wasm_tests` module (cross-crate byte differential + wire round-trip + accessor
/// read-back + boundary acceptance — see `src/emit_tests_wasm.rs`). A cell can `cargo check` green
/// (compile gate) while the wrapper API does a semantically wrong same-type conversion; that only
/// surfaces when the emitted assertions RUN, which is what this gate adds.
///
/// Each cell is swept across `super::ALL_PROFILES` (default / preserve / json) — `--preserve-encodings`
/// and the json flags substantially change codegen, so the wasm behavioural verdict must hold under
/// each. This is strictly the WASM round-trip verdict per profile; rust-side non-default round-trip
/// breadth stays `feature_corpus_roundtrips_nondefault_profiles`' job (this gate only `cargo test`s
/// the wasm crate, exactly as the default-only version did). Each `(profile, cell)` output lives in
/// `{stem}__{profile}` under one shared `CARGO_TARGET_DIR`, and its crate dir is freed after its
/// verdict (the disk-space pattern from `feature_corpus_roundtrips_nondefault_profiles`).
///
/// MANUAL/LOCAL ONLY — `#[ignore]`d so it stays out of CI under the feature freeze (`cargo test`
/// per cell across three profiles is materially heavier than the compile gate's per-cell `cargo
/// check`). Run it with `cargo test --bin cddl-codegen wasm_matrix_roundtrips -- --ignored`.
///
/// Two skip lists, both four-state (verdict matrix as `wasm_matrix_compiles`, labels `{stem}/{profile}`):
/// `WASM_MATRIX_SKIP` holds cells red in EVERY profile (extern); `WASM_MATRIX_PROFILE_SKIP` (this gate
/// only) holds `(profile, cell, reason)` cells red under a SPECIFIC profile. A red non-skip cell fails
/// (real finding, or deliberately skip-list it with a ledger reason); a skip cell that now passes fails
/// the resurfaced guard (a fix landed — take it off the list). An up-front stale-pin guard rejects a
/// `WASM_MATRIX_PROFILE_SKIP` entry naming a dead profile or cell stem. `wasm_matrix_compiles` stays
/// byte-for-byte untouched: it remains the always-on default-profile CI compile floor (non-default
/// compile coverage is subsumed by this gate's `cargo test` at full tier, per cost policy); this is
/// the manual per-profile round-trip verdict on top. Its own scratch dir name lets it run beside the
/// compile gate. Note: a cell whose shape mints no wasm test surface (nothing the emitter can
/// faithfully build — e.g. a pure c-enum, or a wrapper/collection ctor arg with no wasm build) simply
/// emits no module and `cargo test` passes with zero emitted tests; that is a legitimate green here
/// (the emitter skips loudly), NOT a false pass — the compile gate already pins that the cell's wasm
/// ABI compiles.
#[test]
#[ignore]
fn wasm_matrix_roundtrips() {
    use std::str::FromStr;

    // The wrapper-collection struct-field cells (`coll__struct-field` `nums = [* uint]`,
    // `collmap__struct-field`,
    // `passthrumap__struct-field`) round-trip green: the emitter builds their `&Nums`/`&Mp` ctor arg
    // through the wrapper's `new`/`add`/`insert` API, taking the wrapper NAME from the UNRESOLVED
    // conceptual type (`emit_tests_wasm::wasm_collection_build`) so it doesn't shallow-resolve the
    // alias into a bare `vec![..]` against the `&Nums` param — so they are NOT
    // `WASM_MATRIX_SKIP`-listed.

    let dir = std::path::PathBuf::from_str("tests/matrix_wasm").unwrap();
    let mut entries: Vec<std::path::PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().and_then(|e| e.to_str()) == Some("cddl"))
        .collect();
    entries.sort();
    assert!(
        !entries.is_empty(),
        "no wasm-matrix fixtures in {dir:?} (run `bun run project_wasm_matrix.ts`)"
    );

    // Reject `WASM_MATRIX_PROFILE_SKIP` entries naming a dead profile or cell stem up front — a
    // stale pin would rot silently (its resurfaced guard only fires on a (profile, cell) the sweep
    // actually visits). Mirrors the `EXPECTED_GENERATION_FAIL` stale-pin guard in wasm_parity_tests.
    let cell_stems: std::collections::BTreeSet<&str> = entries
        .iter()
        .map(|p| p.file_stem().unwrap().to_str().unwrap())
        .collect();
    for stem in WASM_MATRIX_SKIP {
        assert!(
            cell_stems.contains(stem),
            "WASM_MATRIX_SKIP names cell `{stem}` that no longer exists in tests/matrix_wasm — \
             stale pin, remove or fix it"
        );
    }
    // The component profile is filtered out BY NAME: this gate's subject is the wasm ABI's
    // round-trip behaviour, and `--component` adds no wasm surface at all (it mints a separate
    // wasip2 crate and changes no rust or wasm byte). Pins are reconciled against the SWEPT
    // profiles, not against `ALL_PROFILES`, so a pin naming the filtered row fails as stale rather
    // than sitting vacuous.
    let profiles: Vec<super::Profile> = super::ALL_PROFILES
        .iter()
        .filter(|(profile, _)| *profile != super::COMPONENT_PROFILE)
        .copied()
        .collect();
    for (profile, stem, _) in WASM_MATRIX_PROFILE_SKIP {
        assert!(
            profiles.iter().any(|(name, _)| name == profile),
            "WASM_MATRIX_PROFILE_SKIP names profile `{profile}`, which this gate does not sweep — \
             stale pin, remove or fix it"
        );
        assert!(
            cell_stems.contains(stem),
            "WASM_MATRIX_PROFILE_SKIP names cell `{stem}` that no longer exists in tests/matrix_wasm \
             — stale pin, remove or fix it"
        );
    }

    // Own scratch dir (distinct from wasm_matrix_compiles) + one shared target so cbor_event/
    // wasm-bindgen/the libtest harness build once, then each tiny crate tests incrementally. The
    // shared target survives across all profiles/cells; each per-cell output dir is freed after its
    // verdict (disk-space pattern from feature_corpus_roundtrips_nondefault_profiles).
    let scratch_name = format!("cddl_codegen_wasm_matrix_rt_{:016x}", checkout_hash());
    let _scratch_lock = acquire_scratch_lock(&scratch_name); // serialize same-checkout runs
    let root = std::env::temp_dir().join(&scratch_name);
    let _ = std::fs::remove_dir_all(&root);
    let target_dir = root.join("target");

    let mut failures = vec![]; // red cells NOT skip-listed — real findings
    let mut resurfaced = vec![]; // skip-listed cells that now pass — remove them
    let mut cache_run = 0usize;
    let mut cache_hit = 0usize;
    for input in &entries {
        let stem = input.file_stem().unwrap().to_str().unwrap();
        // Skipped in EVERY profile (extern).
        let skipped_all = WASM_MATRIX_SKIP.contains(&stem);
        for (profile, extra) in &profiles {
            let label = format!("{stem}/{profile}");
            // Skipped in EVERY profile, or in THIS specific profile.
            let skipped = skipped_all
                || WASM_MATRIX_PROFILE_SKIP
                    .iter()
                    .any(|(p, s, _)| p == profile && s == &stem);
            let out = root.join(format!("{stem}__{profile}"));
            let gen_out = codegen_cmd()
                .arg(format!("--input={}", input.to_str().unwrap()))
                .arg(format!("--output={}", out.to_str().unwrap()))
                .arg("--wasm=true")
                .arg("--emit-tests=true")
                .args(*extra)
                .output()
                .unwrap();
            if !gen_out.status.success() {
                if !skipped {
                    failures.push(format!(
                        "{label}: generation failed\n{}",
                        String::from_utf8_lossy(&gen_out.stderr)
                    ));
                }
                let _ = std::fs::remove_dir_all(&out);
                continue;
            }
            let wasm_dir = out.join("wasm");
            if !wasm_dir.exists() {
                // Every cell wraps its shape in a composite `holder`, so a wasm crate is always expected.
                if skipped {
                    resurfaced.push(format!("{label} (emits no wasm crate)"));
                } else {
                    failures.push(format!(
                        "{label}: generated no wasm crate (expected a wasm wrapper for every cell — the \
                         cell is no longer being round-trip-gated)"
                    ));
                }
                let _ = std::fs::remove_dir_all(&out);
                continue;
            }
            // See wasm_matrix_compiles: append the in-repo raw-bytes defs so `rawbytes__*` cells
            // compile/run under every profile. The wire defs are profile-agnostic (pinned by
            // raw_bytes_preserve); json selects the flavor carrying the serde/schemars derives the
            // json flags impose on user-supplied types.
            if stem.starts_with("rawbytes__") {
                append_raw_bytes_defs(&out, *profile == "json");
            }
            let argv_for_key = vec![
                "cwd=wasm".to_string(),
                "cargo".to_string(),
                "test".to_string(),
            ];
            let manifest_subpaths = vec![std::path::PathBuf::from("wasm/Cargo.toml")];
            let mut test_output = None;
            let outcome = gate_cache::run_cached(
                "wasm_matrix_roundtrips",
                &label,
                &out,
                &manifest_subpaths,
                &argv_for_key,
                || {
                    let test = tool_cmd("cargo")
                        .arg("test")
                        .current_dir(&wasm_dir)
                        .env("CARGO_TARGET_DIR", &target_dir)
                        .output()
                        .unwrap();
                    let success = test.status.success();
                    test_output = Some(test);
                    success
                },
            );
            cache_run += outcome.ran();
            cache_hit += outcome.cached();
            match (skipped, outcome.success()) {
                (false, false) => {
                    let test = test_output.unwrap();
                    failures.push(format!(
                        "{label}: cargo test failed (wasm round-trip red cell — fix the emitter/generator \
                         or, deliberately, add to WASM_MATRIX_PROFILE_SKIP + a ledger reason)\nstdout:\n{}\nstderr:\n{}",
                        String::from_utf8_lossy(&test.stdout),
                        String::from_utf8_lossy(&test.stderr)
                    ));
                }
                (true, true) => resurfaced.push(label),
                _ => {} // (false,true)=green as expected; (true,false)=red as expected
            }
            // Free the per-cell crate dir as we go (keep the shared target) — near disk-full, and
            // 98 cells × 3 profiles of generated crates add up.
            let _ = std::fs::remove_dir_all(&out);
        }
    }
    if gate_cache::enabled() {
        println!("wasm_matrix_roundtrips gate-cache: {cache_run} run, {cache_hit} cached");
    }
    let _ = std::fs::remove_dir_all(&root);
    assert!(
        resurfaced.is_empty(),
        "these skip-listed wasm-matrix cells now round-trip — remove them from WASM_MATRIX_SKIP / \
         WASM_MATRIX_PROFILE_SKIP (a fix landed):\n{}",
        resurfaced.join("\n")
    );
    assert!(
        failures.is_empty(),
        "wasm-matrix cells failed to round-trip:\n\n{}",
        failures.join("\n\n")
    );
}

/// The multifile-placement matrix ROUND-TRIP gate — the behavioural upgrade of
/// `multifile_matrix_compiles`, mirroring `wasm_matrix_roundtrips`. Same cell enumeration (the 46
/// `tests/matrix_multifile/<shape>__<mode>/` directories), but each cell is generated with
/// `--wasm=true --emit-tests=true` across `super::ALL_PROFILES` (default / preserve / json) and
/// `cargo test`ed rather than `cargo check`ed — this compiles AND RUNS the emitted
/// `cddl_generated_tests` / `cddl_generated_wasm_tests` modules, whose minted values construct the
/// CROSS-MODULE wiring (module `b`'s holder built from module `a`'s shape, e.g.
/// `Bholder::new(St::new(..))`; the wasm twin also byte-differentials against the fully-qualified
/// `cddl_lib::b::Bholder`/`cddl_lib::a::St` natives). A placement cell can type-check green under
/// the compile floor while cross-module (de)serialization misbehaves; that only surfaces when the
/// emitted assertions RUN, which is what this gate adds.
///
/// BOTH generated subcrates are `cargo test`ed, `rust/` then `wasm/`: the rust crate's
/// `#[cfg(test)]` module is NOT compiled when the crate is built merely as a dep of the wasm
/// crate, and the proven placement classes are rust-side (`feature_corpus_compiles` is the
/// both-crates precedent). A cell is red if EITHER crate's `cargo test` fails.
///
/// MANUAL/LOCAL ONLY — `#[ignore]`d (check.ts `full` tier) under the CI cost policy: 46 cells × 3
/// profiles × 2 `cargo test`s is materially heavier than the always-on compile floor. Run it with
/// `cargo test --bin cddl-codegen multifile_matrix_roundtrips -- --ignored`.
///
/// Two skip ledgers, both four-state (red+listed = expected; red+unlisted = fail — fix or,
/// deliberately, pin + cddl-matrix/ROADMAP.md ledger reason; green+listed = "resurfaced — remove
/// the pin"; green+unlisted = pass) with up-front stale-key guards: `MULTIFILE_ROUNDTRIP_SKIP`
/// (red in EVERY profile — the collrec compile-floor carries) and
/// `MULTIFILE_ROUNDTRIP_PROFILE_SKIP` (profile-specific reds). No rustc-error-code class assertion
/// here — the compile floor's `MULTIFILE_MATRIX_SKIP` pins each collrec cell's exact class.
///
/// Vacuity floor: the sweep counts each generated crate whose root `generated/mod.rs` carries a
/// minted test module (the `feature_corpus_compiles` counting pattern) and asserts a floor, so
/// "all green" can't silently mean "nothing was minted". Loud-skip contract (as
/// `wasm_matrix_roundtrips`): a cell shape minting no test surface emits no module and passes
/// with zero tests — legitimate (the emitter eprintln!s the skip; the compile floor still pins the
/// cell's ABI), and the floor bounds how much of that the sweep tolerates in aggregate.
/// `multifile_matrix_compiles` stays byte-for-byte untouched as the always-on compile floor; its
/// own scratch dir name (+ `acquire_scratch_lock`) lets this gate run beside it, and each per-cell
/// output dir is freed after its verdict (the disk-space pattern from
/// `feature_corpus_roundtrips_nondefault_profiles`).
#[test]
#[ignore]
fn multifile_matrix_roundtrips() {
    use std::str::FromStr;

    let dir = std::path::PathBuf::from_str("tests/matrix_multifile").unwrap();
    let mut cell_dirs: Vec<std::path::PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.is_dir())
        .collect();
    cell_dirs.sort();
    assert!(
        !cell_dirs.is_empty(),
        "no multifile-matrix fixtures in {dir:?} (run `bun run project_multifile_matrix.ts`)"
    );

    // Up-front stale-key guards (mirror wasm_matrix_roundtrips): a listed stem/profile that no
    // longer exists would otherwise rot silently (its resurfaced guard only fires on a
    // (profile, cell) the sweep actually visits).
    let cell_stems: std::collections::BTreeSet<&str> = cell_dirs
        .iter()
        .map(|p| p.file_name().unwrap().to_str().unwrap())
        .collect();
    for (stem, _reason) in MULTIFILE_ROUNDTRIP_SKIP {
        assert!(
            cell_stems.contains(stem),
            "MULTIFILE_ROUNDTRIP_SKIP names cell `{stem}` that no longer exists in \
             tests/matrix_multifile — stale pin, remove or fix it"
        );
    }
    // The component profile is filtered out BY NAME, for the same reason as its `wasm_matrix`
    // sibling: this gate's subject is the wasm ABI's round-trip behaviour and `--component` adds no
    // wasm surface. Pins reconcile against the SWEPT profiles so a pin naming the filtered row
    // fails as stale rather than sitting vacuous. The `>= 136 of 144` vacuity floor below is
    // calibrated on the three swept profiles and is deliberately left alone.
    let profiles: Vec<super::Profile> = super::ALL_PROFILES
        .iter()
        .filter(|(profile, _)| *profile != super::COMPONENT_PROFILE)
        .copied()
        .collect();
    for (profile, stem, _reason) in MULTIFILE_ROUNDTRIP_PROFILE_SKIP {
        assert!(
            profiles.iter().any(|(name, _)| name == profile),
            "MULTIFILE_ROUNDTRIP_PROFILE_SKIP names profile `{profile}`, which this gate does not \
             sweep — stale pin, remove or fix it"
        );
        assert!(
            cell_stems.contains(stem),
            "MULTIFILE_ROUNDTRIP_PROFILE_SKIP names cell `{stem}` that no longer exists in \
             tests/matrix_multifile — stale pin, remove or fix it"
        );
    }

    // Own scratch dir (distinct from multifile_matrix_compiles) + one shared target so
    // cbor_event/wasm-bindgen/the libtest harness build once, then each tiny crate tests
    // incrementally.
    let scratch_name = format!("cddl_codegen_multifile_rt_{:016x}", checkout_hash());
    let _scratch_lock = acquire_scratch_lock(&scratch_name); // serialize same-checkout runs
    let root = std::env::temp_dir().join(&scratch_name);
    let _ = std::fs::remove_dir_all(&root);
    let target_dir = root.join("target");

    let mut failures = vec![]; // red cells NOT skip-listed — real findings
    let mut resurfaced = vec![]; // skip-listed cells that now pass — remove them
    let mut cache_run = 0usize;
    let mut cache_hit = 0usize;
    // Vacuity-floor counters: (profile, cell) generations whose crate minted a test module.
    // Counted before the verdict (skip cells still mint), so the floor tracks EMITTER coverage,
    // not the pass rate.
    let mut minted_rust_modules = 0usize;
    let mut minted_wasm_modules = 0usize;
    for input in &cell_dirs {
        let stem = input.file_name().unwrap().to_str().unwrap();
        // Skipped in EVERY profile.
        let skipped_all = MULTIFILE_ROUNDTRIP_SKIP.iter().any(|(s, _)| *s == stem);
        for (profile, extra) in &profiles {
            let label = format!("{stem}/{profile}");
            // Skipped in EVERY profile, or in THIS specific profile.
            let skipped = skipped_all
                || MULTIFILE_ROUNDTRIP_PROFILE_SKIP
                    .iter()
                    .any(|(p, s, _)| p == profile && s == &stem);
            let out = root.join(format!("{stem}__{profile}"));
            let gen_out = codegen_cmd()
                .arg(format!("--input={}", input.to_str().unwrap()))
                .arg(format!("--output={}", out.to_str().unwrap()))
                .arg("--wasm=true")
                .arg("--emit-tests=true")
                .args(*extra)
                .output()
                .unwrap();
            if !gen_out.status.success() {
                if !skipped {
                    failures.push(format!(
                        "{label}: generation failed\n{}",
                        String::from_utf8_lossy(&gen_out.stderr)
                    ));
                }
                let _ = std::fs::remove_dir_all(&out);
                continue;
            }
            if std::fs::read_to_string(out.join("rust/src/generated/mod.rs"))
                .unwrap_or_default()
                .contains("mod cddl_generated_tests")
            {
                minted_rust_modules += 1;
            }
            if std::fs::read_to_string(out.join("wasm/src/generated/mod.rs"))
                .unwrap_or_default()
                .contains("mod cddl_generated_wasm_tests")
            {
                minted_wasm_modules += 1;
            }
            let wasm_dir = out.join("wasm");
            if !wasm_dir.exists() {
                // Every cell's module `b` is a composite record, so a wasm crate is always
                // expected — a missing one silently de-gates the cell (mirror the compile floor).
                if skipped {
                    resurfaced.push(format!("{label} (emits no wasm crate)"));
                } else {
                    failures.push(format!(
                        "{label}: generated no wasm crate (expected a wasm wrapper for every cell \
                         — the cell is no longer being round-trip-gated)"
                    ));
                }
                let _ = std::fs::remove_dir_all(&out);
                continue;
            }
            // Execute BOTH generated subcrates, rust then wasm (see the gate doc); first failure
            // is the cell's red.
            let mut cell_red: Option<(&str, std::process::Output)> = None;
            let manifest_subpaths = vec![
                std::path::PathBuf::from("rust/Cargo.toml"),
                std::path::PathBuf::from("wasm/Cargo.toml"),
            ];
            let argv_for_key = vec![
                "cwd=rust".to_string(),
                "cargo".to_string(),
                "test".to_string(),
                "cwd=wasm".to_string(),
                "cargo".to_string(),
                "test".to_string(),
            ];
            let outcome = gate_cache::run_cached(
                "multifile_matrix_roundtrips",
                &label,
                &out,
                &manifest_subpaths,
                &argv_for_key,
                || {
                    for crate_sub in ["rust", "wasm"] {
                        let test = tool_cmd("cargo")
                            .arg("test")
                            .current_dir(out.join(crate_sub))
                            .env("CARGO_TARGET_DIR", &target_dir)
                            .output()
                            .unwrap();
                        if !test.status.success() {
                            cell_red = Some((crate_sub, test));
                            return false;
                        }
                    }
                    true
                },
            );
            cache_run += outcome.ran();
            cache_hit += outcome.cached();
            match (skipped, cell_red) {
                (false, Some((crate_sub, test))) => failures.push(format!(
                    "{label} ({crate_sub}): cargo test failed (multifile round-trip red cell — \
                     fix the emitter/generator or, deliberately, add to MULTIFILE_ROUNDTRIP_SKIP \
                     / MULTIFILE_ROUNDTRIP_PROFILE_SKIP + a cddl-matrix/ROADMAP.md ledger \
                     reason)\nstdout:\n{}\nstderr:\n{}",
                    String::from_utf8_lossy(&test.stdout),
                    String::from_utf8_lossy(&test.stderr)
                )),
                (true, None) if outcome.success() => resurfaced.push(label),
                _ => {} // (false, None) = green as expected; (true, Some(_)) = red as expected
            }
            // Free the per-cell crate dir as we go (keep the shared target) — 46 cells × 3
            // profiles of generated crates add up.
            let _ = std::fs::remove_dir_all(&out);
        }
    }
    let _ = std::fs::remove_dir_all(&root);
    if gate_cache::enabled() {
        println!("multifile_matrix_roundtrips gate-cache: {cache_run} run, {cache_hit} cached");
    }
    eprintln!(
        "multifile_matrix_roundtrips: minted test modules across the sweep — rust {minted_rust_modules}, wasm {minted_wasm_modules}"
    );
    // Vacuity floor, calibrated from the observed green runs: all 144 (48 cells × 3 profiles)
    // generations minted BOTH modules (every cell's module `b` holder is a mintable composite
    // record). A big drop means the emitter's multifile coverage silently shrank, not that the
    // matrix got simpler.
    assert!(
        minted_rust_modules >= 136 && minted_wasm_modules >= 136,
        "only {minted_rust_modules} rust / {minted_wasm_modules} wasm (profile, cell) generations \
         minted a generated-test module (expected >= 136 each of 144) — emit_tests multifile \
         coverage shrank; the sweep's green is going vacuous"
    );
    assert!(
        resurfaced.is_empty(),
        "these skip-listed multifile-matrix cells now round-trip — remove them from \
         MULTIFILE_ROUNDTRIP_SKIP / MULTIFILE_ROUNDTRIP_PROFILE_SKIP (a fix landed):\n{}",
        resurfaced.join("\n")
    );
    assert!(
        failures.is_empty(),
        "multifile-matrix cells failed to round-trip:\n\n{}",
        failures.join("\n\n")
    );
}

/// Compile gate for `--wasm-list-macro` / `--wasm-conversions-macro`. The emitted code references
/// a user-supplied macro (`impl_wasm_list!` invocations replace each list wrapper's inline
/// struct/accessor/conversion block), so it can't compile standalone and was previously
/// snapshot-only — a malformed invocation emission (wrong arg order, wrong `needs_into`/`is_copy`
/// values, an unreachable combination) is a semantic fact a source snapshot can't judge. This
/// wires in `tests/wasm-macro-crate` — real macro definitions matching the emitted signature,
/// written so each of those wrong-emission classes fails to compile (see its README) — the same
/// way extern-deps wires `tests/extern-dep-crate`, and `cargo check`s the generated wasm crate
/// under both flag combinations the snapshot suite pins (`snapshot_tests::wasm_list_macro`).
#[test]
fn wasm_list_macro_compiles() {
    use std::str::FromStr;
    let cases: &[(&str, &[&str])] = &[
        (
            "list_macro",
            &["--wasm-list-macro=wasm_macro_crate::impl_wasm_list"][..],
        ),
        // combined: list wrappers use impl_wasm_list! (which emits its own conversions) while
        // non-list wrappers use impl_wasm_conversions! — compile-proves the two don't double-emit.
        (
            "list_and_conversions_macro",
            &[
                "--wasm-list-macro=wasm_macro_crate::impl_wasm_list",
                "--wasm-conversions-macro=wasm_macro_crate::impl_wasm_conversions",
            ][..],
        ),
    ];
    let test_path = std::path::PathBuf::from_str("tests/wasm-list-macro").unwrap();
    // own scratch target (shared across the two cases) so parallel tests don't collide
    let target_dir = std::env::temp_dir().join(format!(
        "cddl_codegen_wasm_list_macro_{:016x}",
        checkout_hash()
    ));
    for (label, options) in cases {
        let out = test_path.join(format!("export_{label}"));
        let _ = std::fs::remove_dir_all(&out);
        let gen_out = codegen_cmd()
            .arg(format!(
                "--input={}",
                test_path.join("input.cddl").to_str().unwrap()
            ))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=true")
            .args(*options)
            .output()
            .unwrap();
        assert!(
            gen_out.status.success(),
            "{label}: generation failed\n{}",
            String::from_utf8_lossy(&gen_out.stderr)
        );
        // vacuous-pass guard: the gate only gates the macro path if the flag actually collapsed
        // the list wrappers into invocations (5 at landing; see the fixture's header comment).
        let lib = std::fs::read_to_string(out.join("wasm/src/generated/mod.rs")).unwrap();
        let n_invocations = lib.matches("impl_wasm_list!(").count();
        assert!(
            n_invocations >= 5,
            "{label}: only {n_invocations} impl_wasm_list! invocations emitted (expected >= 5) — \
             the flag stopped collapsing list wrappers, so this gate no longer gates the macro path"
        );
        // symmetric vacuous-pass guard for the conversions half: the combined case's docstring claims
        // BOTH flag combinations are compile-gated, but only the list count was asserted — a
        // regression of --wasm-conversions-macro back to inline From/AsRef would still compile green.
        // The fixture emits 2 conversions invocations (list=5, conv=2).
        if options
            .iter()
            .any(|o| o.contains("--wasm-conversions-macro="))
        {
            let n_conv = lib.matches("impl_wasm_conversions!(").count();
            assert!(
                n_conv >= 2,
                "{label}: only {n_conv} impl_wasm_conversions! invocations emitted (expected >= 2) — \
                 the flag stopped collapsing non-list wrappers, so the conversions-macro path is ungated"
            );
        }
        // wire in the real macro definitions the emitted invocations reference
        let mut cargo_toml = std::fs::OpenOptions::new()
            .append(true)
            .open(out.join("wasm/Cargo.toml"))
            .unwrap();
        cargo_toml
            .write_all(b"wasm-macro-crate = { path = \"../../../wasm-macro-crate\" }\n")
            .unwrap();
        std::mem::drop(cargo_toml);
        let check = tool_cmd("cargo")
            .arg("check")
            .current_dir(out.join("wasm"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .output()
            .unwrap();
        assert!(
            check.status.success(),
            "{label}: cargo check failed\n{}",
            String::from_utf8_lossy(&check.stderr)
        );
    }
}

/// Smoke gate for documented flag *values* that no other test or profile exercises (closed the
/// once-open "five documented flag values with zero coverage" gap for the rust-side four). Each selects a whole alternative emit path: `--annotate-fields=false` (a
/// different deserialization / error-emission mode — 13+ branch sites in `generation/`),
/// `--to-from-bytes-methods=false` (drops the `to_bytes`/`from_bytes` API), and
/// `--binary-wrappers=true` (byte strings as new rust types). Before this, a generation regression
/// under any of them compiled nothing anywhere. Cheapest acceptance per the roadmap: generate a
/// rich, extern-free, custom-serialize-free input (tests/canonical — so no default-flag-assuming
/// appends are needed) under each value and `cargo check` the rust crate. Rust-side only
/// (`--wasm=false`).
///
/// The fifth documented value — `--canonical-form=true` *without* `--preserve-encodings` — turned
/// out to emit a crate that doesn't compile (the canonical toggle rides on preserve's serialize
/// signatures, leaving an unbound `force_canonical`). Per the roadmap's own resolution ("a CLI
/// rejection or a ledgered gap"), that combination is now rejected up front (`api::with_types`);
/// `flag_value_rejects_canonical_without_preserve` pins the rejection. The remaining fifth value,
/// `--wasm-cbor-json-api-macro`, is a wasm+macro concern gated by
/// `wasm_cbor_json_api_macro_compiles` below.
#[test]
fn flag_value_smoke() {
    use std::str::FromStr;
    let input = std::path::PathBuf::from_str("tests/canonical/input.cddl").unwrap();
    let cases: &[(&str, &[&str])] = &[
        ("annotate_fields_false", &["--annotate-fields=false"][..]),
        (
            "to_from_bytes_methods_false",
            &["--to-from-bytes-methods=false"][..],
        ),
        ("binary_wrappers_true", &["--binary-wrappers=true"][..]),
    ];
    // shared scratch + target under temp_dir (per-checkout, like the other generate+check gates)
    let scratch =
        std::env::temp_dir().join(format!("cddl_codegen_flag_smoke_{:016x}", checkout_hash()));
    let target_dir = scratch.join("target");
    let mut failures = Vec::new();
    for (label, options) in cases {
        let out = scratch.join(label);
        let _ = std::fs::remove_dir_all(&out);
        let gen_out = codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=false")
            .args(*options)
            .output()
            .unwrap();
        if !gen_out.status.success() {
            failures.push(format!(
                "{label}: generation failed\n{}",
                String::from_utf8_lossy(&gen_out.stderr)
            ));
            continue;
        }
        let check = tool_cmd("cargo")
            .arg("check")
            .current_dir(out.join("rust"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .output()
            .unwrap();
        if !check.status.success() {
            failures.push(format!(
                "{label}: cargo check failed\n{}",
                String::from_utf8_lossy(&check.stderr)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

/// `--preserve-encodings=true --annotate-fields=false` over bool/null fixed-value MEMBERS — a
/// standing cell for an escaped flag interaction (the third on record; policy per
/// tests/TESTING_ROADMAP.md's declined flag-powerset entry: escaped interactions earn their own
/// standing cells rather than the whole powerset). No profile combines preserve with
/// annotate=false, and `flag_value_smoke`'s annotate=false case runs a spec with no encoding-LESS
/// fixed member, so the combination's fixed-value deserialize path was unreachable by every gate:
/// it emitted a bare `()` value expr with no statement terminator before the next statement
/// (non-parsing output, array and map arms — found by reading during the optional-fixed-value
/// delivery, fixed by terminating the preserve-only trailing `()` with `;`). This cell generates
/// the two fixed-member corpus fixtures (mandatory: `fixed_bool_member.cddl`; optional presence
/// bools: `optional_fixed_member.cddl`) under exactly that flag pair and `cargo check`s the
/// result, so a regression fails here rather than only in a consumer running annotate=false.
/// Tier: check.ts `local` (the `test` gate).
#[test]
fn preserve_no_annotate_fixed_members_generate() {
    use std::str::FromStr;
    if !tool_exists("cargo") {
        return;
    }
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_pres_noann_fixed_{:016x}",
        checkout_hash()
    ));
    let target_dir = scratch.join("target");
    let mut failures = Vec::new();
    for (label, input) in [
        ("mandatory", "tests/corpus/fixed_bool_member.cddl"),
        ("optional", "tests/corpus/optional_fixed_member.cddl"),
    ] {
        let input = std::path::PathBuf::from_str(input).unwrap();
        let out = scratch.join(label);
        let _ = std::fs::remove_dir_all(&out);
        let gen_out = codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=false")
            .arg("--preserve-encodings=true")
            .arg("--annotate-fields=false")
            .output()
            .unwrap();
        if !gen_out.status.success() {
            failures.push(format!(
                "{label}: generation failed\n{}",
                String::from_utf8_lossy(&gen_out.stderr)
            ));
            continue;
        }
        let check = tool_cmd("cargo")
            .arg("check")
            .current_dir(out.join("rust"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .output()
            .unwrap();
        if !check.status.success() {
            failures.push(format!(
                "{label}: cargo check failed\n{}",
                String::from_utf8_lossy(&check.stderr)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

/// `--no-synthesized-rust-collection-aliases`: suppress ONLY generator-synthesized collection
/// wrapper rust aliases (a table rule's auto-named keys-list, `pub type FooList = Vec<Foo>;`), never
/// rule-declared ones. An authored `authored_list = [* foo]` and an authored table `tbl = { * foo =>
/// uint }` (`pub type Tbl = BTreeMap<..>`) are human-named and must survive. Provenance
/// (`AliasInfo::rule_metadata`) cannot tell the three apart — all register via `new_manual` with
/// `rule_metadata: None` — so this pins the explicit `synthesized_collection` marker end-to-end on
/// the emitted rust source. Flag-OFF byte-identity is the snapshot suite's job (this fixture is
/// generated into a temp dir, never a committed `export/`); here we assert the ON-side suppression +
/// rule-declared survival, plus that the wasm-side wrapper class is untouched (generated code still
/// references it structurally, so the crate must keep compiling). Tier: check.ts `local`.
#[test]
fn no_synthesized_rust_collection_aliases_suppresses_only_synthesized() {
    if !tool_exists("cargo") {
        return;
    }
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_no_synth_alias_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    // `foo` is an array struct (not directly-wasm-exposable), so `tbl`'s keys synthesize a
    // `FooList` keys-list wrapper; `authored_list` is a human-named array rule of the same shape's
    // element that must NOT be confused with it.
    std::fs::write(
        &input,
        "foo = [uint]\nauthored_list = [* foo]\ntbl = { * foo => uint }\n",
    )
    .unwrap();
    let out = scratch.join("out");
    let gen_out = codegen_cmd()
        .arg(format!("--input={}", input.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--wasm=true")
        .arg("--no-synthesized-rust-collection-aliases=true")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "generation failed:\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );
    let rust_mod = std::fs::read_to_string(out.join("rust/src/generated/mod.rs")).unwrap();
    // synthesized keys-list alias suppressed
    assert!(
        !rust_mod.contains("pub type FooList"),
        "synthesized keys-list alias `FooList` must be suppressed:\n{rust_mod}"
    );
    // rule-declared aliases survive byte-identical
    assert!(
        rust_mod.contains("pub type AuthoredList = Vec<Foo>;"),
        "authored array alias must survive:\n{rust_mod}"
    );
    assert!(
        rust_mod.contains("pub type Tbl = BTreeMap<Foo, u64>;"),
        "authored table alias must survive:\n{rust_mod}"
    );
    // wasm-side wrapper class + structural refs are untouched (only the RUST alias is gated)
    let wasm_mod = std::fs::read_to_string(out.join("wasm/src/generated/mod.rs")).unwrap();
    assert!(
        wasm_mod.contains("pub struct FooList("),
        "wasm `FooList` wrapper class must remain:\n{wasm_mod}"
    );
    // the emitted rust crate must still compile: the alias was pure API surface, everything is
    // referenced structurally as `Vec<Foo>`.
    let target_dir = scratch.join("target");
    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("rust"))
        .env("CARGO_TARGET_DIR", &target_dir)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "generated rust crate failed to compile with the flag on:\n{}",
        String::from_utf8_lossy(&check.stderr)
    );
}

/// The multi-scope half of the declared-spelling rule COMPILES: with a directory input, an alias
/// declared in module `a` and referred to by a record in module `b` is spelled declared in
/// `b/cbor_encodings.rs`, and the ident must actually be in scope there.
///
/// This needs a compile rather than a source assertion because the failure mode is E0412/E0433, not
/// a diff — `<scope>/cbor_encodings.rs` names the ident through `use super::*`, so the route depends
/// on the scope's own `mod.rs` binding it, and `mark_refs` marking both an alias ident and its target
/// was established for the SERIALIZATION file's idents, which is a different emission surface. Both
/// sidecar depths are exercised: the rest row's key domain (depth 1) and the container inside its
/// value (depth 2).
///
/// `--wasm=false` deliberately: a cross-scope NESTED-map wrapper (`{* epoch => {* policy_id => text}}`
/// with the aliases in another module) fails to emit its `MapEpochToMapPolicyIdToText` wasm class
/// (E0425). That is pre-existing and unrelated to spelling — it reproduces with every
/// `resolve_aliases` call restored, and a cross-scope FLAT map wrapper compiles fine — so including
/// wasm here would make this pin red for a reason it does not test. The source-level spelling +
/// routing assertions are in
/// `declared_spelling_tests::cross_scope_alias_is_spelled_and_routed_in_the_referring_scope`.
/// Tier: check.ts `local`.
#[test]
fn declared_spelling_cross_scope_encoding_crate_compiles() {
    if !tool_exists("cargo") {
        return;
    }
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_declspell_cross_scope_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    let input = scratch.join("input");
    std::fs::create_dir_all(&input).unwrap();
    std::fs::write(input.join("lib.cddl"), "rt = [uint]\n").unwrap();
    std::fs::write(input.join("a.cddl"), "epoch = uint\npolicy_id = bytes\n").unwrap();
    std::fs::write(
        input.join("b.cddl"),
        "holder = [m: {* epoch => text}]\n\
         open_holder = {1: uint, * epoch => {* policy_id => text}}\n\
         open_tail = [uint, * {* policy_id => text}]\n",
    )
    .unwrap();
    let out = scratch.join("out");
    let gen_out = codegen_cmd()
        .arg(format!("--input={}", input.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--preserve-encodings=true")
        .arg("--wasm=false")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "cross-scope generation failed:\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );

    // The spelling itself, so a compile-only pass cannot go green by resolving everything.
    let b_enc =
        std::fs::read_to_string(out.join("rust/src/generated/b/cbor_encodings.rs")).unwrap();
    assert!(
        b_enc.contains("BTreeMap<Epoch, Option<cbor_event::Sz>>")
            && b_enc.contains("BTreeMap<PolicyId, StringEncoding>"),
        "scope `b`'s encoding file must spell scope `a`'s aliases as declared at both \
         depths:\n{b_enc}"
    );

    let target_dir = scratch.join("target");
    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("rust"))
        .env("CARGO_TARGET_DIR", &target_dir)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "the cross-scope generated rust crate failed to compile — a declared spelling in \
         `b/cbor_encodings.rs` naming an ident from scope `a` is not routed into scope `b`:\n{}\n{}",
        String::from_utf8_lossy(&check.stdout),
        String::from_utf8_lossy(&check.stderr)
    );
    let _ = std::fs::remove_dir_all(&scratch);
}

/// The multi-scope half of the declared-spelling rule at member deserialize CALL TARGETS COMPILES:
/// with a directory input, an alias declared in module `a` and referred to by a record in module `b`
/// is CALLED by its declared name from `b/serialization.rs`, and that name must be in scope there.
///
/// The direction that needs proving is the one the change creates: before it, `b` named the alias's
/// TARGET (`Credential::deserialize`, `Hash::from_raw_bytes`) and `mark_refs` imported both idents
/// into `b`, which is why the target import existed at all. Afterwards the target import goes
/// unused and `import_prune` drops it — so the surviving import must be the one the call now names,
/// and getting that backwards is E0412/E0433 rather than a source diff. Asserted on the import LINE
/// too, so a pass cannot come from over-importing.
///
/// Covers both call-target families that can cross a scope: a nominal record (`T::deserialize`) and
/// a raw-bytes type (`T::from_raw_bytes`). The raw-bytes rule is externally defined, so the crate
/// carries a hand-written definition in its non-generated root — the same shape the
/// `external_rust_raw_bytes_def` integration cell uses. `--wasm=false` for the same reason as the
/// encoding-struct cell above. Tier: check.ts `local`.
#[test]
fn declared_spelling_cross_scope_call_target_crate_compiles() {
    if !tool_exists("cargo") {
        return;
    }
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_declspell_calltarget_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    let input = scratch.join("input");
    std::fs::create_dir_all(&input).unwrap();
    std::fs::write(input.join("lib.cddl"), "rt = [uint]\n").unwrap();
    std::fs::write(
        input.join("a.cddl"),
        "hash = _CDDL_CODEGEN_RAW_BYTES_TYPE_\n\
         script_hash = hash\n\
         credential = [idx: uint]\n\
         stake_credential = credential\n",
    )
    .unwrap();
    std::fs::write(
        input.join("b.cddl"),
        "holder = [sc: stake_credential, sh: script_hash]\n",
    )
    .unwrap();
    let out = scratch.join("out");
    let gen_out = codegen_cmd()
        .arg(format!("--input={}", input.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--preserve-encodings=true")
        .arg("--wasm=false")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "cross-scope generation failed:\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );

    let b_ser = std::fs::read_to_string(out.join("rust/src/generated/b/serialization.rs")).unwrap();
    assert!(
        b_ser.contains("StakeCredential::deserialize(raw)")
            && b_ser.contains("ScriptHash::from_raw_bytes(&bytes)"),
        "scope `b`'s call targets must name scope `a`'s aliases as declared:\n{b_ser}"
    );
    let b_mod = std::fs::read_to_string(out.join("rust/src/generated/b/mod.rs")).unwrap();
    assert!(
        b_mod.contains("use crate::generated::a::{ScriptHash, StakeCredential};"),
        "scope `b`'s import must be exactly the DECLARED idents its call targets now name — the \
         structural targets' imports become unused and are pruned:\n{b_mod}"
    );

    // The raw-bytes rule is externally defined; supply it in the hand-owned crate root so the
    // generated glue's `pub use crate::Hash;` resolves.
    let lib_rs = out.join("rust/src/lib.rs");
    let mut root = std::fs::read_to_string(&lib_rs).unwrap();
    root.push_str("\npub mod raw_bytes_defs;\npub use raw_bytes_defs::Hash;\n");
    std::fs::write(&lib_rs, root).unwrap();
    std::fs::write(
        out.join("rust/src/raw_bytes_defs.rs"),
        "use crate::generated::error::DeserializeError;\n\
         use crate::generated::serialization::RawBytesEncoding;\n\
         #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]\n\
         pub struct Hash(pub Vec<u8>);\n\
         impl RawBytesEncoding for Hash {\n\
         \x20   fn to_raw_bytes(&self) -> &[u8] { &self.0 }\n\
         \x20   fn from_raw_bytes(bytes: &[u8]) -> Result<Self, DeserializeError> { Ok(Self(bytes.to_vec())) }\n\
         }\n",
    )
    .unwrap();

    let target_dir = scratch.join("target");
    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("rust"))
        .env("CARGO_TARGET_DIR", &target_dir)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "the cross-scope generated rust crate failed to compile — a declared call target in \
         `b/serialization.rs` naming an ident from scope `a` is not routed into scope `b`:\n{}\n{}",
        String::from_utf8_lossy(&check.stdout),
        String::from_utf8_lossy(&check.stderr)
    );
    let _ = std::fs::remove_dir_all(&scratch);
}

/// The rust crate's c-style-enum `#[wasm_bindgen]` is gated behind the `--rust-wasm-feature` cargo
/// feature (default `wasm`), so the rust crate compiles STANDALONE — feature off — without the
/// optional wasm-bindgen dependency (the request this feature closes). Asserts (a) the emitted
/// attribute is the `cfg_attr` form and NEVER a bare/ungated `#[wasm_bindgen]`, and (b) `cargo check`
/// of the generated rust crate with the feature off succeeds. There is no workspace root above the
/// generated `rust/`, so this check exercises the feature-OFF path; a workspace build would instead
/// enable the feature via the wasm crate's path dep. Tier: check.ts `local`.
#[test]
fn rust_wasm_bindgen_feature_gated_crate_compiles_standalone() {
    if !tool_exists("cargo") {
        return;
    }
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_rust_wasm_feature_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    // a c-style enum is the one rust-crate construct that carries `#[wasm_bindgen]`
    std::fs::write(&input, "fixed_enum = 0 / 1 / 2\n").unwrap();
    let out = scratch.join("out");
    let gen_out = codegen_cmd()
        .arg(format!("--input={}", input.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--wasm=true")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "generation failed:\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );
    let rust_mod = std::fs::read_to_string(out.join("rust/src/generated/mod.rs")).unwrap();
    assert!(
        rust_mod.contains("#[cfg_attr(feature = \"wasm\", wasm_bindgen::prelude::wasm_bindgen)]"),
        "c-style enum must carry the feature-gated wasm_bindgen attribute:\n{rust_mod}"
    );
    // never an ungated one: a bare `#[wasm_bindgen…]` would force the optional dep on a standalone
    // rust build (the cfg_attr line starts with `#[cfg_attr`, so it does not match this).
    for line in rust_mod.lines() {
        assert!(
            !line.trim_start().starts_with("#[wasm_bindgen"),
            "ungated wasm_bindgen attribute in the generated rust crate:\n{line}"
        );
    }
    let target_dir = scratch.join("target");
    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("rust"))
        .env("CARGO_TARGET_DIR", &target_dir)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "standalone rust crate failed to compile with the wasm feature off:\n{}",
        String::from_utf8_lossy(&check.stderr)
    );
    let _ = std::fs::remove_dir_all(&scratch);
}

/// The `wasm/src/generated/collections.rs` re-export index (R3a): every wasm run emits exactly one
/// `pub use crate::…::<Wrapper>;` per collection wrapper CLASS the crate minted, sorted, no glob, no
/// cfg — a self-validating inventory (compiled as part of the crate, so a line naming a removed
/// wrapper fails the crate's own build). This pins the four placement shapes that a single-file
/// fixture cannot all produce, using a MULTIFILE (directory) input:
/// (a) a ROOT-scope structural list wrapper (`InnerList`, from an anonymous `[* inner]` field over a
///     non-exposable element) → `crate::generated::InnerList`;
/// (b) a sole-owner rule-NAMED table class at root (`RootTbl`) → `crate::generated::RootTbl`;
/// (c) a sole-owner rule-named table class in a NON-ROOT exported module (`SubTbl` in `sub/`) →
///     `crate::generated::sub::SubTbl`, verifying the multi-segment path derivation.
/// (d) the ROOT-minted keys-list wrapper of that non-root table (`SubKeyList`, minted because
///     `sub_tbl` is keyed by the NON-exposable record `sub_key`) → `crate::generated::SubKeyList`.
///     The `sub` table deliberately uses a non-exposable KEY so its `keys()` accessor names
///     `SubKeyList` — a root-minted wrapper the non-root `SubTbl` class must import
///     (`use crate::generated::SubKeyList;`). Before the `mark_refs` keys-list registration this
///     dangled E0425 (cddl-matrix/ROADMAP.md § findings, now retired; enumerated as the `tblrec`
///     multifile cells); the compile assertion below is what would catch a regression here.
/// The acceptance property (feature-request criterion 4) is that the wasm crate COMPILES with the
/// index in place; we assert that here alongside the exact line set. Tier: check.ts `local`.
#[test]
fn wasm_collections_index_lists_every_minted_wrapper() {
    if !tool_exists("cargo") {
        return;
    }
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_collections_index_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    let inputs = scratch.join("inputs");
    std::fs::create_dir_all(inputs.join("sub")).unwrap();
    // Root scope: `inner` is an array struct (not directly-wasm-exposable), so the anonymous
    // `[* inner]` field mints the structural `InnerList` at root, and `root_tbl` is the sole owner
    // of the `{ inner => text }` shape (a real JS class `RootTbl` at root). `holder` also references
    // `sub_tbl` so the non-root class is reachable.
    std::fs::write(
        inputs.join("lib.cddl"),
        "inner = [uint]\n\
         holder = [\n\
         \x20   items: [* inner],\n\
         \x20   r: root_tbl,\n\
         \x20   s: sub_tbl,\n\
         ]\n\
         root_tbl = { * inner => text }\n",
    )
    .unwrap();
    // Non-root module `sub`: `sub_tbl` is the sole owner of the `{ sub_key => text }` shape, so its
    // JS class `SubTbl` is emitted into `crate::generated::sub`. Its KEY `sub_key` is a record
    // (non-exposable), so `keys()` names the ROOT-minted keys-list wrapper `SubKeyList` — which the
    // non-root `SubTbl` class must import (the `mark_refs` keys-list registration; the fixed
    // non-exposable-key placement class, enumerated as the `tblrec` multifile cells).
    std::fs::write(
        inputs.join("sub/mod.cddl"),
        "sub_key = [b0: uint]\n\
         sub_tbl = { * sub_key => text }\n",
    )
    .unwrap();

    let out = scratch.join("out");
    let gen_out = codegen_cmd()
        .arg(format!("--input={}", inputs.to_str().unwrap()))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--wasm=true")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "generation failed:\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );

    // The index is declared from the always-regenerated generated root, never the seed-once lib.rs.
    let wasm_mod = std::fs::read_to_string(out.join("wasm/src/generated/mod.rs")).unwrap();
    assert!(
        wasm_mod.contains("pub mod collections;"),
        "generated wasm root mod.rs must declare `pub mod collections;`:\n{wasm_mod}"
    );
    let wasm_root = std::fs::read_to_string(out.join("wasm/src/lib.rs")).unwrap();
    assert!(
        !wasm_root.contains("collections"),
        "the seed-once crate-root lib.rs must NOT declare the collections module:\n{wasm_root}"
    );

    // Exactly the three expected `pub use` lines (order is rustfmt-canonical, hence deterministic;
    // compare as a set so the assertion pins CONTENT + COUNT, not rustfmt's ordering choice).
    let collections =
        std::fs::read_to_string(out.join("wasm/src/generated/collections.rs")).unwrap();
    let pub_uses: std::collections::BTreeSet<&str> = collections
        .lines()
        .map(str::trim)
        .filter(|l| l.starts_with("pub use "))
        .collect();
    let expected: std::collections::BTreeSet<&str> = [
        "pub use crate::generated::InnerList;",
        "pub use crate::generated::RootTbl;",
        "pub use crate::generated::SubKeyList;",
        "pub use crate::generated::sub::SubTbl;",
    ]
    .into_iter()
    .collect();
    assert_eq!(
        pub_uses, expected,
        "collections.rs must list exactly the four minted wrappers:\n{collections}"
    );

    // Acceptance property: the wasm crate (index included) compiles. `cargo check` on the wasm
    // manifest also builds its path-dep rust crate, so a bad index path is a hard failure here.
    let target_dir = scratch.join("target");
    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("wasm"))
        .env("CARGO_TARGET_DIR", &target_dir)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "generated wasm crate failed to compile with the collections index:\n{}",
        String::from_utf8_lossy(&check.stderr)
    );
}

/// Clippy over generated crates: the emitted deserialize/serialize source must be `clippy::all`-clean
/// (no `clippy::no_effect` degenerate `();` statements, no other default clippy lints), per emission
/// profile. Snapshots pin that the emitted bytes don't *change*, not that they're *idiomatic* — a
/// generator regression that mints lint-worthy code (a standalone `();`, a needless clone, a
/// pointless match) is invisible to them and to the round-trip suites (the code still compiles and
/// works), but it degrades every consumer's `cargo clippy`. This runs `cargo clippy -- -D
/// clippy::all` over a rich, extern-free fixture (`tests/canonical/input.cddl`, which
/// `flag_value_smoke` already relies on for exactly its extern-freedom + breadth) under two
/// representative profiles: default flags, and `--preserve-encodings=true --canonical-form=true`.
///
/// Deny only `clippy::all` plus a curated rustc style-lint set, NOT `-D warnings`: generated code
/// legitimately over-imports traits/globs (only the concrete collection-type imports are pruned —
/// `import_prune`) and rustc's `unused_imports` / `unused_variables` must stay warnings
/// here (see `tool_cmd`'s doc comment; `tool_cmd` also strips the CI-injected `RUSTFLAGS=-D
/// warnings`). The rustc denies cover emitted source-shape regressions `clippy::all` does not:
/// redundant grouping (`unused_parens`, `unused_braces`) and useless heap allocation
/// (`unused_allocation`), each proven green for both profiles when this axis was added.
/// Generate-into-own-temp-dir shape mirrors `flag_value_smoke` so this gate can't race the fixtures'
/// own `tests/<dir>/export` outputs. `--wasm=true` generates both the rust and wasm crates; the rust
/// output differs from `--wasm=false` only by an extra wasm-support type alias in this fixture, so a
/// single generation run covers the prior rust surface and lets the gate lint the wasm binding crate
/// too. Tier: check.ts `local` (a plain non-ignored test) — measured warm wall-clock stays under the
/// ~90s plain-`#[test]` threshold. NEVER promote to `fast`/CI.
#[test]
fn generated_code_clippy_clean() {
    use std::str::FromStr;
    if !tool_exists("cargo") {
        return;
    }
    const RUSTC_STYLE_DENIES: &[&str] = &[
        "-D",
        "unused_parens",
        "-D",
        "unused_braces",
        "-D",
        "unused_allocation",
    ];
    const PERMANENT_ALLOWS: &[&str] = &["-A", "clippy::disallowed_names"];
    let input = std::path::PathBuf::from_str("tests/canonical/input.cddl").unwrap();
    let cases: &[(&str, &[&str])] = &[
        ("default", &[][..]),
        (
            "preserve_canonical",
            &["--preserve-encodings=true", "--canonical-form=true"][..],
        ),
    ];
    // shared scratch + target under temp_dir (per-checkout), like `flag_value_smoke` and the other
    // generate+check gates — never the committed `tests/<dir>/export` dirs the fixtures reuse.
    let scratch =
        std::env::temp_dir().join(format!("cddl_codegen_clippy_gate_{:016x}", checkout_hash()));
    let target_dir = scratch.join("target");
    let mut failures = Vec::new();
    for (label, options) in cases {
        let out = scratch.join(label);
        let _ = std::fs::remove_dir_all(&out);
        let gen_out = codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=true")
            .args(*options)
            .output()
            .unwrap();
        if !gen_out.status.success() {
            failures.push(format!(
                "{label}: generation failed\n{}",
                String::from_utf8_lossy(&gen_out.stderr)
            ));
            continue;
        }
        let clippy = tool_cmd("cargo")
            .arg("clippy")
            .current_dir(out.join("rust"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .args(["--", "-D", "clippy::all"])
            .args(RUSTC_STYLE_DENIES)
            // Input-dependent, permanent allow: the fixture's own `foo`/`bar` rule names become
            // generated parameter names, which clippy::disallowed_names flags — not a generator
            // defect. This is the rust crate's ONLY allow: the emission-quality burn-down list is
            // fully retired, so every other clippy::all lint class (and any NEW one a generator
            // regression might mint) is hard-red on both profiles.
            .args(PERMANENT_ALLOWS)
            .output()
            .unwrap();
        if !clippy.status.success() {
            failures.push(format!(
                "{label}: `cargo clippy -- -D clippy::all` failed on the generated rust crate\n\
                 --- stdout ---\n{}\n--- stderr ---\n{}",
                String::from_utf8_lossy(&clippy.stdout),
                String::from_utf8_lossy(&clippy.stderr)
            ));
        }
        let wasm_clippy = tool_cmd("cargo")
            .arg("clippy")
            .current_dir(out.join("wasm"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .args(["--", "-D", "clippy::all"])
            .args(RUSTC_STYLE_DENIES)
            .args(PERMANENT_ALLOWS)
            // The wasm crate's emission-quality burn-down list is fully retired too. New
            // clippy::all lint classes are hard-red on both profiles and both generated crates.
            .output()
            .unwrap();
        if !wasm_clippy.status.success() {
            failures.push(format!(
                "{label}: `cargo clippy -- -D clippy::all` failed on the generated wasm crate\n\
                 --- stdout ---\n{}\n--- stderr ---\n{}",
                String::from_utf8_lossy(&wasm_clippy.stdout),
                String::from_utf8_lossy(&wasm_clippy.stderr)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

/// `--canonical-form=true` without `--preserve-encodings` must be rejected (it otherwise emits a
/// non-compiling crate — see `api::with_types`). Pins the rejection *and* its message so the guard
/// can't silently become a no-op, and confirms the same input with both flags is accepted — so the
/// rejection is specific to the missing `--preserve-encodings`, not the input.
#[test]
fn flag_value_rejects_canonical_without_preserve() {
    let mut cli = crate::cli::Cli {
        input: std::path::PathBuf::from("tests/canonical/input.cddl"),
        output: std::path::PathBuf::from("unused"),
        canonical_form: true,
        preserve_encodings: false,
        ..Default::default()
    };
    let err = crate::api::with_types(&cli, |_, _| ())
        .expect_err("--canonical-form without --preserve-encodings should be rejected");
    let msg = err.to_string();
    assert!(
        msg.contains("--canonical-form") && msg.contains("--preserve-encodings"),
        "rejection message should name both flags, got: {msg}"
    );
    // baseline: with preserve-encodings the same input is accepted (so it's the combination, not
    // the input, that's rejected)
    cli.preserve_encodings = true;
    assert!(
        crate::api::with_types(&cli, |_, _| ()).is_ok(),
        "--canonical-form with --preserve-encodings should be accepted"
    );
}

/// A spec whose finalized IR lowers CDDL `any` to the `AnyCbor` runtime type is a FULL-surface
/// citizen: accepted under `--wasm=true` (the wasm wrapper class), under the JSON
/// flags (serde/schemars), and rust-only — including all three at once. Pins that no flag
/// combination rejects on `any`'s account, so a future regression that re-adds any such guard is
/// caught. (Predecessor: `flag_value_rejects_any_under_wasm_but_accepts_json`, retired when the wasm
/// guard was lifted.)
#[test]
fn flag_value_accepts_any_under_all_surfaces() {
    // tests/robustness/any_member.cddl is `a = [any]` — its IR contains `Any`. `Cli` isn't `Clone`,
    // so build a fresh base per case and flip exactly the surface flags under test.
    let any_cli = |wasm: bool, serde: bool, schemars: bool| crate::cli::Cli {
        input: std::path::PathBuf::from("tests/robustness/any_member.cddl"),
        output: std::path::PathBuf::from("unused"),
        wasm,
        json_serde_derives: serde,
        json_schema_export: schemars,
        ..Default::default()
    };

    // Every surface combination — wasm, each JSON flag, all together, and rust-only — is ACCEPTED.
    for (wasm, serde, schemars) in [
        (true, false, false),
        (false, true, false),
        (false, false, true),
        (false, true, true),
        (true, true, true),
        (false, false, false),
    ] {
        assert!(
            crate::api::with_types(&any_cli(wasm, serde, schemars), |_, _| ()).is_ok(),
            "`any` should be accepted under wasm={wasm} serde={serde} schemars={schemars}"
        );
    }
}

/// A user rule literally named `any` (`any = uint`) must SHADOW the prelude `any` and behave
/// exactly as it did before `ConceptualRustType::Any` existed: it registers a user type alias
/// (`Any = u64`) resolved via `resolve_alias` BEFORE the `new_type` fallback that intercepts the
/// bare prelude name, so a member typed `any` gets the user's uint, NOT the `AnyCbor` runtime type,
/// and no `any_cbor` module is pulled in. Pins the interception seam's shadowing guarantee (A2).
#[test]
fn user_rule_named_any_shadows_the_prelude() {
    // tests/any-shadow/input.cddl is `any = uint` + `foo = {1: any}` + a choice arm `bar = tstr / any`.
    let files = crate::api::generated_strings(&crate::cli::Cli {
        input: std::path::PathBuf::from("tests/any-shadow/input.cddl"),
        output: std::path::PathBuf::from("unused"),
        static_dir: std::path::PathBuf::from("static"),
        wasm: false,
        ..Default::default()
    })
    .expect("shadowed `any` should generate");
    let all = files.values().cloned().collect::<String>();
    // The user alias wins in EVERY position — member (`foo`) AND type-choice arm (`bar`): the field
    // and the arm are the uint-backed `Any` alias, never the runtime AnyCbor. A choice arm that
    // failed to resolve the shadow would either lower to `AnyCbor` or force backtracking dispatch.
    assert!(
        !all.contains("AnyCbor") && !all.contains("any_cbor"),
        "a user `any = uint` rule must not pull in the AnyCbor runtime type"
    );
    // `bar = tstr / any` is an ordinary `tstr / uint` choice: the arm resolves to the user's uint
    // alias, so the enum gains an `Any(Any)` variant carrying the u64-backed user alias — NOT the
    // catch-all runtime type. (`pub type Any = u64;` is the user rule; the variant reuses its name.)
    assert!(
        all.contains("pub enum Bar") && all.contains("Any(Any)") && all.contains("type Any = u64"),
        "the shadowed `any` choice arm must reuse the user's uint alias, not the runtime type:\n{all}"
    );

    // baseline: WITHOUT the shadowing rule, `{1: any}` (tests/robustness/any_member.cddl's sibling
    // shape) DOES lower to AnyCbor — so the shadowing above is the cause, not the input.
    let unshadowed = crate::api::generated_strings(&crate::cli::Cli {
        input: std::path::PathBuf::from("tests/robustness/any_member.cddl"),
        output: std::path::PathBuf::from("unused"),
        static_dir: std::path::PathBuf::from("static"),
        wasm: false,
        ..Default::default()
    })
    .expect("bare `any` should generate rust-only");
    assert!(
        unshadowed.values().any(|c| c.contains("any_cbor::AnyCbor")),
        "an unshadowed `any` position must lower to the AnyCbor runtime type"
    );
}

/// The manifest merge contract on real disk (the `cargo_manifest` changeset applied through
/// `export`): a first run scaffolds `rust/Cargo.toml`; a user then hand-edits it (bumps the seeded
/// `version`, adds their own dep + comments, tampers the version stamp); a regeneration must
/// **preserve** the untouched user content and the `SeedOnce` version, **restore** the tool-owned
/// stamp, and a third regeneration must be a byte-identical fixed point. Driven in-process via
/// `generate_to_disk` (no subprocess/compile — this exercises the disk-merge path, not codegen
/// correctness, which the compile gates cover). `--wasm=false` keeps it to the single rust manifest.
#[test]
fn cargo_manifest_disk_round_trip() {
    use clap::Parser;
    let scratch =
        std::env::temp_dir().join(format!("cddl_codegen_manifest_rt_{:016x}", checkout_hash()));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    std::fs::write(&input, "foo = [x: uint]\n").unwrap();
    let out = scratch.join("crate");

    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input",
        input.to_str().unwrap(),
        "--output",
        out.to_str().unwrap(),
        "--wasm=false",
    ]);
    let manifest = out.join("rust/Cargo.toml");

    // First run: scaffolds the manifest with tool-owned keys + the write-only version stamp.
    crate::api::generate_to_disk(&cli).unwrap();
    let first = std::fs::read_to_string(&manifest).unwrap();
    let tool_version = env!("CARGO_PKG_VERSION");
    assert!(
        first.contains("cbor_event"),
        "tool-owned dep missing:\n{first}"
    );
    assert!(
        first.contains(&format!("generated-with = \"{tool_version}\"")),
        "version stamp missing:\n{first}"
    );

    // Hand-edit: bump the seeded version, tamper the stamp, add a user dep with an inline comment,
    // prepend a top-of-file comment, and reshape the tool-owned `cbor_event` dep (a git table since
    // the fork pin) by adding a user-only `optional = false` field. All but the stamp must survive
    // (the reshape exercises the field-level dep merge on a real disk round trip); the stamp must be
    // restored.
    assert!(
        first.contains("cbor_event = { git = "),
        "expected the git-table cbor_event dep to reshape:\n{first}"
    );
    let edited = format!(
        "# hand-written top comment\n{}\nanyhow = \"1\" # user pin\n",
        first
            .replace("version = \"0.1.0\"", "version = \"9.9.9\"")
            .replace(
                "cbor_event = { git = ",
                "cbor_event = { optional = false, git = "
            )
            .replace(
                &format!("generated-with = \"{tool_version}\""),
                "generated-with = \"0.0.0-tampered\"",
            )
    );
    std::fs::write(&manifest, &edited).unwrap();

    // Second run: merge onto the edited manifest.
    crate::api::generate_to_disk(&cli).unwrap();
    let second = std::fs::read_to_string(&manifest).unwrap();
    assert!(
        second.contains("version = \"9.9.9\""),
        "SeedOnce version must survive regen:\n{second}"
    );
    assert!(
        second.contains("anyhow = \"1\""),
        "user-added dep must survive regen:\n{second}"
    );
    assert!(
        second.contains("# hand-written top comment") && second.contains("# user pin"),
        "user comments must survive regen:\n{second}"
    );
    assert!(
        second.contains(&format!("generated-with = \"{tool_version}\"")),
        "tool-owned stamp must be restored:\n{second}"
    );
    assert!(
        !second.contains("0.0.0-tampered"),
        "tampered stamp must be overwritten:\n{second}"
    );
    assert!(
        second.contains("cbor_event"),
        "tool-owned dep must persist:\n{second}"
    );
    // the user's reshape (the added `optional` field) survives the field-level dep merge, and the
    // git source assertion stays clean — no version key materializes beside the git source.
    assert!(
        second.contains("optional = false"),
        "user-added dep field must survive the dep merge:\n{second}"
    );
    let cbor_line = second
        .lines()
        .find(|l| l.trim_start().starts_with("cbor_event = "))
        .expect("cbor_event dep missing");
    assert!(
        cbor_line.contains("git = ")
            && cbor_line.contains("rev = ")
            && !cbor_line.contains("version"),
        "the merged git dep must stay version-free:\n{cbor_line}"
    );

    // Third run: byte-identical fixed point.
    crate::api::generate_to_disk(&cli).unwrap();
    let third = std::fs::read_to_string(&manifest).unwrap();
    assert_eq!(
        second, third,
        "regeneration must reach a byte-identical fixed point"
    );

    let _ = std::fs::remove_dir_all(&scratch);
}

/// `--package-json` must create the output directory it writes `package.json` into.
///
/// Every other artifact reaches disk through a write that `create_dir_all`s its parent first, so a
/// fresh `--output` gets scaffolded on the way; the npm manifest is a `fs::copy` straight into the
/// output ROOT, which has no such parent pass. The gap is only reachable when nothing else created
/// that root first — i.e. `--package-json` WITHOUT `--json-schema-export`/`--json-schema-scripts`,
/// whose script copy creates `<output>/scripts` — and it surfaced as a bare
/// `Os { code: 2, kind: NotFound }` naming no file at all.
///
/// Both directions are asserted: the same fresh directory generates fine WITHOUT the flag, so a
/// regression cannot be excused as "creating the output directory is the caller's job".
#[test]
fn package_json_creates_a_missing_output_directory() {
    use clap::Parser;
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_pkg_json_mkdir_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    std::fs::write(&input, "foo = [x: uint]\n").unwrap();

    let run = |out: &std::path::Path, package_json: bool| {
        crate::api::generate_to_disk(&crate::cli::Cli::parse_from([
            "cddl-codegen",
            "--input",
            input.to_str().unwrap(),
            "--output",
            out.to_str().unwrap(),
            "--package-json",
            if package_json { "true" } else { "false" },
        ]))
    };

    let without = scratch.join("no-package-json");
    run(&without, false).expect("a fresh output directory generates without --package-json");

    let with = scratch.join("with-package-json");
    assert!(
        !with.exists(),
        "the discriminating premise: the output directory must not exist yet"
    );
    run(&with, true).unwrap_or_else(|e| {
        panic!("--package-json must create its own output directory, got: {e:?}")
    });
    assert!(
        with.join("package.json").is_file(),
        "the npm manifest must land in the created directory"
    );

    let _ = std::fs::remove_dir_all(&scratch);
}

/// The `lib.rs` seed-once contract (the thin-root counterpart of the manifest changeset): a first
/// export seeds a thin root (`mod generated; pub use generated::*;`) and emits every generated file
/// under `rust/src/generated/**`; the root is thereafter user-owned and NEVER rewritten — an
/// existence check only, mirroring `ManifestOp::SeedOnce`. Deleting a generated file and hand-editing
/// the root, then re-exporting, must leave the root byte-identical and restore the subtree; a third
/// run is a byte-identical fixed point. In-process via `generate_to_disk` (no compile — the compile +
/// behavioral coverage of the split lives in the `extern_deps` fixture and the snapshot corpus).
#[test]
fn thin_root_seed_once() {
    use clap::Parser;
    let scratch =
        std::env::temp_dir().join(format!("cddl_codegen_thin_seed_{:016x}", checkout_hash()));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    std::fs::write(&input, "foo = [x: uint]\n").unwrap();
    let out = scratch.join("crate");
    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input",
        input.to_str().unwrap(),
        "--output",
        out.to_str().unwrap(),
        "--wasm=true",
    ]);
    let lib_rs = out.join("rust/src/lib.rs");
    let generated_mod = out.join("rust/src/generated/mod.rs");

    // First run: seeds the thin root and emits the generated subtree.
    crate::api::generate_to_disk(&cli).unwrap();
    let seeded = std::fs::read_to_string(&lib_rs).unwrap();
    assert!(
        seeded.contains("mod generated;"),
        "seeded root must declare the generated module:\n{seeded}"
    );
    assert!(
        seeded.contains("pub use generated::*;"),
        "seeded root must glob-re-export the generated module:\n{seeded}"
    );
    assert!(
        !seeded.contains("struct Foo"),
        "generated type definitions must live under generated/, not the thin root:\n{seeded}"
    );
    assert!(
        generated_mod.exists(),
        "generated/mod.rs must exist after the first export"
    );

    // The wasm crate root gets the identical seed-once split.
    let wasm_seeded = std::fs::read_to_string(out.join("wasm/src/lib.rs")).unwrap();
    assert!(
        wasm_seeded.contains("mod generated;") && wasm_seeded.contains("pub use generated::*;"),
        "the wasm crate root must be seeded with the same thin root:\n{wasm_seeded}"
    );
    assert!(
        out.join("wasm/src/generated/mod.rs").exists(),
        "wasm generated/mod.rs must exist after the first export"
    );

    // The root is now user-owned: hand-edit it and delete a generated file.
    let user_edited = format!("{seeded}\npub mod utils;\n");
    std::fs::write(&lib_rs, &user_edited).unwrap();
    std::fs::remove_file(&generated_mod).unwrap();

    // Second run: existence-only — the root is preserved verbatim, the subtree restored.
    crate::api::generate_to_disk(&cli).unwrap();
    let after = std::fs::read_to_string(&lib_rs).unwrap();
    assert_eq!(
        user_edited, after,
        "seed-once root must survive regeneration byte-for-byte"
    );
    assert!(
        generated_mod.exists(),
        "the generated subtree must be restored on re-export"
    );

    // Third run: byte-identical fixed point.
    crate::api::generate_to_disk(&cli).unwrap();
    let third = std::fs::read_to_string(&lib_rs).unwrap();
    assert_eq!(
        after, third,
        "seed-once root must reach a byte-identical fixed point"
    );

    let _ = std::fs::remove_dir_all(&scratch);
}

/// The wiring-survival regression (the CML cip25 clobber, mechanized): a hand-wired thin root that
/// wires a user-supplied module (`pub mod utils; pub use utils::Helper;` — the extern-type shape)
/// must survive regeneration untouched, and the user module must be left in place while the generated
/// subtree is regenerated beside it. This is the failure the whole feature exists to prevent. Beyond
/// byte survival, the hand-wired crate must actually COMPILE after the regenerated-over run: the
/// design doc's contract is that hand wiring referencing generated types through the crate-root glob
/// (`utils.rs`'s fn takes and returns a generated `Foo`) keeps resolving. Guarded on `cargo` so the
/// byte-level assertions still run on a toolchain-less box.
#[test]
fn thin_root_wiring_survives() {
    use clap::Parser;
    let scratch =
        std::env::temp_dir().join(format!("cddl_codegen_thin_wire_{:016x}", checkout_hash()));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    std::fs::write(&input, "foo = [x: uint]\n").unwrap();
    let out = scratch.join("crate");
    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input",
        input.to_str().unwrap(),
        "--output",
        out.to_str().unwrap(),
        "--wasm=false",
    ]);
    let lib_rs = out.join("rust/src/lib.rs");
    let utils_rs = out.join("rust/src/utils.rs");

    // First run seeds the thin root; the user then hand-wires an extern-type module into it. The
    // module reaches generated types through the crate-root glob (`crate::Foo`) — the exact shape an
    // extern-type consumer (CML's cip25) hand-maintains.
    crate::api::generate_to_disk(&cli).unwrap();
    let hand_wired =
        "// hand-wired root\nmod generated;\npub use generated::*;\npub mod utils;\npub use utils::Helper;\n"
            .to_owned();
    std::fs::write(&lib_rs, &hand_wired).unwrap();
    std::fs::write(
        &utils_rs,
        "use crate::Foo;\npub struct Helper;\npub fn round_trip(f: Foo) -> Foo {\n    f\n}\n",
    )
    .unwrap();

    // Regenerate over the same directory: the hand wiring must survive.
    crate::api::generate_to_disk(&cli).unwrap();
    let after = std::fs::read_to_string(&lib_rs).unwrap();
    assert_eq!(
        hand_wired, after,
        "hand wiring in the thin root must survive regeneration byte-for-byte"
    );
    assert_eq!(
        std::fs::read_to_string(&utils_rs).unwrap(),
        "use crate::Foo;\npub struct Helper;\npub fn round_trip(f: Foo) -> Foo {\n    f\n}\n",
        "the user-supplied module must be left untouched"
    );
    assert!(
        out.join("rust/src/generated/mod.rs").exists(),
        "the generated subtree must be regenerated beside the user module"
    );

    // A further regeneration is still a fixed point for the user-owned root.
    crate::api::generate_to_disk(&cli).unwrap();
    assert_eq!(
        hand_wired,
        std::fs::read_to_string(&lib_rs).unwrap(),
        "thin root must remain a byte-identical fixed point across runs"
    );

    // The regenerated-over crate must compile: the hand-wired root + `utils.rs` referencing a
    // generated type through the glob resolve against the freshly clobbered `src/generated/**`.
    if tool_exists("cargo") {
        let target_dir = scratch.join("target");
        let build = tool_cmd("cargo")
            .arg("build")
            .current_dir(out.join("rust"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .output()
            .unwrap();
        assert!(
            build.status.success(),
            "hand-wired crate must compile after the regenerated-over export\n{}\n{}",
            String::from_utf8_lossy(&build.stdout),
            String::from_utf8_lossy(&build.stderr)
        );
    }

    let _ = std::fs::remove_dir_all(&scratch);
}

/// In-crate extern types must resolve under the thin-root split (the CML cip25 scenario the feature
/// exists for). Given `my_ext = _CDDL_CODEGEN_EXTERN_TYPE_` used by a generated `wrapper`, generated
/// code refers to the extern by its bare ident inside `generated/mod.rs` (and via `use super::*;`
/// inside `generated/serialization.rs`). Pre-split those names resolved because the user's
/// `pub use utils::MyExt;` sat in the SAME root scope (the monolithic `lib.rs`); post-split the user
/// can only edit the thin `lib.rs`, and a parent-module name is NOT visible inside `mod generated`, so
/// the crate failed to build with E0433 "cannot find type `MyExt`". The tool now emits
/// `pub use crate::MyExt;` into the declaring scope's generated module, and the documented contract is:
/// define the extern in a hand-written module and RE-EXPORT it at the crate root — the identical action
/// pre-split consumers already took. This gate hand-wires exactly that shape and asserts the crate both
/// keeps the seeded `lib.rs` byte-identical AND compiles. `cargo`-guarded so the wiring assertions still
/// run on a toolchain-less box. Covers the default and `--preserve-encodings` profiles (preserve reshapes
/// the deserializer's imports/signatures, but the extern's own impls are unchanged — the extern carries
/// no encoding metadata — so the same `utils.rs` serves both).
///
/// A third profile covers the WASM crate, which has the identical latent shape: generated wasm code
/// names the extern's hand-written `#[wasm_bindgen]` WRAPPER bare inside `wasm/src/generated/**`, but
/// the wrapper is user-authored (a real consumer, e.g. CML cip25, defines it in a hand-written wasm
/// module). Under the split those references can't see it — same E0433. The tool emits the same
/// `pub use crate::MyExt;` glue into the wasm generated module; the contract is to define the wrapper in
/// a hand-written wasm-crate module and RE-EXPORT it at the wasm crate root. The wasm crate builds as a
/// host crate (it depends on the rust crate as a path dep, so the rust side is wired too), which the
/// harness already `cargo build`s.
#[test]
fn thin_root_in_crate_extern_type_compiles() {
    use clap::Parser;

    fn run(profile: &str, extra_flags: &[&str]) {
        let scratch = std::env::temp_dir().join(format!(
            "cddl_codegen_thin_extern_{profile}_{:016x}",
            checkout_hash()
        ));
        let _ = std::fs::remove_dir_all(&scratch);
        std::fs::create_dir_all(&scratch).unwrap();
        let input = scratch.join("input.cddl");
        std::fs::write(
            &input,
            "my_ext = _CDDL_CODEGEN_EXTERN_TYPE_\nwrapper = [id: uint, ext: my_ext]\n",
        )
        .unwrap();
        let out = scratch.join("crate");
        let mut args = vec![
            "cddl-codegen",
            "--input",
            input.to_str().unwrap(),
            "--output",
            out.to_str().unwrap(),
            "--wasm=false",
        ];
        args.extend_from_slice(extra_flags);
        let cli = crate::cli::Cli::parse_from(args);
        let lib_rs = out.join("rust/src/lib.rs");
        let utils_rs = out.join("rust/src/utils.rs");

        // First export seeds the thin root; capture it to assert seed-once leaves it byte-identical.
        crate::api::generate_to_disk(&cli).unwrap();
        let seeded = std::fs::read_to_string(&lib_rs).unwrap();

        // Hand-wire the extern exactly as the docs prescribe: a user module that DEFINES the extern, and
        // a crate-root re-export. This is the only edit a post-split consumer can make (the thin root is
        // user-owned; `generated/**` is clobbered every run).
        let hand_wired = format!("{seeded}\npub mod utils;\npub use utils::MyExt;\n");
        std::fs::write(&lib_rs, &hand_wired).unwrap();
        // The extern's Rust definition. Default profile: `Serialize` is `cbor_event::se::Serialize`,
        // `Deserialize` is `crate::serialization::Deserialize`, error type `crate::error::DeserializeError`
        // — all reachable from a crate-root module through the seeded `pub use generated::*;` glob.
        std::fs::write(
            &utils_rs,
            "use crate::error::DeserializeError;\n\
             use crate::serialization::Deserialize;\n\
             \n\
             #[derive(Clone, Debug)]\n\
             pub struct MyExt(pub u64);\n\
             \n\
             impl cbor_event::se::Serialize for MyExt {\n\
             \x20   fn serialize<'se>(\n\
             \x20       &self,\n\
             \x20       serializer: &'se mut cbor_event::se::Serializer,\n\
             \x20   ) -> cbor_event::Result<&'se mut cbor_event::se::Serializer> {\n\
             \x20       serializer.write_unsigned_integer(self.0)\n\
             \x20   }\n\
             }\n\
             \n\
             impl Deserialize for MyExt {\n\
             \x20   fn deserialize(\n\
             \x20       raw: &mut cbor_event::de::Deserializer,\n\
             \x20   ) -> Result<Self, DeserializeError> {\n\
             \x20       Ok(Self(raw.unsigned_integer()?))\n\
             \x20   }\n\
             }\n",
        )
        .unwrap();

        // Regenerate over the same directory: seed-once must leave the hand-wired root byte-identical
        // (the generated subtree is re-clobbered beside it, carrying the fresh `pub use crate::MyExt;`).
        crate::api::generate_to_disk(&cli).unwrap();
        assert_eq!(
            hand_wired,
            std::fs::read_to_string(&lib_rs).unwrap(),
            "[{profile}] the hand-wired thin root must survive regeneration byte-for-byte"
        );

        // The generator must emit the re-export glue into the declaring (root) scope's module so the
        // bare `MyExt` references in `generated/mod.rs` and (via `use super::*;`) the serializer resolve.
        let generated_mod = std::fs::read_to_string(out.join("rust/src/generated/mod.rs")).unwrap();
        assert!(
            generated_mod.contains("pub use crate::MyExt;"),
            "[{profile}] generated/mod.rs must re-export the in-crate extern from the crate root:\n{generated_mod}"
        );

        if tool_exists("cargo") {
            let target_dir = scratch.join("target");
            let build = tool_cmd("cargo")
                .arg("build")
                .current_dir(out.join("rust"))
                .env("CARGO_TARGET_DIR", &target_dir)
                .output()
                .unwrap();
            assert!(
                build.status.success(),
                "[{profile}] hand-wired in-crate extern crate must compile\n{}\n{}",
                String::from_utf8_lossy(&build.stdout),
                String::from_utf8_lossy(&build.stderr)
            );
        }

        let _ = std::fs::remove_dir_all(&scratch);
    }

    // The WASM crate carries the identical latent shape — generated wasm code names the extern's
    // hand-written `#[wasm_bindgen]` WRAPPER bare inside `wasm/src/generated/**`, invisible there under
    // the split. Hand-wire the wasm wrapper (define + re-export at the wasm crate root) exactly as the
    // docs prescribe, plus the rust-side wiring (the wasm crate depends on the rust crate), and assert
    // both thin roots survive regeneration byte-for-byte AND the wasm crate compiles as a host crate.
    fn run_wasm() {
        let scratch = std::env::temp_dir().join(format!(
            "cddl_codegen_thin_extern_wasm_{:016x}",
            checkout_hash()
        ));
        let _ = std::fs::remove_dir_all(&scratch);
        std::fs::create_dir_all(&scratch).unwrap();
        let input = scratch.join("input.cddl");
        std::fs::write(
            &input,
            "my_ext = _CDDL_CODEGEN_EXTERN_TYPE_\nwrapper = [id: uint, ext: my_ext]\n",
        )
        .unwrap();
        let out = scratch.join("crate");
        let cli = crate::cli::Cli::parse_from([
            "cddl-codegen",
            "--input",
            input.to_str().unwrap(),
            "--output",
            out.to_str().unwrap(),
            "--wasm=true",
        ]);
        let rust_lib_rs = out.join("rust/src/lib.rs");
        let wasm_lib_rs = out.join("wasm/src/lib.rs");

        // First export seeds both thin roots; capture them to assert seed-once leaves them byte-identical.
        crate::api::generate_to_disk(&cli).unwrap();
        let rust_seeded = std::fs::read_to_string(&rust_lib_rs).unwrap();
        let wasm_seeded = std::fs::read_to_string(&wasm_lib_rs).unwrap();

        // Rust side (the wasm crate's path dep): the same WI-6 wiring — define + re-export the native
        // extern at the crate root so the bare `generated/**` references resolve.
        let rust_hand_wired = format!("{rust_seeded}\npub mod utils;\npub use utils::MyExt;\n");
        std::fs::write(&rust_lib_rs, &rust_hand_wired).unwrap();
        std::fs::write(
            out.join("rust/src/utils.rs"),
            "use crate::error::DeserializeError;\n\
             use crate::serialization::Deserialize;\n\
             \n\
             #[derive(Clone, Debug)]\n\
             pub struct MyExt(pub u64);\n\
             \n\
             impl cbor_event::se::Serialize for MyExt {\n\
             \x20   fn serialize<'se>(\n\
             \x20       &self,\n\
             \x20       serializer: &'se mut cbor_event::se::Serializer,\n\
             \x20   ) -> cbor_event::Result<&'se mut cbor_event::se::Serializer> {\n\
             \x20       serializer.write_unsigned_integer(self.0)\n\
             \x20   }\n\
             }\n\
             \n\
             impl Deserialize for MyExt {\n\
             \x20   fn deserialize(\n\
             \x20       raw: &mut cbor_event::de::Deserializer,\n\
             \x20   ) -> Result<Self, DeserializeError> {\n\
             \x20       Ok(Self(raw.unsigned_integer()?))\n\
             \x20   }\n\
             }\n",
        )
        .unwrap();

        // WASM side: define the `#[wasm_bindgen]` wrapper around the rust type (reached as `cddl_lib::MyExt`,
        // the rust crate's path-dep name) and re-export it at the wasm crate root. The generated wasm code
        // converts between wrapper and native via `From`, so supply both directions (+ `AsRef`, matching the
        // real consumer's wrapper shape).
        let wasm_hand_wired = format!("{wasm_seeded}\npub mod utils;\npub use utils::MyExt;\n");
        std::fs::write(&wasm_lib_rs, &wasm_hand_wired).unwrap();
        std::fs::write(
            out.join("wasm/src/utils.rs"),
            "use wasm_bindgen::prelude::wasm_bindgen;\n\
             \n\
             #[wasm_bindgen]\n\
             #[derive(Clone, Debug)]\n\
             pub struct MyExt(cddl_lib::MyExt);\n\
             \n\
             impl From<cddl_lib::MyExt> for MyExt {\n\
             \x20   fn from(native: cddl_lib::MyExt) -> Self {\n\
             \x20       Self(native)\n\
             \x20   }\n\
             }\n\
             \n\
             impl From<MyExt> for cddl_lib::MyExt {\n\
             \x20   fn from(wasm: MyExt) -> Self {\n\
             \x20       wasm.0\n\
             \x20   }\n\
             }\n\
             \n\
             impl AsRef<cddl_lib::MyExt> for MyExt {\n\
             \x20   fn as_ref(&self) -> &cddl_lib::MyExt {\n\
             \x20       &self.0\n\
             \x20   }\n\
             }\n",
        )
        .unwrap();

        // Regenerate over the same directory: seed-once must leave BOTH hand-wired thin roots byte-identical.
        crate::api::generate_to_disk(&cli).unwrap();
        assert_eq!(
            rust_hand_wired,
            std::fs::read_to_string(&rust_lib_rs).unwrap(),
            "[wasm] the hand-wired rust thin root must survive regeneration byte-for-byte"
        );
        assert_eq!(
            wasm_hand_wired,
            std::fs::read_to_string(&wasm_lib_rs).unwrap(),
            "[wasm] the hand-wired wasm thin root must survive regeneration byte-for-byte"
        );

        // The generator must emit the re-export glue into BOTH generated roots so the bare `MyExt`
        // references resolve to the user's definitions.
        let rust_generated_mod =
            std::fs::read_to_string(out.join("rust/src/generated/mod.rs")).unwrap();
        assert!(
            rust_generated_mod.contains("pub use crate::MyExt;"),
            "[wasm] rust generated/mod.rs must re-export the in-crate extern:\n{rust_generated_mod}"
        );
        let wasm_generated_mod =
            std::fs::read_to_string(out.join("wasm/src/generated/mod.rs")).unwrap();
        assert!(
            wasm_generated_mod.contains("pub use crate::MyExt;"),
            "[wasm] wasm generated/mod.rs must re-export the in-crate extern wrapper:\n{wasm_generated_mod}"
        );

        if tool_exists("cargo") {
            let target_dir = scratch.join("target");
            let build = tool_cmd("cargo")
                .arg("build")
                .current_dir(out.join("wasm"))
                .env("CARGO_TARGET_DIR", &target_dir)
                .output()
                .unwrap();
            assert!(
                build.status.success(),
                "[wasm] hand-wired in-crate extern WASM crate must compile\n{}\n{}",
                String::from_utf8_lossy(&build.stdout),
                String::from_utf8_lossy(&build.stderr)
            );
        }

        let _ = std::fs::remove_dir_all(&scratch);
    }

    run("default", &[]);
    run("preserve", &["--preserve-encodings=true"]);
    run_wasm();
}

/// Surfaces the own-spec extern re-export contract three ways so a stale hand-written thin root can't
/// leave a user staring at a bare E0432 (the generated glue's `pub use crate::<Name>;` resolves only
/// if the crate-root `lib.rs` re-exports `<Name>` from wherever the user defined it):
///   (1) run-output print — the required per-crate re-export list (rust and wasm) on stdout;
///   (2) contract comment — a `//` group above each generated scope's glue restating the contract;
///   (3) generation-time diagnostic — a stderr warning when a seed-once `lib.rs` ALREADY EXISTS and
///       lacks a required name, naming the missing idents and the exact fix.
///
/// The required sets are collected at EXACTLY the glue-emission sites (single source of truth), so
/// the surfaced list can never drift from the glue. This gate drives a real generator SUBPROCESS (the
/// only way to observe stdout/stderr) into a scratch dir repeatedly and pins every layer: the fresh seed is
/// SILENT (no diagnostic — the seed path never `exist`s), the stale seed WARNS, a satisfied root and
/// a foreign glob re-exporter are both silent, the diagnostic changes ZERO generated bytes
/// (run-twice-equals-run-once), and a `@raw_bytes_flavor` spec surfaces its `<Base>RawBytes` name.
/// `cargo`-guarded (the print/warning are only observable through the subprocess).
#[test]
fn extern_reexport_contract_surfaced() {
    if !tool_exists("cargo") {
        return;
    }

    // Every `.rs` under either crate's `generated/**`, rel-path -> bytes, for the byte-identity check.
    fn generated_snapshot(out: &std::path::Path) -> std::collections::BTreeMap<String, String> {
        let mut map = std::collections::BTreeMap::new();
        for sub in ["rust/src/generated", "wasm/src/generated"] {
            let base = out.join(sub);
            if !base.exists() {
                continue;
            }
            let mut stack = vec![base.clone()];
            while let Some(dir) = stack.pop() {
                for entry in std::fs::read_dir(&dir).unwrap() {
                    let path = entry.unwrap().path();
                    if path.is_dir() {
                        stack.push(path);
                    } else if path.extension().and_then(|e| e.to_str()) == Some("rs") {
                        let rel = path
                            .strip_prefix(out)
                            .unwrap()
                            .to_string_lossy()
                            .into_owned();
                        map.insert(rel, std::fs::read_to_string(&path).unwrap());
                    }
                }
            }
        }
        map
    }

    fn run_gen(input: &std::path::Path, out: &std::path::Path) -> (String, String) {
        let run = codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=true")
            .output()
            .unwrap();
        assert!(
            run.status.success(),
            "generation failed:\n{}",
            String::from_utf8_lossy(&run.stderr)
        );
        (
            String::from_utf8_lossy(&run.stdout).into_owned(),
            String::from_utf8_lossy(&run.stderr).into_owned(),
        )
    }

    let root = std::env::temp_dir().join(format!(
        "cddl_codegen_extern_contract_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();

    // --- Main flow: a plain in-crate extern used by a generated wrapper (rust + wasm glue). ---
    let input = root.join("input.cddl");
    std::fs::write(
        &input,
        "my_ext = _CDDL_CODEGEN_EXTERN_TYPE_\nwrapper = [id: uint, ext: my_ext]\n",
    )
    .unwrap();
    let out = root.join("crate");

    // (1) Fresh seed: the print names the required re-exports for BOTH crates; NO diagnostic fires
    // (the seed-once roots did not pre-exist, so the diagnostic branch is skipped entirely).
    let (stdout1, stderr1) = run_gen(&input, &out);
    assert!(
        stdout1.contains("the hand-written rust/src/lib.rs must re-export")
            && stdout1.contains("pub use <your_module>::MyExt;"),
        "run-output print must list the rust required re-exports:\n{stdout1}"
    );
    assert!(
        stdout1.contains("the hand-written wasm/src/lib.rs must re-export"),
        "run-output print must list the wasm required re-exports:\n{stdout1}"
    );
    assert!(
        !stderr1.contains("is missing crate-root re-exports"),
        "a fresh seed must NOT emit the missing-re-export diagnostic:\n{stderr1}"
    );

    // (2) The contract comment sits above the glue in each generated scope mod.rs.
    for crate_mod in ["rust/src/generated/mod.rs", "wasm/src/generated/mod.rs"] {
        let text = std::fs::read_to_string(out.join(crate_mod)).unwrap();
        assert!(
            text.contains("cddl-codegen extern re-export contract:")
                && text.contains("pub use crate::MyExt;"),
            "{crate_mod} must carry the contract comment above the glue:\n{text}"
        );
    }

    let generated_after_seed = generated_snapshot(&out);

    // (3a) Second run over the still-stale seeded roots (they carry `pub use generated::*;` — the
    // tool's OWN glob, which must NOT suppress — but not `MyExt`): the diagnostic fires for BOTH
    // crates, naming the missing ident and the fix.
    let (_stdout2, stderr2) = run_gen(&input, &out);
    assert!(
        stderr2.contains("rust/src/lib.rs is missing crate-root re-exports")
            && stderr2.contains("MyExt")
            && stderr2.contains("pub use <your_module>::<Name>;"),
        "a stale rust seed missing a required re-export must warn with the fix:\n{stderr2}"
    );
    assert!(
        stderr2.contains("wasm/src/lib.rs is missing crate-root re-exports"),
        "a stale wasm seed missing a required re-export must warn:\n{stderr2}"
    );

    // The diagnostic reads prior output but writes ZERO bytes: generated/** is byte-identical.
    assert_eq!(
        generated_after_seed,
        generated_snapshot(&out),
        "the missing-re-export diagnostic must not change any generated byte (run-twice=run-once)"
    );

    // (3b) Satisfy the contract on both roots: the diagnostic goes silent.
    for lib in ["rust/src/lib.rs", "wasm/src/lib.rs"] {
        std::fs::write(
            out.join(lib),
            "mod generated;\npub use generated::*;\npub mod utils;\npub use utils::MyExt;\n",
        )
        .unwrap();
    }
    let (_stdout3, stderr3) = run_gen(&input, &out);
    assert!(
        !stderr3.contains("is missing crate-root re-exports"),
        "a satisfied root must not warn:\n{stderr3}"
    );

    // (3c) A foreign glob re-exporter (`pub use utils::*;`, path last-segment != `generated`) the
    // name scan can't see through: suppress the per-name warning rather than false-positive.
    std::fs::write(
        out.join("rust/src/lib.rs"),
        "mod generated;\npub use generated::*;\npub mod utils;\npub use utils::*;\n",
    )
    .unwrap();
    let (_stdout4, stderr4) = run_gen(&input, &out);
    assert!(
        !stderr4.contains("rust/src/lib.rs is missing crate-root re-exports"),
        "a non-generated glob re-exporter must suppress the rust per-name warning:\n{stderr4}"
    );

    // --- Raw-bytes-flavor coverage: the `<Base>RawBytes` flavor name surfaces in the print. ---
    let rb_input = root.join("rawbytes.cddl");
    std::fs::write(
        &rb_input,
        "pub_key = _CDDL_CODEGEN_RAW_BYTES_TYPE_\n\
         ext_set<T> = _CDDL_CODEGEN_EXTERN_TYPE_ ; @raw_bytes_flavor\n\
         plain = [a: uint, b: text]\n\
         using = [keys: ext_set<pub_key>, plains: ext_set<plain>]\n",
    )
    .unwrap();
    let rb_out = root.join("rb_crate");
    let (rb_stdout, _rb_stderr) = run_gen(&rb_input, &rb_out);
    assert!(
        rb_stdout.contains("pub use <your_module>::ExtSetRawBytes;"),
        "the @raw_bytes_flavor <Base>RawBytes flavor name must surface in the print:\n{rb_stdout}"
    );

    let _ = std::fs::remove_dir_all(&root);
}

/// Layer-3 refinement of the extern re-export diagnostic (`extern_reexport_contract_surfaced` pins
/// the three layers; this pins the opt-out): a required re-export name must NOT be nagged as
/// "missing from the seed-once lib.rs" when the user deliberately deleted its glue line
/// (`pub use crate::<Name>;`) via a `cddl-codegen:replace` block. The generator's own contract no
/// longer requires that re-export once the glue is gone from this run's WRITTEN output, so the
/// warning would be a recurring false nag on every regen. The decision reads the post-overlay
/// written bytes (not `comment_preserve` internals), so this also pins the whole chain — the overlay
/// really deletes the glue AND the warning subtracts the deleted name — while the second extern's
/// surviving glue still warns. `cargo`-guarded (the warning is only observable through the
/// subprocess) and driven over a real regen so the comment-preservation overlay actually runs.
#[test]
fn extern_reexport_diagnostic_skips_replace_deleted_glue() {
    if !tool_exists("cargo") {
        return;
    }

    fn run_gen(input: &std::path::Path, out: &std::path::Path) -> String {
        let run = codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=true")
            .output()
            .unwrap();
        assert!(
            run.status.success(),
            "generation failed:\n{}",
            String::from_utf8_lossy(&run.stderr)
        );
        String::from_utf8_lossy(&run.stderr).into_owned()
    }

    // Wrap a whole-line `use` item in a delete-only replace block: empty user section (nothing
    // between `replace-start` and `replaces`), and the recorded original is the `//`-commented line
    // — the anchor the overlay re-finds in the regenerated item and splices the (empty) user section
    // over, deleting the glue from this run's written output.
    fn delete_glue_via_replace_block(mod_path: &std::path::Path, glue_line: &str) {
        let text = std::fs::read_to_string(mod_path).unwrap();
        assert!(
            text.contains(glue_line),
            "expected glue `{glue_line}` in {}:\n{text}",
            mod_path.display()
        );
        let block = format!(
            "// cddl-codegen:replace-start\n\
             // cddl-codegen:replaces\n\
             // {glue_line}\n\
             // cddl-codegen:replace-end"
        );
        let edited = text.replacen(glue_line, &block, 1);
        std::fs::write(mod_path, edited).unwrap();
    }

    let root = std::env::temp_dir().join(format!(
        "cddl_codegen_extern_replace_optout_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();

    // Two plain in-crate externs used by one generated wrapper: required rust+wasm re-export set
    // {FirstExt, SecondExt}. `FirstExt` sorts before `SecondExt`, and neither is a substring of the
    // other, so the stderr assertions can distinguish them by whole-name substring.
    let input = root.join("input.cddl");
    std::fs::write(
        &input,
        "first_ext = _CDDL_CODEGEN_EXTERN_TYPE_\n\
         second_ext = _CDDL_CODEGEN_EXTERN_TYPE_\n\
         wrapper = [id: uint, a: first_ext, b: second_ext]\n",
    )
    .unwrap();
    let out = root.join("crate");

    // Seed run: writes the seed-once roots (the default thin roots re-export neither extern) and the
    // generated scope mod.rs files carrying both glue lines for each crate.
    let _ = run_gen(&input, &out);
    let rust_mod = out.join("rust/src/generated/mod.rs");
    let wasm_mod = out.join("wasm/src/generated/mod.rs");

    // User deletes ONLY FirstExt's glue in BOTH crates via a replace block; SecondExt's glue stays.
    for mod_path in [&rust_mod, &wasm_mod] {
        delete_glue_via_replace_block(mod_path, "pub use crate::FirstExt;");
    }

    // Regen over the edited prior output: the overlay splices the empty user section over the
    // recorded FirstExt line, deleting it; SecondExt survives.
    let stderr = run_gen(&input, &out);

    // Chain half 1: the overlay actually removed FirstExt's LIVE glue and kept SecondExt's in the
    // written output — so the survival scan is reading a real deletion, not a no-op. A replace
    // deletion leaves the recorded original behind as a `// pub use crate::FirstExt;` comment, so
    // this must be a whole-trimmed-line check, not a substring `contains` (which the comment matches).
    for (label, mod_path) in [("rust", &rust_mod), ("wasm", &wasm_mod)] {
        let written = std::fs::read_to_string(mod_path).unwrap();
        let live_lines: std::collections::BTreeSet<String> =
            written.lines().map(|l| l.trim().to_owned()).collect();
        assert!(
            !live_lines.contains("pub use crate::FirstExt;"),
            "{label} generated mod.rs must have the replace-deleted FirstExt LIVE glue removed:\n{written}"
        );
        assert!(
            live_lines.contains("pub use crate::SecondExt;"),
            "{label} generated mod.rs must still carry the surviving SecondExt glue:\n{written}"
        );
    }

    // Chain half 2: the diagnostic warns for the SURVIVING name (SecondExt, absent from the seed
    // roots) but is SILENT for the replace-deleted name (FirstExt) in either crate.
    for lib in ["rust/src/lib.rs", "wasm/src/lib.rs"] {
        assert!(
            stderr.contains(&format!("{lib} is missing crate-root re-exports"))
                && stderr.contains("SecondExt"),
            "{lib} must still warn for the surviving SecondExt re-export:\n{stderr}"
        );
    }
    assert!(
        !stderr.contains("FirstExt"),
        "the diagnostic must NOT nag for a name whose glue a replace block deleted:\n{stderr}"
    );

    let _ = std::fs::remove_dir_all(&root);
}

/// Compile-level pin for the documented per-scope FACADE COMPOSITION
/// (docs/docs/output_format.mdx § "Per-scope hand modules: the facade pattern", plus the preceding
/// extern-glue section and the following "Generated wrapper fields are pub(crate)" section). The
/// composition's ingredients are already string-pinned separately —
/// `integration_extern_only_scope_declared_in_root` (the extern-only scope gets a generated `pub mod`
/// in the root) and `integration_wrapper_fields_are_pub_crate` (the wrapper's backing field is
/// `pub(crate)`) — but no string pin can catch a COMPOSITION regression, where the pieces are each
/// individually correct yet no longer compose: generated code beginning to reference a public
/// `crate::<scope>::…` path (which the facade shadows and would silently rebind), a scope module
/// losing its `pub mod` in the generated root, or the root `pub use generated::*;` glob disappearing.
/// Only actually BUILDING the documented consumer composition catches those.
///
/// So this gate generates the committed two-scope fixture in `tests/facade/input` (`assets`: a
/// bounded-bytes newtype carrying the `pub(crate) inner` field; `address`: an extern-ONLY scope,
/// which also compiles the e07c3a0 extern-only-scope module-declaration contract end to end),
/// overlays the committed hand files from `tests/facade/hand/` (a facade `lib.rs`, a per-scope
/// `assets/utils.rs` whose `_assert_paths` fn pins every public path the facade promises, and the
/// `addr_impl.rs` extern definition), and `cargo check`s the result. `cargo`-guarded so the
/// string-level self-diagnosing assertions still run on a toolchain-less box. Shared
/// `CARGO_TARGET_DIR` under `temp_dir()` keyed by `checkout_hash()`, like the sibling generate+check
/// gates. Generation is in-process (`generate_to_disk`) rather than a spawned generator — the same
/// code path, cheaper, and matching `thin_root_in_crate_extern_type_compiles`.
#[test]
fn facade_composition_compiles() {
    use clap::Parser;

    // Committed fixture (input + hand overlay) and the gitignored `tests/*/export*` output dir,
    // relative to the repo root (the cwd during `cargo test`, like the multifile-matrix gate).
    let input = "tests/facade/input";
    let out = std::path::PathBuf::from("tests/facade/export");
    let hand = std::path::PathBuf::from("tests/facade/hand");

    let _ = std::fs::remove_dir_all(&out);
    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input",
        input,
        "--output",
        out.to_str().unwrap(),
        "--preserve-encodings=true",
        "--wasm=false",
    ]);
    crate::api::generate_to_disk(&cli).unwrap_or_else(|e| panic!("generation failed: {e}"));

    // Self-diagnosing string checks BEFORE the compile so a broken ingredient names itself rather
    // than surfacing as an opaque rustc failure downstream.
    let root_mod = std::fs::read_to_string(out.join("rust/src/generated/mod.rs")).unwrap();
    for decl in ["pub mod assets;", "pub mod address;"] {
        assert!(
            root_mod.lines().any(|l| l.trim() == decl),
            "generated root mod.rs must declare `{decl}` (the facade shadows the glob re-export of \
             this scope):\n{root_mod}"
        );
    }
    let addr_mod = std::fs::read_to_string(out.join("rust/src/generated/address/mod.rs")).unwrap();
    assert!(
        addr_mod.contains("pub use crate::Address;"),
        "extern-only `address` scope's generated mod.rs must emit the re-export glue \
         `pub use crate::Address;`:\n{addr_mod}"
    );

    // Overlay the documented consumer composition: the facade thin root, the per-scope hand module
    // at `src/assets/utils.rs`, and the extern definition at `src/addr_impl.rs`.
    std::fs::copy(hand.join("lib.rs"), out.join("rust/src/lib.rs")).unwrap();
    std::fs::create_dir_all(out.join("rust/src/assets")).unwrap();
    std::fs::copy(
        hand.join("assets_utils.rs"),
        out.join("rust/src/assets/utils.rs"),
    )
    .unwrap();
    std::fs::copy(hand.join("addr_impl.rs"), out.join("rust/src/addr_impl.rs")).unwrap();

    if tool_exists("cargo") {
        let target_dir =
            std::env::temp_dir().join(format!("cddl_codegen_facade_{:016x}", checkout_hash()));
        let check = tool_cmd("cargo")
            .arg("check")
            .current_dir(out.join("rust"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .output()
            .unwrap();
        assert!(
            check.status.success(),
            "the documented per-scope facade composition must compile\n{}\n{}",
            String::from_utf8_lossy(&check.stdout),
            String::from_utf8_lossy(&check.stderr)
        );
    }
}

/// The documented migration trap for pre-split consumers must fail LOUD, not silent. A consumer whose
/// `lib.rs` predates the thin-root split still carries `pub mod serialization;` (and inline generated
/// type defs) pointing at siblings the split relocated under `src/generated/**`. Seed-once leaves that
/// stale root untouched (the tool doesn't read it to decide what to emit — regeneration still
/// succeeds), so the breakage surfaces at COMPILE time as a diagnosable error, exactly as the design
/// doc requires. We pin the stable `E0583` module-resolution failure (the relocated `serialization`
/// module is now unresolved from the root) so a future silent-clobber regression can't pass this gate.
#[test]
fn migration_legacy_root_fails_loudly() {
    use clap::Parser;
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_migration_loud_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    std::fs::write(&input, "foo = [x: uint]\n").unwrap();
    let out = scratch.join("crate");
    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input",
        input.to_str().unwrap(),
        "--output",
        out.to_str().unwrap(),
        "--wasm=false",
    ]);
    let lib_rs = out.join("rust/src/lib.rs");

    crate::api::generate_to_disk(&cli).unwrap();

    // Overwrite the seeded root with a faithful pre-split monolith: crate attrs, a `pub mod
    // serialization;` decl (whose file the split moved under `generated/`), and an inline copy of the
    // generated `Foo` — the shape a legacy consumer carries. Crucially, no `mod generated;`.
    std::fs::write(
        &lib_rs,
        "// legacy pre-split monolithic root\n#![allow(clippy::too_many_arguments)]\npub mod serialization;\n\n#[derive(Clone, Debug)]\npub struct Foo {\n    pub x: u64,\n}\n",
    )
    .unwrap();

    // Re-export must SUCCEED — the tool never reads the root to decide what to emit; it seed-once
    // skips it and regenerates the subtree beside it.
    crate::api::generate_to_disk(&cli).expect("regeneration over a legacy root must still succeed");

    if tool_exists("cargo") {
        let target_dir = scratch.join("target");
        let build = tool_cmd("cargo")
            .arg("build")
            .current_dir(out.join("rust"))
            .env("CARGO_TARGET_DIR", &target_dir)
            .output()
            .unwrap();
        assert!(
            !build.status.success(),
            "a legacy pre-split root must NOT silently compile after regeneration"
        );
        let stderr = String::from_utf8_lossy(&build.stderr);
        assert!(
            stderr.contains("E0583"),
            "the legacy-root breakage must be the diagnosable module-resolution failure (E0583: the \
             relocated `serialization` module is unresolved from the root), got:\n{stderr}"
        );
    }

    let _ = std::fs::remove_dir_all(&scratch);
}

/// The legacy-shape stderr warning (diagnostics only — output bytes are unchanged): when a crate-root
/// `lib.rs` already exists and does NOT declare `mod generated`, `export()` prints a one-time-migration
/// warning naming the remedy; a thin root (which does declare it) draws no warning. Captured via a real
/// CLI subprocess because the warning is an `eprintln!` on the tool's process stderr.
#[test]
fn legacy_root_warning_fires_only_for_legacy_shape() {
    if !tool_exists("cargo") {
        return;
    }
    let scratch =
        std::env::temp_dir().join(format!("cddl_codegen_legacy_warn_{:016x}", checkout_hash()));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    std::fs::write(&input, "foo = [x: uint]\n").unwrap();
    let out = scratch.join("crate");
    let lib_rs = out.join("rust/src/lib.rs");

    let run = || {
        codegen_cmd()
            .arg(format!("--input={}", input.to_str().unwrap()))
            .arg(format!("--output={}", out.to_str().unwrap()))
            .arg("--wasm=false")
            .output()
            .unwrap()
    };

    // First run seeds a thin root; a second run over it must NOT warn (the root declares `mod
    // generated`).
    let first = run();
    assert!(first.status.success());
    let thin = run();
    assert!(thin.status.success());
    let thin_stderr = String::from_utf8_lossy(&thin.stderr);
    assert!(
        !thin_stderr.contains("predates the thin-root layout"),
        "a thin root (with `mod generated`) must NOT draw the legacy-shape warning, got:\n{thin_stderr}"
    );

    // Now overwrite with a legacy-shaped root (no `mod generated`) and re-run: the warning must fire
    // and name the remedy.
    std::fs::write(
        &lib_rs,
        "// legacy pre-split monolithic root\npub mod serialization;\npub struct Foo;\n",
    )
    .unwrap();
    let legacy = run();
    assert!(
        legacy.status.success(),
        "regeneration over a legacy root still succeeds (warning is diagnostic only)"
    );
    let legacy_stderr = String::from_utf8_lossy(&legacy.stderr);
    assert!(
        legacy_stderr.contains("predates the thin-root layout")
            && legacy_stderr.contains("mod generated;"),
        "a legacy-shaped root must draw the one-time-migration warning naming the remedy, got:\n{legacy_stderr}"
    );
    // Diagnostics only: the legacy root is left byte-for-byte untouched (seed-once still skips it).
    assert_eq!(
        std::fs::read_to_string(&lib_rs).unwrap(),
        "// legacy pre-split monolithic root\npub mod serialization;\npub struct Foo;\n",
        "the legacy root must be left untouched — the warning changes no output bytes"
    );

    let _ = std::fs::remove_dir_all(&scratch);
}

/// A regeneration over an UNPARSEABLE existing manifest must be a hard error that names the file —
/// never a silent clobber (a parse failure is exactly when the user has content we can't preserve).
#[test]
fn cargo_manifest_rejects_unparseable_existing() {
    use clap::Parser;
    let scratch = std::env::temp_dir().join(format!(
        "cddl_codegen_manifest_badtoml_{:016x}",
        checkout_hash()
    ));
    let _ = std::fs::remove_dir_all(&scratch);
    std::fs::create_dir_all(&scratch).unwrap();
    let input = scratch.join("input.cddl");
    std::fs::write(&input, "foo = [x: uint]\n").unwrap();
    let out = scratch.join("crate");
    let cli = crate::cli::Cli::parse_from([
        "cddl-codegen",
        "--input",
        input.to_str().unwrap(),
        "--output",
        out.to_str().unwrap(),
        "--wasm=false",
    ]);

    crate::api::generate_to_disk(&cli).unwrap();
    let manifest = out.join("rust/Cargo.toml");
    let garbage = "this is [[[ not valid toml";
    std::fs::write(&manifest, garbage).unwrap();

    let err = crate::api::generate_to_disk(&cli)
        .expect_err("regeneration over unparseable manifest must error");
    let msg = err.to_string();
    assert!(
        msg.contains("rust/Cargo.toml"),
        "error must name the offending manifest, got: {msg}"
    );
    // the corrupt content is left untouched (not clobbered)
    assert_eq!(std::fs::read_to_string(&manifest).unwrap(), garbage);

    let _ = std::fs::remove_dir_all(&scratch);
}

/// Compile gate for `--wasm-cbor-json-api-macro` — the third external-macro flag and, unlike its two
/// snapshot+compile-gated siblings (`wasm_list_macro_compiles`), previously had zero coverage
/// anywhere (it is the documented CML invocation path). The flag replaces each wasm wrapper's inline
/// CBOR/JSON API with a `cbor_json_api!(WasmName);` invocation referencing a user-supplied macro, so
/// it can't compile standalone. Wire in `tests/wasm-macro-crate`'s real `cbor_json_api!` definition
/// (whose bodies mirror the inline emission, so a divergent invocation fails to compile) and
/// `cargo check` the generated wasm crate — same pattern as `wasm_list_macro_compiles`.
/// `--emit-tests-conformance` without `--emit-tests` must be rejected up front (there is no
/// generated-test module to add the conformance calls to). Pins the rejection *and* its message so
/// the guard can't silently become a no-op, and confirms the same flags together are accepted — so
/// the rejection is specific to the missing `--emit-tests`. Mirrors
/// `flag_value_rejects_canonical_without_preserve`.
#[test]
fn flag_rejects_conformance_without_emit_tests() {
    let mut cli = crate::cli::Cli {
        input: std::path::PathBuf::from("tests/corpus/exclusive_range.cddl"),
        output: std::path::PathBuf::from("unused"),
        emit_tests_conformance: true,
        emit_tests: false,
        ..Default::default()
    };
    let err = crate::api::with_types(&cli, |_, _| ())
        .expect_err("--emit-tests-conformance without --emit-tests should be rejected");
    let msg = err.to_string();
    assert!(
        msg.contains("--emit-tests-conformance") && msg.contains("--emit-tests=true"),
        "rejection message should name both flags, got: {msg}"
    );
    cli.emit_tests = true;
    assert!(
        crate::api::with_types(&cli, |_, _| ()).is_ok(),
        "--emit-tests-conformance with --emit-tests should be accepted"
    );
}

#[test]
fn wasm_cbor_json_api_macro_compiles() {
    use std::str::FromStr;
    let test_path = std::path::PathBuf::from_str("tests/canonical").unwrap();
    let out = test_path.join("export_cbor_json_api_macro");
    let _ = std::fs::remove_dir_all(&out);
    let gen_out = codegen_cmd()
        .arg(format!(
            "--input={}",
            test_path.join("input.cddl").to_str().unwrap()
        ))
        .arg(format!("--output={}", out.to_str().unwrap()))
        .arg("--wasm=true")
        .arg("--wasm-cbor-json-api-macro=wasm_macro_crate::cbor_json_api")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "generation failed\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );
    // vacuous-pass guard: only gates the macro path if the flag actually collapsed the inline API
    // into invocations (11 at landing over tests/canonical).
    let lib = std::fs::read_to_string(out.join("wasm/src/generated/mod.rs")).unwrap();
    let n_invocations = lib.matches("cbor_json_api!(").count();
    assert!(
        n_invocations >= 8,
        "only {n_invocations} cbor_json_api! invocations emitted (expected >= 8) — the flag stopped \
         collapsing the inline API, so this gate no longer gates the macro path"
    );
    let mut cargo_toml = std::fs::OpenOptions::new()
        .append(true)
        .open(out.join("wasm/Cargo.toml"))
        .unwrap();
    cargo_toml
        .write_all(b"wasm-macro-crate = { path = \"../../../wasm-macro-crate\" }\n")
        .unwrap();
    std::mem::drop(cargo_toml);
    let target_dir = std::env::temp_dir().join(format!(
        "cddl_codegen_wasm_cbor_json_api_macro_{:016x}",
        checkout_hash()
    ));
    let check = tool_cmd("cargo")
        .arg("check")
        .current_dir(out.join("wasm"))
        .env("CARGO_TARGET_DIR", &target_dir)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "cargo check failed\n{}",
        String::from_utf8_lossy(&check.stderr)
    );
}

// ---------------------------------------------------------------------------
// wasm three-state read fidelity (`tests/nullable-wasm/`).
//
// wasm-bindgen can't represent a nested `Option<Option<T>>`, so a nullable value (`T / null` ->
// `Option<T>`) sitting where the accessor adds its own presence-`Option` is FLATTENED to a single
// `Option<T>` on read: the plain getter reports `None` for BOTH an absent slot and a present-but-null
// one. Three-state fidelity is restored ADDITIVELY (no existing getter signature changes) by presence
// accessors emitted from exactly the flatten condition: `has_<field>()` beside an optional-nullable
// struct field getter, and `has(key)` on a nullable-value map wrapper. The single-nested enum
// variant needs no new accessor — `kind()` + `as_variant()` is already unambiguous. A DOUBLE-nested
// enum variant (payload resolving to `Option<Option<T>>`) is unreachable: the wasm enum constructor
// panics on such a variant before any getter is emitted, so `add_wasm_enum_getters` fails loud
// (`unreachable!`) instead of silently skipping. The behavioural oracle is the fixture's
// `tests_wasm.rs`, which constructs all three states through the rust API and asserts pairwise-distinct
// observations through the wasm accessors; read protocols live in docs/docs/wasm_differences.mdx.
#[test]
fn nullable_wasm() {
    run_test("nullable-wasm", &[], None, &[], &[], false, &[]);
}

// ---------------------------------------------------------------------------
// Tracked SILENT-WRONG-OUTPUT gaps (compile-green, snapshot-blessed, behaviorally wrong).
//
// These three corpus constructs generate code whose behavior contradicts the CDDL spec, and no
// automated oracle observes it: the corpus's only verdicts are "snapshot unchanged" + "it
// compiles" (`feature_corpus_compiles`), both of which the wrong code passes. Each is ledgered in
// cddl-matrix/ROADMAP.md ("Bugs / gaps surfaced as findings") and flagged ⚠️ in
// tests/corpus/COVERAGE.md, but a hand-authored overlay note can't fail a build — these stubs make
// the gaps visible in the suite itself, per the same convention as the wasm-fidelity pair above.
// Remove #[ignore] and write the real behavioral assertion when the generator is fixed (or when
// the emitted round-trip harness grows to cover the construct).

/// `a...b` must EXCLUDE b (max valid = b-1). `[v: 0...10]` must emit `max: Some(9)` — NOT the old
/// `max: Some(11)` (which accepted the out-of-spec 10 and 11). Asserts on the COMMITTED snapshot so a
/// regression can't slip back in via an unreviewed re-bless, mirroring `corpus_inline_group_members_kept`.
/// The behavioral half (9 round-trips, 10/11 rejected) is owned by the `--emit-tests` reject cases and
/// the `ir_conformance_corpus` oracle.
#[test]
fn corpus_exclusive_range_upper_bound() {
    let lib = std::fs::read_to_string(
        "tests/corpus/snapshots/exclusive_range/default__rust__src__generated__mod.rs.snap",
    )
    .expect("exclusive_range lib snapshot missing");
    assert!(
        lib.contains("max: Some(9)") && lib.contains("if v > 9"),
        "exclusive_range no longer emits the exclusive upper bound 9 — the a...b (max=b-1) bound is wrong"
    );
    assert!(
        !lib.contains("Some(11)") && !lib.contains("> 11"),
        "exclusive_range emits the old inclusive-off-by-one bound 11 — a...b must EXCLUDE b (max=b-1)"
    );
}

/// Occurrence counts (`+`, `n*m`) are LENGTH constraints on the array: embed sites must enforce
/// them on the array's length (deserialize + fallible constructor) and must never misread them
/// as element VALUE bounds (`[+ uint]` once rejected the element value 0 and `[2*5 uint]`
/// rejected element values outside 2..=5, while any length passed — parsing hung the bounds on
/// the element type instead of the array). This asserts on the COMMITTED occurrence snapshots so
/// neither regression can come back via an unreviewed re-bless; the *executed* proof is the
/// fixture's emit-tests run in `feature_corpus_compiles` (its deser-reject cases push each
/// field's length out of bounds — mutation-verified red when the emitted length check is
/// removed).
#[test]
fn corpus_occurrence_bounds_enforced() {
    let ser = std::fs::read_to_string(
        "tests/corpus/snapshots/occurrence/default__rust__src__generated__serialization.rs.snap",
    )
    .expect("occurrence serialization snapshot missing");
    // `2*5` and `1*3` keep the runtime occurrence-count length checks byte-for-byte (only the exact
    // `+` shape changes representation — WI-1 of two-type-constraint-enforcement).
    for check in [
        "if b_arr.len() < 2 || b_arr.len() > 5 {",
        "if inline_bounded_arr.len() < 1 || inline_bounded_arr.len() > 3 {",
    ] {
        assert!(
            ser.contains(check),
            "occurrence snapshot lost the occurrence-count length check `{check}`"
        );
    }
    // the `+` (`[+ uint]`) shape is now type-enforced: its length check is GONE from the ctor/deser,
    // replaced by the single `NonEmptyVec::try_from` door (identical RangeCheck error). The old
    // inline `if o_arr.len() < 1` runtime check must NOT come back.
    assert!(
        !ser.contains("if o_arr.len() < 1 {"),
        "occurrence `[+ uint]` reverted to an inline length check — it must enforce via NonEmptyVec"
    );
    assert!(
        ser.contains("NonEmptyVec::try_from(o_arr)?"),
        "occurrence `[+ uint]` deserialize must route the collected Vec through NonEmptyVec::try_from"
    );
    // the value-misread form bound each ELEMENT read through `.and_then(|x| if x < ... )` —
    // occurrence bounds must never re-attach to element values
    assert!(
        !ser.contains("found: x as i128"),
        "occurrence snapshot has an element VALUE RangeCheck — occurrence counts are being \
         misread as element value bounds again"
    );
}

/// The named/inline `[+ elem]` wasm-surface contract (two-type design doc, dedup + collision
/// decisions), asserted on the COMMITTED core whole-program wasm snapshot so none of it can
/// regress via an unreviewed re-bless; the *executed* proof is `tests/core/tests_wasm.rs`'s
/// `wasm_non_empty_named_free_selfnamed_and_dedup` in `core_with_wasm`:
/// - an inline `[+ nev_pt]` DEDUPS to the named `nev_pts = [+ nev_pt]` rule's class — no
///   synthesized `NonEmptyNevPtList` may exist, and member surfaces use the named class;
/// - the free-named rule's `try_from` borrows the loose `NevPtList` builder (minted for it);
/// - a SELF-NAMED rule (`nev_q_list = [+ nev_q]`, rule ident == loose-builder name) emits its
///   restricted class WITHOUT `try_from` — the self-referential `try_from(list: &NevQList)`
///   form was the miscompile (the restricted class fed to itself as the loose source, E0277).
#[test]
fn core_non_empty_dedup_and_self_named_wasm_surface() {
    let wasm = std::fs::read_to_string(
        "tests/corpus/snapshots/core/default__wasm__src__generated__mod.rs.snap",
    )
    .expect("core wasm snapshot missing");
    assert!(
        !wasm.contains("NonEmptyNevPtList"),
        "inline `[+ nev_pt]` must dedup to the named NevPts class, not mint NonEmptyNevPtList"
    );
    assert!(
        wasm.contains("pub fn pts_inline(&self) -> NevPts"),
        "the deduped inline field's getter must return the NAMED class NevPts"
    );
    assert!(
        wasm.contains("pub fn try_from(list: &NevPtList) -> Result<NevPts, JsError>"),
        "the free-named rule's try_from must borrow the loose NevPtList builder"
    );
    assert!(
        !wasm.contains("try_from(list: &NevQList)"),
        "self-named `[+ …]` rule emitted a self-referential try_from — the restricted class fed \
         to itself as the loose source (the E0277 miscompile class)"
    );
}

/// Special-class (major-type-7) map KEYS must deserialize through the map loop, not be
/// intercepted as a potential break byte — in EITHER framing. The definite-length loop reads
/// exactly `n` entries (`make_deser_loop_break_check` gates its Special check on the INDEFINITE
/// case only), and the indefinite loop uses the non-consuming `special_break()` probe, so a bool
/// key is left in place and flows straight to `bool::deserialize`. This asserts on the COMMITTED
/// special_map_key snapshots so the interception can't come back via an unreviewed re-bless; the
/// *executed* proof is the fixture's emit-tests round-trip in `feature_corpus_compiles` (it mints
/// a real `(false, 0)` entry — mutation-verified: an unconditional break check fails it with
/// EndingBreakMissing at BkeyHolder.named) plus the golden_hex_preserve indefinite-bool KATs.
#[test]
fn corpus_special_map_key_supported() {
    let ser = std::fs::read_to_string(
        "tests/corpus/snapshots/special_map_key/default__rust__src__generated__serialization.rs.snap",
    )
    .expect("special_map_key serialization snapshot missing");
    assert!(
        ser.contains("bool::deserialize(raw)?"),
        "special_map_key snapshot no longer deserializes the bool key through the element path"
    );
    // every Special peek in the map loops must be gated on the indefinite case — an ungated
    // `raw.cbor_type()? == cbor_event::Type::Special` check would eat definite-length bool keys.
    // The RHS counts the gate by its indefinite PATTERN (always on one line with its comma —
    // rustfmt wraps the `&&` chain, never the `matches!` args), not by a bare `if matches!(`,
    // so an unrelated future matches-gate can't pad the count.
    assert_eq!(
        ser.matches("raw.cbor_type()? == cbor_event::Type::Special")
            .count(),
        ser.matches(", cbor_event::Len::Indefinite)").count(),
        "special_map_key snapshot has a Special-class peek not gated on an indefinite length — \
         the break-interception bug on definite-length special keys is back"
    );
}

/// A native float under `--preserve-encodings` carries its CBOR head WIDTH (`0xf9`/`0xfa`/`0xfb`,
/// RFC 8949 §3.3) as an encoding variable, exactly as an integer carries its argument width. The
/// three properties that makes concrete, asserted here on the COMMITTED preserve snapshots so none
/// can be silently dropped by an unreviewed re-bless:
///   * the width has a HOME — an `Option<cbor_event::Sz>` encoding field per float member;
///   * decode CAPTURES it — `float_sz()` (the `(f64, Sz)` reader), never the width-discarding
///     `float()`, which is what the default profile keeps using;
///   * encode CONSULTS it — through the `write_float` runtime helper, which is also the single place
///     that widens a recorded width the held value has outgrown (rather than erroring
///     `InvalidLenPassed`) and that normalizes a NaN payload away under `--canonical-form`
///     (RFC 8949 §4.2.2).
///
/// A snapshot assertion cannot see whether those bytes are RIGHT, so the executed proofs live
/// elsewhere: the `golden_hex_preserve` / `golden_hex_canonical` KAT suites (hand-derived RFC 8949
/// Appendix A vectors at all three widths, including the canonical-NaN rule), this fixture's own
/// emit-tests round-trip under `feature_corpus_compiles` — whose `widen_float` encoding-fidelity
/// mutation class now reaches native float heads, not just `AnyCbor`'s — and the float rows of
/// `decode_conformance_replay` / `corpus_decode_replay`, which replay under preserve rather than
/// sitting in a `PRESERVE_SKIP` ledger.
#[test]
fn preserve_encodings_supports_floats() {
    let snap = |file: &str| {
        std::fs::read_to_string(format!(
            "tests/corpus/snapshots/optional_fixed_float/preserve__rust__src__generated__{file}.snap"
        ))
        .unwrap_or_else(|_| {
            panic!(
                "optional_fixed_float has no preserve {file} snapshot — floats abort generation \
                 under --preserve-encodings again"
            )
        })
    };
    let encs = snap("cbor_encodings.rs");
    assert!(
        encs.contains("pub f_encoding: Option<cbor_event::Sz>"),
        "the fixed-float member has no width encoding field — a float's head width has nowhere to live"
    );
    let ser = snap("serialization.rs");
    assert!(
        ser.contains("let (f_value, f_encoding) = raw.float_sz()?;"),
        "the preserve deserializer no longer reads the float through `float_sz()` — the head width \
         is being discarded at decode, so an f16 input would re-encode as an f64"
    );
    // The runtime helper's own DEFINITION is concatenated into this file, so count CALLS as the
    // excess over definitions rather than matching a bare name (and rather than matching an
    // indentation-dependent literal, which the emitted call's nesting depth would break).
    assert!(
        ser.matches("write_float(").count() > ser.matches("pub fn write_float(").count(),
        "the preserve serializer no longer writes the float through `write_float` — the recorded \
         width, its outgrown-value widening, and the canonical NaN rule all live there"
    );
}

/// `[(uint, tstr)]` must keep BOTH spliced members. This regressed member-dropping data loss for
/// years (a 1-field `InlineGroup { index_0 }` / `read_elems(1)` that parsed, compiled, and
/// round-tripped green) until the cddl-fork AST bump (c505d38) fixed the group's shape. The corpus
/// snapshots pin the fixed form; this asserts on the COMMITTED snapshots so a regression can't
/// slip back in via an unreviewed re-bless (the snapshot suite alone would happily pin the
/// 1-field form again).
#[test]
fn corpus_inline_group_members_kept() {
    let lib = std::fs::read_to_string(
        "tests/corpus/snapshots/inline_group/default__rust__src__generated__mod.rs.snap",
    )
    .expect("inline_group lib snapshot missing");
    assert!(
        lib.contains("index_0") && lib.contains("index_1"),
        "inline_group snapshot no longer keeps both spliced members — the [(uint, tstr)] member-drop bug is back"
    );
    let ser = std::fs::read_to_string(
        "tests/corpus/snapshots/inline_group/default__rust__src__generated__serialization.rs.snap",
    )
    .expect("inline_group serialization snapshot missing");
    assert!(
        ser.contains("read_elems(2)"),
        "inline_group deserializer no longer reads 2 elements — the [(uint, tstr)] member-drop bug is back"
    );
}

/// A collapsed map-representation group-choice arm (`{ a: uint // b: tstr }`) stores only its
/// VALUE in the enum, so its fixed member key must be WRITTEN on serialize and VERIFIED on
/// deserialize. The historical miscompile dropped the key entirely — emitting `map(1)` + the bare
/// value (malformed/truncated CBOR) and dispatching decode on the VALUE type — so it round-tripped
/// with itself while rejecting the spec-valid `{"a": n}`/`{"b": s}` form. The multi-field arm
/// (`{ a: uint, x: tstr // b: tstr }`) was broken the same way on the decode side: dispatch keyed
/// on the first VALUE type (uint) instead of the first member KEY type (text "a"). This asserts on
/// the COMMITTED group_choice_map snapshots so neither regression can slip back via an unreviewed
/// re-bless; the *executed* proof is the fixture's emit-tests round-trip in `feature_corpus_compiles`
/// plus the decode-conformance accept vectors on the `group.choice` catalog row (a reverted
/// key-dropping decoder mis-decodes the spec-valid `{"a": n}` foreign bytes and fails the replay
/// gate).
#[test]
fn corpus_group_choice_map_key_written_and_verified() {
    let ser = std::fs::read_to_string(
        "tests/corpus/snapshots/group_choice_map/default__rust__src__generated__serialization.rs.snap",
    )
    .expect("group_choice_map serialization snapshot missing");
    // Serialize side: each collapsed arm writes its fixed member key between the map header and the
    // value (text keys for TextKeyed, uint value-keys for UintKeyed) — dropping any of these is the
    // malformed-CBOR miscompile.
    for key_write in [
        "serializer.write_text(\"a\")?;",
        "serializer.write_text(\"b\")?;",
        "serializer.write_unsigned_integer(1u64)?;",
        "serializer.write_unsigned_integer(2u64)?;",
    ] {
        assert!(
            ser.contains(key_write),
            "group_choice_map serialize no longer writes the collapsed member key `{key_write}` — \
             the map-rep group-choice key-drop miscompile is back"
        );
    }
    // Deserialize side: each collapsed arm reads and VERIFIES its member key (a mismatch is a
    // FixedValueMismatch). These checks vanish if the decoder reverts to dispatching on the value.
    for key_verify in [
        "if a_key != \"a\" {", // TextKeyed A arm
        "if uint_key != 1 {",  // UintKeyed / MixedKeyTypes uint-key arm
        "if text_key != 2 {",  // UintKeyed B arm (uint key 2)
    ] {
        assert!(
            ser.contains(key_verify),
            "group_choice_map deserialize no longer verifies the collapsed member key `{key_verify}` — \
             the decoder is dispatching on the value again, not the key"
        );
    }
    // Multi-field arm: decode must route through the 2-field embedded record (keying on the first
    // member KEY), not dispatch on the first field's VALUE type.
    assert!(
        ser.contains("MultiFieldArm0::deserialize_as_embedded_group"),
        "multi_field_arm no longer decodes via its embedded record — the first-value-type dispatch \
         bug (matching uint before the text key) is back"
    );
}

/// A group-choice arm whose whole content is a FIXED VALUE has no data to store, so its enum
/// variant is FIELD-LESS and its deserializer must construct it by NAMING it (`Ok(T::A)`), never by
/// calling it with a value it never bound (`Ok(T::A(a))`). Three spellings reach this: the keyed
/// map arm (`t = { a: 0 // b: tstr }`, via `make_keyed_map_variant_deser_code`) and the two array
/// arms (`t = [ a: 0 // b: tstr ]`, `t = [ 0 // tstr ]`, via `generate_enum`) — two different
/// callers of the `Fixed` deserialize branch, which is why both are asserted here.
///
/// The failure this pins is not a compile error in THIS crate but an abort while generating: the
/// `Fixed` branch asserts an empty before/after because it only reads and verifies the constant,
/// so a caller that asks it to bind trips `assert_eq!` at generation time. That is why the checks
/// below are about the EMITTED text rather than about a value: by the time a value exists, the
/// generator has already either aborted or emitted the right thing.
///
/// Also asserted: dropping the binding must not have dropped the VERIFICATION. A decoder that
/// stopped checking the constant (or, on the map side, the member key) would still round-trip with
/// its own encoder — the exact blind spot that hid the historical key-drop miscompile — so the
/// wire-level checks are named explicitly. In-process, no nested cargo.
#[test]
fn group_choice_fixed_value_arm_emits_fieldless_variant() {
    use clap::Parser;

    // (label, cddl, variant, the emitted guard proving the constant is still verified)
    let shapes = [
        ("map", "t = { a: 0 // b: tstr }\n", "A", "if a_value != 0 {"),
        (
            "array",
            "t = [ a: 0 // b: tstr ]\n",
            "A",
            "if a_value != 0 {",
        ),
        ("bare", "t = [ 0 // tstr ]\n", "I0", "if i0_value != 0 {"),
    ];
    for (label, spec, variant, value_check) in shapes {
        let path = std::env::temp_dir().join(format!(
            "cddl_codegen_gc_fixed_{label}_{}.cddl",
            std::process::id()
        ));
        std::fs::write(&path, spec).unwrap();

        let emit = |extra: &[&str]| -> String {
            let mut argv = vec![
                "cddl-codegen",
                "--input",
                path.to_str().unwrap(),
                "--output",
                "unused_in_memory_generation",
            ];
            argv.extend_from_slice(extra);
            let cli = crate::cli::Cli::parse_from(argv);
            crate::api::generated_strings(&cli)
                .unwrap_or_else(|e| panic!("{label}: generation failed: {e}"))
                .get("rust/src/generated/serialization.rs")
                .unwrap_or_else(|| panic!("{label}: no rust serialization.rs emitted"))
                .clone()
        };

        let default = emit(&[]);
        assert!(
            default.contains(&format!("Ok(T::{variant})")),
            "{label}: default profile must construct the field-less variant as `Ok(T::{variant})`"
        );
        assert!(
            !default.contains(&format!("Ok(T::{variant}(")),
            "{label}: default profile constructs `Ok(T::{variant}(…))` — a field-less variant is \
             being called with a value that was never bound"
        );
        assert!(
            default.contains(value_check),
            "{label}: default profile no longer verifies the arm's fixed value (`{value_check}`) — \
             dropping the binding must not drop the check"
        );

        // Preserve keeps its encoding fields, so it binds and builds a STRUCT variant. This shape
        // generated under preserve long before it did under default; the arm must stay untouched.
        let preserve = emit(&["--preserve-encodings", "true"]);
        assert!(
            preserve.contains(&format!("Ok(Self::{variant} {{")),
            "{label}: preserve profile must still build the struct variant with its encoding fields"
        );

        // Map rep only: the collapsed arm stores no value at all now, so the member key is the ONLY
        // thing on the wire. Losing either half re-emits malformed CBOR that round-trips with itself.
        if label == "map" {
            assert!(
                default.contains("serializer.write_text(\"a\")?;"),
                "map: serialize no longer writes the collapsed arm's member key"
            );
            assert!(
                default.contains("if a_key != \"a\" {"),
                "map: deserialize no longer verifies the collapsed arm's member key"
            );
        }

        std::fs::remove_file(&path).ok();
    }
}

