/// `@used_as_elem` (comment DSL): a struct rule tagged `@used_as_elem` makes the generator mint the
/// loose-list wasm wrapper (`<Elem>List`, the `[* elem]` equivalent) exactly as an inline `[* elem]`
/// usage would — structural name, `collections.rs` index entry, `own_wrapper_shapes` membership.
/// This replaces a downstream crate's hand-maintained fake structural-named rules. Asserts:
/// (a) the tag ALONE (no inline usage) mints the wrapper under its structural name and indexes it;
/// (b) the tag + an inline `[* elem]` usage define the class exactly ONCE (dedup, no wasm
/// duplicate-symbol); (c) a directly-wasm-exposable element is rejected GRACEFULLY (exit failure +
/// actionable message, never a panic). Bespoke harness (not `run_test`) so it can regen several
/// specs and capture the rejection stderr.
#[test]
fn used_as_elem_mints_loose_list_wrapper() {
    use std::str::FromStr;
    if !tool_exists("cargo") {
        return;
    }
    let base = std::path::PathBuf::from_str("tests/used-as-elem").unwrap();
    let run = |input: &str, output: &str| -> std::process::Output {
        let out_dir = base.join(output);
        let _ = std::fs::remove_dir_all(&out_dir);
        codegen_cmd()
            .arg(format!("--input=tests/used-as-elem/{input}"))
            .arg(format!("--output=tests/used-as-elem/{output}"))
            .arg("--wasm=true")
            .arg("--preserve-encodings=true")
            .output()
            .unwrap()
    };
    let read = |output: &str, rel: &str| -> String {
        std::fs::read_to_string(base.join(output).join(rel)).unwrap()
    };

    // (a) Tag alone: the wrapper is minted under its structural name and indexed, with NO inline use.
    let only = run("tag_only.cddl", "export_tag_only");
    assert!(
        only.status.success(),
        "tag_only generate failed:\n{}",
        String::from_utf8_lossy(&only.stderr)
    );
    let only_mod = read("export_tag_only", "wasm/src/generated/mod.rs");
    assert!(
        only_mod.contains("pub struct BootstrapWitnessList("),
        "the @used_as_elem tag alone must mint the structural loose-list wrapper BootstrapWitnessList"
    );
    let only_index = read("export_tag_only", "wasm/src/generated/collections.rs");
    assert!(
        only_index.contains("pub use crate::generated::BootstrapWitnessList;"),
        "the minted wrapper must appear in the collections.rs re-export index:\n{only_index}"
    );

    // (b) Tag + inline `[* bootstrap_witness]`: the class is defined EXACTLY ONCE (dedup).
    let both = run("tag_and_inline.cddl", "export_tag_and_inline");
    assert!(
        both.status.success(),
        "tag_and_inline generate failed:\n{}",
        String::from_utf8_lossy(&both.stderr)
    );
    let both_mod = read("export_tag_and_inline", "wasm/src/generated/mod.rs");
    assert_eq!(
        both_mod.matches("pub struct BootstrapWitnessList(").count(),
        1,
        "the wrapper must be defined exactly once when the tag AND an inline [* x] usage coexist \
         (dedup via already_generated) — a second definition is a wasm duplicate-symbol"
    );
    assert!(
        read("export_tag_and_inline", "wasm/src/generated/collections.rs")
            .contains("pub use crate::generated::BootstrapWitnessList;"),
        "the wrapper is indexed exactly once regardless of how it was minted"
    );

    // (c) A directly-wasm-exposable element (`coin = uint`) has no wrapper class: reject gracefully.
    let bad = run("exposable.cddl", "export_exposable");
    assert!(
        !bad.status.success(),
        "an exposable @used_as_elem element must fail generation, not silently no-op"
    );
    let bad_stderr = String::from_utf8_lossy(&bad.stderr);
    assert!(
        bad_stderr.contains("directly wasm-exposable")
            && bad_stderr.contains("@used_as_elem")
            && !bad_stderr.to_lowercase().contains("panicked"),
        "the exposable rejection must be graceful and name the tag; stderr:\n{bad_stderr}"
    );
}

/// Plan step 4 (emitted demand assertions): a `@used_as_key ord` root over an extern that supplies
/// Hash+Eq but NOT Ord must (a) emit a named `_demand_keyed` assertion over the tagged type citing the
/// tag, and (b) make the GENERATED crate fail to compile because the extern refuses `Ord`. In the
/// same-crate case the tagged type's OWN `#[derive(Ord)]` is the first failure and rustc's derive
/// error-recovery synthesizes a stub `Ord` that masks the assertion's redundant error; the assertion's
/// distinct cross-crate value (naming the demanding ROOT when the failure surfaces far away) is covered
/// by the CML validation. Here we pin the mechanism that matters in phase 1: the flavor is enforced at
/// the generated crate's compile, and the assertion is emitted well-formed.
#[test]
fn used_as_key_ord_flavor_assertion_fails_on_missing_supply() {
    use std::io::Write;
    use std::str::FromStr;
    if !tool_exists("cargo") {
        return;
    }
    let base = std::path::PathBuf::from_str("tests/used-as-key-flavor").unwrap();
    let out_dir = base.join("export");
    let _ = std::fs::remove_dir_all(&out_dir);
    let gen_out = codegen_cmd()
        .arg("--input=tests/used-as-key-flavor/input.cddl")
        .arg("--output=tests/used-as-key-flavor/export")
        .arg("--wasm=false")
        .output()
        .unwrap();
    assert!(
        gen_out.status.success(),
        "generation must succeed (the supply check is deferred to the generated crate's compile):\n{}",
        String::from_utf8_lossy(&gen_out.stderr)
    );

    // The emitted assertion file must exist and reference the ord carrier over the tagged type.
    let assertions =
        std::fs::read_to_string(out_dir.join("rust/src/generated/key_demand_assertions.rs"))
            .expect("key_demand_assertions.rs must be emitted for a flavored root");
    assert!(
        assertions.contains("_key_demand_ord::<crate::generated::Keyed>();")
            && assertions.contains("fn _demand_keyed()"),
        "the assertion must name the ord carrier and the `_demand_<rule>` fn naming the tagged \
         rule (the file is banner-only — no per-fn comment, which would strand into a \
         preservation-overlay trap on tag deletion):\n{assertions}"
    );

    // Inject a hand-written `Value` extern that supplies Hash+Eq but deliberately NOT Ord.
    let mut lib_rs = std::fs::OpenOptions::new()
        .append(true)
        .open(out_dir.join("rust/src/lib.rs"))
        .unwrap();
    lib_rs
        .write_all(
            b"\nuse serialization::*;\n\n\
            #[derive(Clone, Debug, Eq, PartialEq, Hash)]\n\
            pub struct Value(pub u64);\n\
            impl cbor_event::se::Serialize for Value {\n\
                fn serialize<'se>(&self, serializer: &'se mut cbor_event::se::Serializer) -> cbor_event::Result<&'se mut cbor_event::se::Serializer> {\n\
                    serializer.write_unsigned_integer(self.0)\n\
                }\n\
            }\n\
            impl serialization::Deserialize for Value {\n\
                fn deserialize(raw: &mut cbor_event::de::Deserializer) -> Result<Self, error::DeserializeError> {\n\
                    Ok(Value(raw.unsigned_integer()?))\n\
                }\n\
            }\n",
        )
        .unwrap();
    std::mem::drop(lib_rs);

    let build = tool_cmd("cargo")
        .arg("build")
        .current_dir(out_dir.join("rust"))
        .output()
        .unwrap();
    assert!(
        !build.status.success(),
        "the generated crate must fail to compile: `Value` supplies no `Ord` but `keyed` demands it"
    );
    let stderr = String::from_utf8_lossy(&build.stderr);
    assert!(
        stderr.contains("Value") && stderr.contains("Ord"),
        "the compile failure must be the missing `Ord` supply on the extern the flavor demands; \
         stderr:\n{stderr}"
    );
}

/// The dcSpark `cddl` fork (already this crate's parser dep) as a test dependency of a *generated*
/// crate, so its round-trips gain the independent conformance oracle (tests/deser_test_conformance.rs).
/// Pinned to the same rev as Cargo.toml — enforced by `cddl_oracle_dep_rev_matches_cargo_toml` below,
/// so a routine cddl bump that updates only Cargo.toml can't silently leave the oracle on a stale rev.
const CDDL_ORACLE_DEP: &str = "\ncddl = { git = \"https://github.com/dcSpark/cddl\", rev = \"ac1b98ec07184236517da4511b1bbea239e35190\" }\n";

#[test]
fn cddl_oracle_dep_rev_matches_cargo_toml() {
    let cargo_toml = include_str!("../../Cargo.toml");
    // the git-dep line (not the `repository = ".../cddl-codegen"` line, which also contains the URL)
    let rev = cargo_toml
        .lines()
        .find(|l| l.contains("dcSpark/cddl\"") && l.contains("rev = \""))
        .and_then(|l| l.split("rev = \"").nth(1))
        .and_then(|s| s.split('"').next())
        .expect("could not find the dcSpark/cddl git-dep rev in Cargo.toml");
    assert!(
        CDDL_ORACLE_DEP.contains(rev),
        "CDDL_ORACLE_DEP is out of sync with Cargo.toml's cddl rev ({rev}) — update the const so the \
         generated-crate conformance oracle validates against the same fork/rev as the generator's parser"
    );
}

fn cddl_oracle_dep_rev() -> &'static str {
    CDDL_ORACLE_DEP
        .split("rev = \"")
        .nth(1)
        .and_then(|s| s.split('"').next())
        .expect("CDDL_ORACLE_DEP must contain a rev")
}

fn rust_source_string_literal(s: &str) -> String {
    format!("{s:?}")
}

fn oracle_fingerprint_probe_string<'a>(probe: &'a serde_json::Value, field: &str) -> &'a str {
    probe
        .get(field)
        .and_then(serde_json::Value::as_str)
        .unwrap_or_else(|| panic!("oracle_fingerprint.json probe has missing/invalid `{field}`"))
}

fn oracle_fingerprint_probe_bool(probe: &serde_json::Value, field: &str) -> bool {
    probe
        .get(field)
        .and_then(serde_json::Value::as_bool)
        .unwrap_or_else(|| panic!("oracle_fingerprint.json probe has missing/invalid `{field}`"))
}

fn oracle_fingerprint_hex_bytes(name: &str, hex: &str) -> Vec<u8> {
    assert!(
        hex.len().is_multiple_of(2),
        "oracle_fingerprint.json probe `{name}` has odd-length cborHex `{hex}`"
    );
    (0..hex.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&hex[i..i + 2], 16).unwrap_or_else(|e| {
                panic!("oracle_fingerprint.json probe `{name}` has invalid cborHex `{hex}`: {e}")
            })
        })
        .collect()
}

fn oracle_fingerprint_byte_slice_literal(bytes: &[u8]) -> String {
    let items = bytes
        .iter()
        .map(|b| format!("0x{b:02x}"))
        .collect::<Vec<_>>()
        .join(", ");
    format!("&[{items}]")
}

fn rust_oracle_fingerprint_preflight(scratch_root: &std::path::Path, target_dir: &std::path::Path) {
    let fingerprint_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("cddl-matrix/oracle_fingerprint.json");
    let fingerprint_text = std::fs::read_to_string(&fingerprint_path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", fingerprint_path.display()));
    let fingerprint: serde_json::Value = serde_json::from_str(&fingerprint_text)
        .unwrap_or_else(|e| panic!("cannot parse {}: {e}", fingerprint_path.display()));
    let probes = fingerprint
        .get("probes")
        .and_then(serde_json::Value::as_array)
        .unwrap_or_else(|| panic!("{} must contain a probes array", fingerprint_path.display()));
    assert!(
        probes.len() >= 5,
        "{} contains only {} probe(s); the oracle fingerprint anti-vacuity floor is 5",
        fingerprint_path.display(),
        probes.len()
    );

    let crate_dir = scratch_root.join("fingerprint_probe");
    let _ = std::fs::remove_dir_all(&crate_dir);
    std::fs::create_dir_all(crate_dir.join("src"))
        .unwrap_or_else(|e| panic!("cannot create {}: {e}", crate_dir.join("src").display()));
    std::fs::write(
        crate_dir.join("Cargo.toml"),
        format!(
            "[package]\nname = \"cddl_oracle_fingerprint_probe\"\nversion = \"0.0.0\"\nedition = \"2021\"\n\n[dependencies]\n{}",
            CDDL_ORACLE_DEP
        ),
    )
    .unwrap_or_else(|e| panic!("cannot write probe Cargo.toml: {e}"));

    let rev = cddl_oracle_dep_rev();
    let mut main_rs =
        String::from("fn main() {\n    let mut failures: Vec<String> = Vec::new();\n");
    for probe in probes {
        let name = oracle_fingerprint_probe_string(probe, "name");
        let spec = oracle_fingerprint_probe_string(probe, "spec");
        let mode = oracle_fingerprint_probe_string(probe, "mode");
        let expect_ok = oracle_fingerprint_probe_bool(probe, "expectOk");
        let why = oracle_fingerprint_probe_string(probe, "why");
        let expected = if expect_ok { "OK" } else { "ERR" };
        match mode {
            "compile" => {
                main_rs.push_str(&format!(
                    "    let observed = cddl::parser::cddl_from_str({}, false).is_ok();\n",
                    rust_source_string_literal(spec)
                ));
                main_rs.push_str(&format!(
                    "    if observed != {expect_ok} {{\n        failures.push(format!(\"  - probe '{{}}': spec {{:?}}; expected {expected}, observed {{}}. {{}}\", {}, {}, if observed {{ \"OK\" }} else {{ \"ERR\" }}, {}));\n    }}\n",
                    rust_source_string_literal(name),
                    rust_source_string_literal(spec),
                    rust_source_string_literal(why)
                ));
            }
            "validate" => {
                let cbor_hex = probe
                    .get("cborHex")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_else(|| {
                        panic!("oracle_fingerprint.json validate probe `{name}` is missing cborHex")
                    });
                let bytes = oracle_fingerprint_hex_bytes(name, cbor_hex);
                main_rs.push_str(&format!(
                    "    let bytes: &[u8] = {};\n    let observed = cddl::validate_cbor_from_slice({}, bytes, None).is_ok();\n",
                    oracle_fingerprint_byte_slice_literal(&bytes),
                    rust_source_string_literal(spec)
                ));
                main_rs.push_str(&format!(
                    "    if observed != {expect_ok} {{\n        failures.push(format!(\"  - probe '{{}}': spec {{:?}} cbor 0x{{}}; expected {expected}, observed {{}}. {{}}\", {}, {}, {}, if observed {{ \"OK\" }} else {{ \"ERR\" }}, {}));\n    }}\n",
                    rust_source_string_literal(name),
                    rust_source_string_literal(spec),
                    rust_source_string_literal(cbor_hex),
                    rust_source_string_literal(why)
                ));
            }
            other => panic!("oracle_fingerprint.json probe `{name}` has unknown mode `{other}`"),
        }
    }
    main_rs.push_str(&format!(
        "    if failures.is_empty() {{\n        println!(\"rust cddl crate fingerprint OK ({{}} probes - CDDL_ORACLE_DEP rev {})\", {});\n    }} else {{\n        eprintln!(\"rust cddl crate fingerprint MISMATCH - failing probe(s):\");\n        for failure in failures {{ eprintln!(\"{{failure}}\"); }}\n        std::process::exit(1);\n    }}\n}}\n",
        rev,
        probes.len()
    ));
    std::fs::write(crate_dir.join("src/main.rs"), main_rs)
        .unwrap_or_else(|e| panic!("cannot write probe main.rs: {e}"));

    let output = tool_cmd("cargo")
        .arg("run")
        .current_dir(&crate_dir)
        .env("CARGO_TARGET_DIR", target_dir)
        .output()
        .unwrap_or_else(|e| panic!("failed to run rust oracle fingerprint probe crate: {e}"));
    let combined = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    if !output.status.success() {
        // Deliberate conflation: a probe-crate BUILD failure (cargo compile error — e.g. a rev
        // bump changed the crate's `cddl_from_str`/`validate_cbor_from_slice` API surface) lands
        // in this same MISMATCH panic as a behavioral mismatch. Both mean "the pinned-oracle
        // contract does not hold at this rev" and both demand the same conscious re-validation;
        // triage which one it is from the attached cargo output below (compile errors vs the
        // probe-name mismatch lines).
        let message = format!(
            "HARNESS FAILURE: rust oracle fingerprint MISMATCH — CDDL_ORACLE_DEP rev {rev} does not \
             behave like the pinned oracle. Failing probe(s):\n{combined}\nThe pinned oracle is the \
             fork's `local-fixes` branch @ ac1b98e, injected through CDDL_ORACLE_DEP. Recover by \
             updating CDDL_ORACLE_DEP only after consciously re-validating the shared probe set in \
             cddl-matrix/oracle_fingerprint.json."
        );
        panic!("{message}");
    }
    print!("{combined}");
}

#[test]
#[ignore = "manual oracle-crate fingerprint preflight: cargo test --bin cddl-codegen rust_oracle_fingerprint -- --ignored --nocapture"]
fn rust_oracle_fingerprint() {
    if !tool_exists("cargo") {
        return;
    }
    let scratch_name = format!(
        "cddl_codegen_rust_oracle_fingerprint_{:016x}",
        checkout_hash()
    );
    let _scratch_lock = acquire_scratch_lock(&scratch_name);
    let root = std::env::temp_dir().join(&scratch_name);
    let _ = std::fs::remove_dir_all(&root);
    let target_dir = root.join("target");
    rust_oracle_fingerprint_preflight(&root, &target_dir);
}

